\includegraphics[width=12.5cm]{Empire} 
\caption{\small A map of the Russian Empire: this is the last map of the \emph{Atlas Russicus} (Saint Petersburg, 1745), and it is drawn using Delisle's method. Bibliothèque
Nationale de France, Département Cartes et Plans.}
 \label{fig:Empire} 
\end{figure}







