\section{Introduction}
In this paper we consider the problem of coded distributed computation over a finite field.  
Coded distributed computing and, in particular, coded distributed matrix multiplication has attracted a large surge of research interest as of late~\cite{LLPPR2018, yma17, dfhjcg2020, YAA2018, DBJMG2018, tldk17,
% sigl22, 
 % sl20, sfsl22,
ylrksa19, jj21, fc21, sma21, rk20, cgw21,jj21a, okk02024,schwartz2024}.
In this paper we will extend the batch matrix multiplication problem in \cite{ylrksa19, jj21}
% ,sl20, sfsl22,  censorhillel2023nearoptimal} 
to the case where there are more workers than there are elements in the field. 
We show that over finite fields, our rook codes can encode \emph{all functions.} We use codes constructed from algebraic function fields. Prior works that use algebraic geometry codes include \cite{fidalgodíaz2024distributed},  \cite{Okko}, \cite{HerA}, and evaluation codes \cite{SecureMatDot}.  

\subsection{Problem Statement}
We are given a function $T$ to evaluate on some $x$ that is inefficient to compute on one master node since 1) $T$ is of high complexity or 2) more simply, $x$ is too large, \emph{e.g.,} $x$ is a large dataset. 
The master node sends the other $N$ nodes in the network some $\tilde x_w$ such that the size $|\tilde x_w| << |x|$ and task the node $w \in [N]$ with computing\footnote{We could in theory consider the $\tau $ that each node $w$ computes to be a different $\tau_w$, but as we will see setting all of the $\tau _w = \tau$ is sufficiently robust to cover all cases of interest to an optimal complexity measure.} $\tau (\tilde x_w)$ where $\tau $ is a smaller computation than the function $T$. The main problem in coded distributed computing is the following: for a network of $N$ nodes find the minimum number of non-faulty nodes needed to return $\tau (\tilde x_w)$ so that we can recover the desired value $T(x)$. 
As is the convention, we consider only linear coding schemes since we need the encoding and decoding procedure at the master node to be as efficient as possible; in particular, we have that the function 
$\texttt{Enc} : (x_1,...,x_k) \mapsto (\tilde x_1,..., \tilde x_N)$
is given by a (full-rank) generator matrix $G_{\mathcal{C}} \in \mathbb{F}^{k \times N}$ so that $\tilde x = x G_\mathcal{C}$. We use the convention that this is an $[n,k]$ code when talking about codes in general and set $n=N$ when talking about nodes; the necessity of this convention will become clear in Section~\ref{sec:sec}. 
We assume the reader has basic familiarity with coding theory; \emph{e.g.,} such as that found in the introductory chapters of \cite{hp03} and \cite{v98}.

The preceding discussion is summarized by the following definition:
\begin{definition}
    The \textbf{recovery threshold} of a function $T$ in a network of $N$ nodes is the smallest number $\mathcal{R}(T,N)$ such that for any subset $S\subset [N]$ of size $\mathcal{R}(T,N)$ the value $T(x) = \texttt{Decode}(\{\tau(\tilde x_s) \}_{s \in S})$ can be recovered by some recovery procedure $\texttt{Decode}$.
    We call the number $N- \mathcal{R}(T,N)$ the \textbf{stragglers}; in classical coding theory, this is referred to as \textbf{erasures}.
    One can generalize this definition to include \textbf{byzantine} nodes as follows: 
    The recovery threshold tolerates $s$ stragglers and $b$ \textbf{byzantine} nodes if for any subset $S\subset [N]$ of size $\mathcal{R}(T,N)+2b$ the value $T(x) = \texttt{Decode}(\{\tau(\tilde x_s) + e_s \}_{s \in S})$ can be recovered if there is at most $b$ many $e_s \neq 0$. We extend the definition to colluding servers in Section~\ref{sec:sec}.
\end{definition}



\section{Hadamard-Shur Product}

 Given two linear codes $\mathcal{C},\mathcal{C}'$ with dimensions parameters $[n,k]$, we define their \textbf{Hadamard-Shur} (HS) product as 
 \begin{equation*}
   \mathcal{C} \circ \mathcal{C}' := \{(a_1b_1,...,a_nb_n) \in \mathbb{F} \mid \vec{a} \in \mathcal{C}, \vec{b} \in \mathcal{C}'\}.
 \end{equation*}
 It is easy to see that this defines another code with parameters $[k',n,d']$ for some $k'=:k(\mathcal{C} \circ \mathcal{C}')$ and $d'=:d(\mathcal{C} \circ \mathcal{C}')$ which we define as the dimension and distance of the resulting code.  
 The \textbf{designed recovery threshold} is defined as the value
 \begin{equation*}
 n- d(\mathcal{C} \circ \mathcal{C}')+1.
 \end{equation*}
 The fact that the designed recovery threshold corresponds to the recovery threshold 
We define the Hadamard-Shur powers as 
\begin{equation*}
    \mathcal{C}^{\circ d} := \mathcal{C} \circ ... \circ \mathcal{C}. 
\end{equation*}
 and the designed recovery threshold is defined as the value
 \begin{equation*}
 n- d(\mathcal{C}^{\circ d})+1 
 \end{equation*}
 in this case.


\begin{remark}
    Informally, the designed recovery threshold and the recovery threshold are equal for almost all of the schemes in this paper. 
\end{remark}
\section{Evaluation Codes and the HS Product}




An \textbf{evaluation code} (over $\mathbb{F}$) is given by the a finite set $D$ and a vector space of functions $V \subset  \mathbb{F}^D $ (where $\mathbb{F}^D$ is the set of all functions $\{f \mid f: D \rightarrow \mathbb{F}\}$), so that 
\begin{equation*}
\mathcal{C}(V,D) := \{ (f(P_1),...,f(P_n) ) \mid f\in V , P_i \in D\}.
\end{equation*}
If $\mathrm{dim}(V) = k$ and $|D| = n$, then $\mathcal{C}(V,D)$ is defined as a linear block code with parameters $[n,k]$ given by the generator matrix defined coordinate-wise as
\begin{equation*}
    (G_{\mathcal{C}(V,D)})_{i,j} = f_i(P_j)
\end{equation*}
where $V  = \left\langle f_1,...,f_k \right\rangle$ and $D = \{P_1,...,P_n\}$. 

Given two functions $f,g \in V$, we can define their product pointwise as 
\begin{equation*}
    (f \cdot g)(x) = f(x)g(x). 
\end{equation*}
We define the tensor product of two vector spaces of functions (with same domains) as 
\begin{equation*}
    V\otimes W := \{f\cdot g \mid f\in V \text{ and } g \in W\}. 
\end{equation*}
Since $V,W$ have the same domain, the evaluation code $\mathcal{C}(V\otimes W, D)$ is well defined. 

The proceeding discussion proves the following simplification for evaluation codes:
\begin{lemma}
We have the following equality between the Hadamard-Shur product and the tensor product of codes:
\begin{equation*}\label{lem:circ_to_ten}
    \mathcal{C}(V, D)\circ \mathcal{C}(W, D) = \mathcal{C}(V\otimes W, D).
\end{equation*}
Simlarly we have that 
\begin{equation*}
    \mathcal{C}(V, D)^{\circ d} = \mathcal{C}(V^{\otimes d} ,  D).
\end{equation*}
\end{lemma}

\section{HS Product of AG Codes}

We provide some background and definitions needed to construct AG codes. 
For a more complete proofs and definitions we refer the reader to \cite{Stichtenoth} and \cite{nied_xing}.
A \textit{function field}\footnote{In general, many authors allow the definition to include transcendence degree higher than 1, but all linear codes can be constructed using only transcendence degree 1, hence the limited scope of the definition.} over $\mathbb{F}$ is a field $\mathcal{F} \supset \mathbb{F}(x)$  that is an algebraic extension of $\mathbb{F}(x)$ (where $\mathbb{F}(x)$ is the field of formal rational functions over $\mathbb{F}$).  
The \textit{places}, denoted $\mathbb{P}_\mathcal{F} \subset 2^{\mathcal{F}}$, of a function field $\mathcal{F}$ is defined as the collection of all subsets, $P \subset \mathcal{F}$, that are a maximal ideal of a maximal local ring $\mathcal{O}_P \subset \mathcal{F}$.
Every such maximal ideal is principle, \emph{i.e.,} generated by a local parameter $P = t\mathcal{O}_P$, and thus, since $\mathcal{O}_P$ is a maximal local ring, we have that $(\forall x  \in \mathcal{F}) \  x \in \mathcal{O}_P \text{ or } x^{-1} \in \mathcal{O}_P$. 
Using these facts we can define a function $v_P: \mathcal{F} \rightarrow \mathbb{Z}$
\begin{equation*}
    v_{P}(x) = n \iff (\exists y \in \mathcal{O}_P \setminus t \mathcal{O}_P) \ x = t^n y  , 
\end{equation*}
and $v_P(0) = \infty$. 

Every element $f \in \mathcal{F}$ can be considered as a function via the \textit{residue class map} defined by
\begin{equation*}
f(P) := 
    \begin{cases}
        f \mod P & \text{ if } f \in \mathcal{O}_P \\ 
        \infty & \text{ otherwise}\\ 
    \end{cases}.
\end{equation*}
A place is called \textit{rational} if $\frac{\mathcal{O}_P}{P\mathcal{O}_P} \cong \mathbb{F}$, where $\frac{\mathcal{O}_P}{P\mathcal{O}_P}$ is the quotient field given by modding $\mathcal{O}_P$ by ${P\mathcal{O}_P}$.
More generally the \textit{degree} of a place, $P$, is the dimension of $\frac{\mathcal{O}_P}{P\mathcal{O}_P}$ when considered as a vector space over $\mathbb{F}$, usually denoted as $[\frac{\mathcal{O}_P}{P\mathcal{O}_P}:\mathbb{F}]$. We can extend the definition of the degree of a place to a divisor by linearity; \emph{i.e.,} $\mathrm{deg}(D) = \sum_{P \in \mathbb{P}_\mathcal{F}} c_P \mathrm{deg}(P)$. 

A \textit{divisor} is an element of the free abelian group generated by the places, \emph{i.e.,} $\mathbb{Z}^{\oplus \mathbb{P}_\mathcal{F}}$. We can order the divisors as follows $D_1 \leq D_2 \iff v_P(D_1) \leq v_P(D_2)$.
Each element of $\mathcal{F}$ has a \textit{principle divisor}, $(x) = \sum_{\mathcal{P \in \mathbb{F}_\mathcal{F}}} v_{P}(x)P$. We define the \textit{Riemann-Roch} of a divisor $G$ as the vector space of functions 
\begin{equation*}
   \mathcal{L}(G) := \{ f \in \mathcal{F} \mid (f) \geq - G \} \cup \{0\}.
\end{equation*}
For a divisor, we define $\ell(D)$ as the dimension of the Riemann-Roch space and we define the \textit{genus} of a function field as the value 
\begin{equation*}
    g := g(\mathcal{F}): =   \max_{ D \in \mathrm{div} (\mathcal{F}) } \{ \mathrm{deg} (D) - \ell (D) + 1  \}
\end{equation*}
We will see that the genus measures exactly how close the recovery threshold of the construction for finite fields can get to the characteristic 0 construction (\emph{e.g.,} Theorem~\ref{thm:main_mat_thm}; see Remark 6.1.5 of \cite{nied_xing}). 

\begin{definition}
    Given two divisors, $G,D$, of a function field, $\mathcal{F}$, where $D = P_1+...+P_n$ for some rational places $P_i$, we define an \textbf{algebraic geometry} code, denoted\footnote{This is the notational convention of \cite{Stichtenoth}; the authors of \cite{nied_xing} instead use the notation $C(P_1,...,P_n; G)$ for this construction.} $\mathcal{C}(G,D)$, as the evaluation code, $\mathcal{C}(V,D')$, where $V = \mathcal{L}(G)$ and $D' = D $.  
\end{definition}


In general, it is difficult to determine the dimension and distance of the HS product general evaluation code, without giving any information about $V$ and $D$; however, the dimension and distance of the HS product of a general Algebraic Geometry code is well known.  
In particular, we have the following: 

\begin{lemma}
We have the following equality between the Hadamard-Shur product and the tensor product of codes:
\begin{equation*}
    \mathcal{C}(G, D)\circ \mathcal{C}(H, D) = \mathcal{C}(G+H, D).
\end{equation*}
Similarly we have that 
\begin{equation*}
    \mathcal{C}(G, D)^{\circ d} = \mathcal{C}(d G ,  D).
\end{equation*}
\end{lemma}


\begin{lemma}
    The designed recovery threshold of the Hadamard-Shur product of two AG codes $\mathcal{C}(G,D),\mathcal{C}(H,D)$ is bounded above by 
\begin{equation*}
n - d (\mathcal{C}(G,D)\circ \mathcal{C}(H,D))+1  \leq   \mathrm{deg}(G+H)+1.
\end{equation*}
\end{lemma}


\begin{lemma}
    \label{lem:key_ag}
    If there exists a function field $\mathcal{F}$ with $n$ rational points and genus $g$, then there exists an HS code with designed recovery threshold
    \begin{equation*}
        n - d(\mathcal{C}(G,D)^{\circ \ell }) +1 = \ell k+g-1. 
    \end{equation*}
\end{lemma}
\begin{proof}
    Theorem 6.1.9 of \cite{nied_xing} gives the result. 
\end{proof}

\section{Log Additive Codes and the Curve Degrees of Evaluation Codes}
    Lemma~\ref{lem:key_ag} gives a recipe for an optimal coded distributed computing scheme which we formalize with the following definition: 
\begin{definition}
    We say that two linear codes $\mathcal{C}_1 , \mathcal{C}_2$ of length $n$ are \textbf{log additive} with respect to one another, denoted $\mathcal{C}_1 \sim \mathcal{C}_2$ if $ d(\mathcal{C}_1 \circ \mathcal{C}_2)\geq d(\mathcal{C}_1)+ d(\mathcal{C}_2) -n $. 
    We abuse notation and call a (single) code $\mathcal{C}$ \textbf{log additive} if $\mathcal{C} \sim \mathcal{C}$. 

    %.  Similarly we say that two linear codes $\mathcal{C}_1 , \mathcal{C}_2$ are \textbf{dimension log additive}, denoted $\mathcal{C}_1 \sim_k \mathcal{C}_2$ if $k(\mathcal{C}_1 \circ \mathcal{C}_2) =k(\mathcal{C}_1)+ k(\mathcal{C}_2) $.
\end{definition}

    Being log additive can also be characterized by the Hamming weight:
\begin{lemma}\label{lem:alt_log}
Let $w (x) $ be the Hamming weight of a code. Then two codes $\mathcal{C}_1 , \mathcal{C}_2$ are log additive if and only if 
\begin{equation*}
    w(x\circ y) \geq d(\mathcal{C}_1 ) + d(\mathcal{C}_2) - n 
\end{equation*}
for all $x \in \mathcal{C}_1, y \in \mathcal{C}_2$.
\end{lemma}
In order to characterize good distributed computing codes we will also need the notion of a genus for a general code: 
\begin{definition}
    The \textbf{(generalized\footnote{This definition is weaker than the stronger definition in \cite{vlanogtsa} which requires that the dual code have a similar bound.}) genus} of a $[n,k,d]$ code is  

    \begin{equation*}
        \mathfrak{g} = n-k+1-d. 
    \end{equation*}
    For AG codes it should be clear that $\mathfrak{g} \leq g$. 
    A \textbf{good distributed computing code for an $\ell$-linear tensor of rank $k$} is a log additive code $\mathcal{C}$ with parameters $[n , k, d]$ and with genus $\mathfrak{g}$ that satisfies the property 
    \begin{equation*}
        \ell \mathfrak{g} \leq  k. 
    \end{equation*}
    % eventually for large enough $i$, where $g_\mathrm{min}(n)$ is the minimum possible genus attainable by a function field with $n$ rational points. 
    \end{definition}

    \begin{theorem}
        A log additive code has a designed recovery threshold equal to 
        \begin{equation*}
            n - d(\mathcal{C}^{\circ \ell}) + 1\leq   \ell k - 1 + \ell \mathfrak{g} .
        \end{equation*}
        In particular, a good distributed computing code has designed recovery threshold
        \begin{equation*}
            n - d(\mathcal{C}^{\circ \ell})+1 \leq   ( \ell +1)k - 1 .
        \end{equation*}
    \end{theorem}
    \begin{proof}
        We prove it for $\ell = 2$. 
        Notice that the designed recovery threshold
        \begin{multline*}
            n  - d(\mathcal{C}^{\circ 2})+1 \leq  2n - d(\mathcal{C}_1)- d(\mathcal{C}_2)  +1  \\ 
            = 2k + 2\mathfrak{g}  -2 +1   = 2k - 2 \mathfrak{g} - 1
        \end{multline*}
        and therefore if $ \mathfrak{g} = n-k+1-d$ we get a recovery threshold of $3k-1$. 
    \end{proof}
   The Hasse-Weil bound for AG codes shows that for a $\ell$-linear tensor, $T$, of rank (see Section~\ref{sec:tensor} for a definition of rank) $R(T) < \frac{|n-q-1|}{ 2 \ell \sqrt{q}}$ the genus becomes the dominant term in the recovery threshold. This motivates looking for log-additive codes of small genus. 
Inspired by the construction \cite{bensasetal} of degree lifted codes to construct new local decodable(/correctable) codes, we show that general evaluation codes with a \textbf{(generalized\footnote{We call it ``generalized'' because we do not need condition 4 in Defition 1.2 of \cite{bensasetal}.}) curve degree function} are log additive. 
