\section{Extending Codes to Vectors}
It is straightforward to prove that any $[n,k,d]_q$-code can be considered as a $[n,k,d]_{q^p}$ code with minimal overhead; in particular, 
\begin{lemma}
    Given an $[n,k,d]_q$ code, one can construct an $[n,k,d]_{q^p}$ with encoding and decoding complexity bounded by at most $p$ times the complexity for $[n,k,d]_q$. 
    More generally, for any algebraic extension $\mathbb{K} \supset \mathbb{F}$ of \emph{any} field $\mathbb{F}$ such that $\mathrm{dim}_\mathbb{F}(\mathbb{K}) = p$, we have that given an $[n,k,d]_\mathbb{F}$ code, one can construct an $[n,k,d]_{\mathbb{K}}$ with encoding and decoding complexity bounded by at most $p$ times the complexity for $[n,k,d]_\mathbb{F}$. 
\end{lemma}
\begin{proof}
    Given some $m \in \mathbb{F}_{q^p}^{k}$, consider is instead as an $p \times k$ matrix in $\mathbb{F}^{p \times k}$ and encode each of the $p$ rows individually. The proof is similar for decoding. 
\end{proof}
\begin{remark}
    The generality is to include characteristic 0 cases like the real and complex fields, where the overhead is at most doubled.  
\end{remark}

\section{Tensors}\label{sec:tensor}
An $\ell$-\textbf{linear tensor}\footnote{It is also common convention to call this form a $(\ell+1)$-tensor if $p>1$. For simplicity we only consider the order of the input and not the output, the more general order output form will be considered in the journal version.} is function 
$T:\mathbb{F}^{m_1} \times ...  \times \mathbb{F}^{m_\ell} \rightarrow \mathbb{F}^p$
which is linear in all of its arguments; \emph{i.e.,} if we fix the values of $x_1,...,x_{i-1},x_{i+1},...,x_{\ell}$, then 
\begin{multline*}
   T(x_1,...,\alpha x_i+ \beta z,..., x_\ell) 
   \\ = 
   \alpha T(x_1,...,x_i,..., x_\ell)  + 
   \beta T(x_1,...,z,..., x_\ell)  , 
\end{multline*}
for all $\alpha ,\beta \in \mathbb{F}$ and  $x_i,z \in \mathbb{F}^{m_i}$.
A tensor $t:\mathbb{F}^{m_1} \times ...  \times \mathbb{F}^{m_\ell} \rightarrow \mathbb{F}^p$ is called a \textbf{rank 1 tensor} if there exists some linear forms $t_i:\mathbb{F}^{m_i} \rightarrow \mathbb{F}$ and a $y \in \mathbb{F}^p$ such that 
\begin{equation*}
    t(x_1,...,x_\ell ) = \left(\prod_{i \in [\ell]} t_i(x_i) \right)y.  
\end{equation*}
The \textbf{tensor rank} of a tensor, $T$, is the smallest number, $R(T)$, such that there exists rank-one tensors $t^{(1)},...,t^{(R(T))}$ such that 
\begin{equation*}
    T(x_1,...,x_\ell) = \sum_{i \in [R(T)]} t^{(i)}(x_1,....,x_\ell).
\end{equation*}

The definition of rank 1 decomposition can be further generalized to a recursive decomposition as follows: given a tensor 
$T:\mathbb{F}^{m_1} \times ...  \times \mathbb{F}^{m_\ell} \rightarrow \mathbb{F}^p$
and a tensor 
$
\tau 
  :\mathbb{F}^{\mu _1} \times ...  \times \mathbb{F}^{\mu _\ell} \rightarrow \mathbb{F}^{\rho }
$
such that $\mu_i < m_i$ and $\rho < p$, we say that $T$ has \textbf{$\tau$-rank} $R_\tau(T)$ if there exists linear functions $\mathcal{E}_i^{(j)}: \mathbb{F}^{m_i}\rightarrow \mathbb{F}^{\mu_i}$ and some linear functions 
$
\mathcal{D}^{(j)}: \mathbb{F}^{\rho} \rightarrow \mathbb{F}^p 
$, where $i \in [\ell]$ and $j \in [R_\tau(T)]$,
such that 
\begin{equation*}
    T(x_1,...,x_\ell) = \sum_{j \in [R_\tau(T)]} \mathcal D^{(j)}(\tau(\mathcal E_1^{(j)}(x_1),...,\mathcal E_\ell^{(j)}(x_\ell))). 
\end{equation*}



\section{Fault Tolerant Matrix Multiplication}

We consider the following problem: given $k $ pairs of matrices 
$$
A_1,B_1,\dots,A_k,B_k,
$$
where  $A_i \in \mathbb{F}^{P \times S}$ and $B_i \in \mathbb{F}^{S \times Q}$ for $i \in [k]$ and a field $\mathbb{F}$, 
compute the products 
$$
A_1 B_1 ,\dots,A_k B_k
$$
in the distributed master worker topology in which the master node  gives  $N$ worker nodes coded matrices of the form 
$$
\tilde A _w = \sum_{i \in [k]} \alpha_{i}^{(w)} A_i  
\in \mathbb{F}^{P \times S}
, \tilde B _w = \sum_{i \in [k]} \beta_{i}^{(w)} B_i
 \in \mathbb{F}^{S \times Q}
$$
where $\alpha_{i}^{(w)} \in \mathbb{F}$ and $w \in [N]$ indexes over the worker nodes. 
We are concerned with the minimum number of worker nodes that need to return their values so that the master can recover the desired products. This will be formalized in Definition~\ref{def:rec_bat}.
Before we move on to constructing the actual codes, we will show that this batch matrix problem is actually the most general form of the distributed matrix multiplication problem since it implicitly solves the \textbf{general matrix-matrix} multiplication problem.
\subsection{General Matrix-Matrix Multiplication}\label{sec:mat_mult_explaination}


Given two matrices
\begin{equation}\label{eq:mat}
    A = \begin{bmatrix}
        A_{1,1} & \dots & A_{1,\zeta}\\
         \vdots & \ddots & \vdots \\
        A_{\chi,1} & \dots & A_{\chi,\zeta}\\
    \end{bmatrix} 
    , \ \ 
    B = \begin{bmatrix}
        B_{1,1} & \dots & B_{1,\upsilon}\\
         \vdots & \ddots & \vdots \\
        B_{\zeta,1} & \dots & B_{\zeta,\upsilon}\\
    \end{bmatrix}, 
\end{equation} with
$A_{i,j} \in \mathbb{F}^{P \times S}$ and $B_{i,j} \in \mathbb{F}^{S \times Q}$, we can take an optimal $(\chi, \upsilon, \zeta)$ fast matrix multiplication tensor, denoted $(\gamma, \delta, \eta)$, of rank $r:=R(\chi, \nu , \zeta )$, {i.e.,} for $t \in [r]$, defined by the equations 
\begin{align}\label{eq:fast_mat}
\begin{split}
\hat A _t = \sum_{i,j \in [\chi] \times [\zeta]} \gamma_{i,j}^{(t)} A_{i,j} , \ \ \hat B _t = \sum_{i,j \in [\zeta ]\times [\upsilon ]} \delta_{i,j}^{(t)} B_{i,j},
\\
\sum_{k \in [\zeta ]}A_{i,k}B_{k,j} = \sum_{t \in [r]} \eta^{(i,j)}_{t} \hat A_{t} \hat B_t ,
\end{split}
\end{align}
with
    and then  $A_i,B_i := \hat{A}_i,\hat{B}_i $ as in \cite{yu_ali_ave_2020}, which shows that the general matrix-matrix multiplication problem reduces exactly to the batch matrix multiplication. It seems that computing the linear functions defined by $\gamma,\delta,$ and $\eta$ is an undesirable overhead, \textit{but one must compute the functions given by $\alpha,\beta$ anyways; in particular, one may compose the $\alpha,\beta$ and the $\gamma, \delta$ so that there is no overhead.} This is made explicit and formalized in Section~\ref{sec:mat_mult}. 
    The number $r$ above is often called the \textit{tensor-rank} or the \textit{bilinear complexity}.

The primary goal of this paper is to generalize the main result of \cite{yu_ali_ave_2020} (which only holds in true generality generally for characteristic zero) to more general cases over finite fields. 
This paper 
overcomes the major obstacle when the field is finite, namely the number of evaluation points (meaning the number of workers) or more generally, the length of the code.  

