\section{Further Applications of the Quantum Dynamic Programming Framework}\label{se:appendix-uniform}

In this section, we describe several problems to which our quantum dynamic programming framework can be applied; refer to \cref{tab:complexities}.
For each of these problems ${\mathcal P}$, we demonstrate the applicability of \cref{thm:quantum-dp-lemma} as follows. 
First, we present the corresponding classical dynamic programming algorithm. In particular, we describe (i) the {\bf subproblems} whose solution is stored in the dynamic programming table, (ii) the {\bf optimal substructure property} of the problem, and (iii) the {\bf overlap} among subproblems. Then, if needed, we transform the recurrence relation of the dynamic programming algorithm in such a way that it matches the pattern of \cref{eq:dynamic-recurrence-generic}, and we define the dependency set $S_{i_1,i_2,\dots,i_k}$, the generating set $C_{i_1,i_2,\dots,i_k}$, the dependency index $h$, and the function $f_{\mathcal P}$. 
Also, we bound the average degree of the dependency digraph $G_{\mathcal{P}}(I)$ in terms of the size of the instances.
Further, we show that the dynamic programming algorithm is simple.
Finally, we bound the time complexity of the functions $f_{\mathcal P}$, $f_C$, and $\gamma$. Altogether, this allows us to the establish our quantum speedups via \cref{thm:quantum-dp-lemma}.

%

\subsection{Computational Geometry}
%

In the following, we will describe several problems within the field of computational geometry.



\subsubsection{Minimum-Weight Triangulation of Convex Polygon}\label{ssc:MWT}

A \emph{triangulation} of a set $S$ of $n$ points in the plane is a maximal plane $n$-vertex graph whose vertices are mapped to the points in $S$.

\problemQuestionOutput{\sc Minimum-weight triangulation of convex polygon (MWT)}%
{A convex polygon $P$ defined by its vertices listed in clockwise order $(v_1,v_2,\dots,v_n)$.}%
{The weight of a triangulation $T$ of $S = \{v_1,v_2,\dots,v_n\}$ of minimum \emph{weight}, defined as the sum of the Euclidean distances of the endvertices of all the edges of $T$.}

\medskip\noindent
Let $T$ be a triangulation of a set of points $S = \{ v_1,\dots,v_n\}$. We denote by $d(v_i,v_j)$ the Euclidean distance between vertices $v_i$ and $v_j$ of $T$.



\medskip\noindent
\textsc{Subproblems}: A subproblem is defined as finding the weight of a minimum-weight triangulation for polygon $(v_i,v_{i+1},\dots,v_{j})$ where $v_i,v_{i+1},\dots,v_{j}$ is a subsequence of (the circular sequence) $v_1,v_2,\dots,v_n$. 
This results in $\frac{n(n-1)}{2}$ subproblems.

\medskip\noindent
\textsc{Optimal substructure}: Let $D$ be a dynamic programming table of size $n \times n$, whose entries $D[i][j]$ store the weight of the minimum-weight triangulation for polygon $(v_i,v_{i+1},\dots,v_{j})$. 
In a minimum-weight triangulation $T$, the edge $(v_1,v_n)$ is part of a triangle with a third vertex $v_r$. The total weight of $T$ is given by:
\begin{equation}\label{eq:MWT}
D[1,n] = \min_{1<r<n} \{d(v_1,v_n) + D[1,r]+D[r,n]\}
\end{equation}

\medskip\noindent
\textsc{Overlapping subproblems}: The value $D[i][j]$ must be accessed to compute all entries $D[k][l]$, where $k<i$ and $j<l$.

\smallskip
\noindent Expanding \cref{eq:MWT} yields the following dynamic programming algorithm for MWT.

\thm{(MWT)}{

\begin{description}
\item[\sc Base case:] If $j= (i +1) \mod (n+1)$, then we have:
\begin{equation*}D[i][j]=d(v_i,v_j)\end{equation*}

\item[\sc Recursive case:] We use the notation $i \prec_r j$ to denote the fact that $v_r$ appears between $v_i$ and $v_j$ when clockwise traversing the boundary of $P$ from $v_i$ to $v_j$.
To compute $D[i][j]$, we need to solve $\bigO(|j-i|)$ subproblems of the form $D[i][r]$ and $D[r][j]$, for all $r$ such that $i \prec_r j$. %
%
In fact, we have:

\begin{equation}\label{eq:DP-MWT}
D[i][j]=\min_{r: i \prec_r j} \{d(v_i,v_j) + D[i][r] + D[r][j]\}    
\end{equation}
\end{description}
}

Clearly, \cref{eq:DP-MWT} matches the pattern of \cref{eq:dynamic-recurrence-generic}. In fact, we can set $S_{i,j}=\{(i,r),(r,j), r : i \prec_r j\}$, $C_{i,j} = \{\{(i,r),(r,j)\}, r :i \prec_r j\}$, $h=2$, and $f_{\mathcal P}(i,j,\{(i,r),(r,j)\}) = d(v_i,v_j) + D[i][r] + D[r][j]$. Note that, MWT is a simple problem, since each entry of $C_{i,j}$ stems from a distinct entry of $S_{i,j}$. 
The time $T_{\mathcal P}$, $T_{f_C}$, and $T_\gamma$ needed for computing quantumly $f_{\mathcal P}$, $f_C$, and 
$\gamma$
is then $O(\log W) = O(\log n)$, 
$O(\log n)$,
and 
$O(\log n)$, respectively. Thus, we have that the time
$T' = T_{f_C} + T_\gamma$ (see the statement of \cref{th:minmax}) is~in~$O(\log n)$.


Finally, we bound the average degree of $\depgr$. Recall that $I = P = (v_1, v_2, \dots, v_n)$. Note that, $|V(\depgr)|$ is the number of subproblems, that is, $n^2$.
Note that, the $n$ nodes of $V(\depgr)$ corresponding to the subproblems $D[0][\cdot]$ have outdegree $0$.
Instead, by the definition of $C_{i,j}$, each node $n_{i,j}$ of $\depgr$ corresponding to a subproblem $D[i][j]$ has outdegree equal to $|j-i|$. Therefore $\sum_{i=1}^{n-1}\sum_{j=i+1}^{n} |j-i| = \frac{n(n-1)(n+1)}{6}$.
It follows that the average degree $\delta$ of $\depgr$ is equal to $\frac{n(n-1)(n+1)2}{6} / \frac{n(n-1)}{2} = \frac{2(n+1)}{3} < n$.


Finally, we compare the current-best classical time bound \cite{KLINCSEK1980121} for the MWT problem with our quantum bound.

\runningtime{(MWT)}{
\textsc{Classical}: $\bigO(n^3)$ time -- $\bigO(n^2)$ space \cite{KLINCSEK1980121}
\\
\\
\textsc{Quantum}: $\tildeO(n^2\sqrt{n})$ time -- $\bigO(n^2)$ space
}

\subsubsection{Segmented Least Squares Problem}\label{ssc: SLS}

Given a set $P$ of $n$ points in the plane, $(x_1, y_1), (x_2, y_2), \dots, (x_n, y_n)$, with $x_1 < x_2 < \dots < x_n$, and a line $l$ defined as $y_l = a_lx_l+b_l$, the sum of the squared error $e_l$ of the line $l$ with respect to $P$ is defined as follows:
\begin{equation*}
    e_l = \sum_{i=1}^{n} (y_i -a_lx_i -b_l)^2
\end{equation*}

\problemQuestionOutput{\sc Segmented Least Squares Problem (SLS)}%
{A set $P$ of $n$ points in the plane, $(x_1, y_1), (x_2, y_2), \dots, (x_n, y_n)$, with $x_1 < x_2 < \dots < x_n$, a constant penalty $C$ for each line}%
{A partition of $P$ into $m$ line segments that minimizes both $\sum_{s=1}^{m} e_m$ and $Cm$} 


\medskip\noindent
Let $D[j]$ denote the minimum penalty for the first $j$ points, $p_1, p_2, \dots, p_j$. Let $e_{i,j}$ denote the minimum error of the best-fit line for the segment containing points $p_i, p_{i+1}, \dots, p_j$. Let $C$ be the cost of adding a new segment (a constant penalty for each segment).


\medskip\noindent
\textsc{Subproblems}: A subproblem is defined as finding the optimal segmented least squares solution for the first $j$ points, where $j$ ranges from $1$ to $n$ (the total number of points).
Hence, we have $\bigO(n)$ subproblems.

\medskip\noindent
\textsc{Optimal substructure}: The optimal solution for $D[j]$ can be constructed from the optimal solutions of smaller subproblems. Specifically, to compute $D[j]$, all possible positions $i$, with $1\leq i \leq j$, where the last segment could begin must be considered.
For each possible starting point $i$ of the last segment, then the optimal solution for the first $j$ points consist of:
\begin{itemize}
    \item The error $e_{i,j}$ of the best-fit line for the segment $p_i, p_{i+1}, \dots, p_j$,
    \item The cost $C$ of adding a new segment, and
    \item The optimal solution for the first $i-1$ points, that is $D[i-1]$.
\end{itemize}
The optimal solution is the minimum over all possible choices of $i$.

\medskip\noindent
\textsc{Overlapping subproblems}: The value $D[j]$ must be accessed to compute all entries $D[k]$, where $j\leq k$.


\smallskip

\noindent This yields the following dynamic programming algorithm for SLS.

\thm{(SLS)}{

\begin{description}
\item[\sc Base case:] For $j = 0$ there are no points and no penalty
\begin{equation*}
D[0] = 0
\end{equation*}


\item[\sc Recursive case:] For $j > 0$, compute:

\begin{equation}\label{eq:DP-SLS}
D[j] = \min_{1 \leq i \leq j} (e_{i,j} + C + D[i-1] )
\end{equation}

\end{description}
}

Clearly, \cref{eq:DP-SLS} matches the pattern of \cref{eq:dynamic-recurrence-generic}. In fact, we have that $S_{j}=\{i: 1\leq i\leq j\}$, $C_{j} = \{\{i\}, 1\leq i \leq j\}$, $h=1$, and $f_{\mathcal P}(i,\{j\}) = e_{i,j} + C + D[i-1]$. Note that, SLS is a simple problem, since each entry of $C_{j}$ stems from a distinct entry of $S_{j}$. The running time for computing $f_{\mathcal P}$, $f_C$, and $_\gamma$ is $\bigO(\log n)$, $\bigO(\log n)$, and $\bigO(\log n)$, respectively. Thus, we have that the time $T'=T_{f_C} +T_{\gamma}$ (see statement of \cref{th:minmax}) is in $\bigO(\log n)$.


Finally, we bound the average degree of $\depgr$. Recall that $I = (P,c)$. Note that, $|V(\depgr)|$ is the number of subproblems, that is, $n$.
Note that, the single node of $V(\depgr)$ corresponding to the subproblem $D[0]$ has outdegree $0$.
Instead, by the definition of $C_{j}$, each node $n_{j}$ of $\depgr$ corresponding to a subproblem $D[j]$ has outdegree equal to $j$. Therefore, we have that $\sum_{j=1}^{n} \deg_{out}(n_{j}) = \frac{n(n+1)}{2}$.
It follows that the average degree $\delta$ of $\depgr$ is equal to $\frac{2n(n+1)}{2}/n = n+1$.


Finally, we compare the current-best classical time bound~\cite{DBLP:journals/cacm/Bellman61a} for the SLS problem with our quantum bound.

\runningtime{(SLS)}{
\textsc{Classical}: $\bigO(n^2)$ time -- $\bigO(n)$  space \cite{DBLP:journals/cacm/Bellman61a}
\\
\\
\textsc{Quantum}: $\tildeO(n\sqrt{n})$ time -- $\bigO(n)$ space
}


\subsubsection{One-Sided Multi-Criteria Boundary Labeling}\label{ssc: MCBL}

Boundary labeling~\cite{bksw-blmearm-07,bnn-eltts-19a,DBLP:journals/jgaa/BenkertHKN09} is a problem in computational geometry motivated from applications in map labeling, where the input consists of a set of $n$ points within a rectangle $R$, e.g., a set of point features in a city map. Each point comes with a specific \emph{label}, e.g., the feature names, which are modeled as unit-height bounding boxes of these names. In the one-sided setting, we further have $n$ uniformly-spaced positions for the labels along one side $a$ of $R$ such that no two labels overlap. A \emph{labeling} $L$ of such an instance consists of a matching between the $n$ feature points and the $n$ labels together with a specific reference point on the label boundary touching $a$ such that each matching pair is connected by \emph{leader} of a specific shape, which indicates the association between a feature and its corresponding label, see \cref{fig:polabeling}. If no two leaders cross, we call $L$ \emph{crossing-free}. Here, we consider orthogonal one-bend leaders (called $po$-leaders~\cite{bnn-eltts-19a}), starting with a segment (called the \emph{hand}) \emph{p}arallel to $a$ in the feature point and ending with a segment (called the \emph{arm}) \emph{o}rthogonal to $a$ in the reference point. The quality of a leader $l$ can be measured by a badness function $bad(l)$ assigning a non-negative badness score to $l$; a common example is the length of the leader or whether it has a bend or not. This leads to the following optimization problem:

\begin{figure}
    \centering
    \includegraphics{polabeling.pdf}
    \caption{Example of a one-sided boundary labeling instance and how the leader $l(p)$ splits it into two subinstances.}
    \label{fig:polabeling}
\end{figure}

%

\problemQuestionOutput{\sc One-Sided Multi-Criteria Boundary Labeling (OSMCBL)~\cite{DBLP:journals/jgaa/BenkertHKN09}}%
{A set $P$ of $n$ points in an axis-aligned rectangle $R$ and $n$ candidate positions for disjoint unit-height labels on one side of $R$, and a given badness function $bad()$.}%
{The minimum total badness $\sum_{l\in L} bad(l)$ overall crossing-free labelings $L$.}




\medskip\noindent
For defining subproblems, assume that $a$ is the right side of $R$ as shown in \cref{fig:polabeling} and consider the leftmost point $p$ of $P$. The leader $l(p)$ connecting to a reference point $r$ splits the instance $I$ into two subinstances, one consisting of the points above the arm of $l(p)$ and the labels above $r$ and one consisting of the points below the arm of $l(p)$ and the labels below $r$. This is due to the fact that the labeling must be crossing free and $l(p)$ connects to the leftmost point of $I$. Obviously the number of feature points and labels in each of the two subsinstances must be equal in order to admit a solution. 


%

\medskip\noindent
\textsc{Subproblems}: $R$ is subdivided into $\bigO(n)$ horizontal strips, defined by the horizontal lines passing through the points in $P$ and the horizontal edges of the labels. To determine an optimal crossing-free labeling all possible choices of the strip $\sigma$ for placing the arm of the leader of $p$ must be considered. Consequently, the subproblems are defined by all possible subsets of contiguous strips between two specified strips $i$ and $j$, which are occupied by the arms of leaders of larger subproblems. This approach results in $\bigO(n^2)$ distinct subproblems. We remark that not all of these subproblems admit a valid solution, in which case the total badness of such a subproblem is defined as $\infty$.

\medskip\noindent
\textsc{Optimal substructure}: An optimal crossing-free labeling $L$ is determined by evaluating, for each possible choice of strip $\sigma$, the optimal leader to $p$ in terms of the badness function whose arm lies within $\sigma$, and recursively computing the optimal crossing-free labelings above and below $\sigma$.

\medskip\noindent
\textsc{Overlapping subproblems}: During the computation and decomposition of subproblems by placing leaders for the points from left to right, subproblems being defined by the same subset of strips can occur several times.

\smallskip

\noindent This yields the following dynamic programming algorithm for OSMCBL with $po$-leaders.

\thm{(OSMCBL with $po$-leaders)}{
Let $D[i][j]$ store the value of the minimum total badness for labeling points in the region between two horizontal strips $i$ (bottom) and $j$ (top). The entries of $D$ can be computes as follows:

\begin{description}
\item[\sc Base case:] If there are no further labels between strips $i$ and $j$, we have:  

$$D[i][j] = 0$$

\item[\sc Recursive case:] Let $S(i, j)$ represent the set of strips lying strictly between $i$ and $j$, excluding $i$ and $j$ themselves. Let $p(i, j)$ denote the $k$-th rightmost point within $S(i, j)$, where $k$ is the number of labels entirely covered by $S(i, j)$. 
It is important to note that we only consider {\em feasible choices} of $\sigma$, where the number of labels above (respectively below) $\sigma$ matches the number of points above (respectively below) it. To compute $D[i][j]$, we use the following recurrence: 
%

$$D[i][j] =
\min_{i < \sigma < j} \left( \text{bad}(l^*(p(i, j), \sigma)) + D[i][\sigma] + D[\sigma][j] \right)$$

where $l^*(p(i, j), \sigma)$ is the optimal leader for the leftmost relevant point $p(i,j)$ in the subproblem, $\sigma$ is a horizontal strip for the placement of the leader’s arm, and bad$(l^*(p(i, j), \sigma))$ is a function that returns the badness score of $l^*(p(i, j), \sigma)$; notice that if $\sigma$ is not a feasible strip we have bad$(l^*(p(i, j), \sigma)) = \infty$ to discard this solution.
\end{description}
}

Before arguing that we can apply \cref{thm:quantum-dp-lemma} we show that the point  $p(i,j)$ can be computed in a quantum way in $\tildeO(\sqrt{n})$ time. %
The set of strips $S(i,j)$ defines an interval of y-coordinates and we can check for each point in $P$ in constant time whether it lies within $S(i,j)$. By putting all $n$ points in superposition we can obtain and mark the points in $S(i,j)$ in constant time. It remains to find the $k$-th rightmost point among the marked ones, which can be done in $\tildeO(\sqrt{n})$ time by iteratively sampling a point from this set and counting the marked points to its right, similarly to median finding using quantum counting and Grover's search~\cite{DBLP:journals/corr/quant-ph-9607014,DBLP:conf/stoc/Grover96}. If there are $k' < k-1$ to the right, we discard them and search for the $(k-k')$-th point in the remaining set. Otherwise we discard all points to the left and repeat the search procedure. 

%

Clearly the recurrence for $D[i][j]$ matches the pattern of \cref{eq:dynamic-recurrence-generic}. In fact, we can set $S_{i,j}=\{(i,\sigma),(\sigma,j): i< \sigma < j\}$, $C_{i,j} = \{\{(i,\sigma),(\sigma,j)\}: i< \sigma < j\}$, $h=2$, and $f_{\mathcal P}(i,j,\{(i,\sigma),(\sigma,j)\}) = \text{bad}(l^*(p(i, j), \sigma)) + D[i][\sigma] + D[\sigma][j]$. 
The definition of $C_{i,j}$ implies that OSMCBL is a simple problem. 
The times $T_{f_C}$ and $T_\gamma$ for computing $f_C$ and $\gamma$ are $O(\log n)$ each. Finally,
assuming that the badness score of any leader is polynomially bounded in the input size (except the special symbol $\infty$ representing infeasible instances), the running time $T_{\mathcal P}$ for computing $f_{\mathcal P}$ is $O(\log n)$. The most critical part is the evaluation of the function bad$(l^*(p(i, j), \sigma))$, since it also includes checking whether $\sigma$ is feasible or not. The score of the leader itself is usually a function that can be evaluated in constant time, as it typically includes only the length of the arm and hand of a leader and whether the leader has a bend or not. The feasibility can be checked in $O(\log n)$ time via two orthogonal range counting queries. For this we use a classical global orthogonal range counting data structure storing the point set $P$, e.g., a range tree which takes $O(n \log n)$ construction time and space and can perform counting queries in $O(\log n)$ time. For the two candidate subproblems $D[i][\sigma]$ and $D[\sigma][j]$ we count the number of points in the rectangle defined by the two strips $i$ and $\sigma$ (or $\sigma$ and $j$) and the x-coordinates of $p(i,j)$ and the right boundary $a$ of $R$. If these numbers do not match the number of labels entirely covered by $S(i,\sigma)$ (or $S(\sigma,j)$) the strip $\sigma$ is not feasible and we assign bad$(l^*(p(i, j), \sigma)) = \infty$. With $\delta = O(n)$ we can now apply \cref{thm:quantum-dp-lemma} and obtain the following speedup.

%


%
%
%
%
%

\runningtime{(OSMCBL with $po$-leaders)}{
\textsc{Classical}: $\bigO(n^3)$ time -- $\bigO(n^2)$ space~\cite{DBLP:journals/jgaa/BenkertHKN09}
\\
\\
\textsc{Quantum}: $\tildeO(n^2\sqrt{n})$ time -- $\bigO(n^2)$ space
}


Benkert et al.~\cite{DBLP:journals/jgaa/BenkertHKN09} also present a dynamic programming algorithm for computing labelings with other leader shapes, namely $do$-leaders with fixed-slope diagonal hand segments. Since the construction of each table entry is similar to the one just described, differing only in the table size, we have described only the $po$-leader case above. However, the same framework can naturally be extended to the $do$-leader case, achieving the same quadratic speedup for the computation of each entry.


