\subsection{Combinatorics and Number Theory}

In the following, we will describe problems that fall within the field of combinatorics and number theory.




\subsubsection{RNA Secondary Structure}\label{ssc: RNA-SS}

Let $\{A,U,C,G\}$ be the set of bases forming a single-stranded RNA molecule.
%
The set of pairs formed by a single-stranded RNA molecule that pairs with itself is called the secondary structure.

Let $S$ be the secondary structure, which must satisfy the following constraints:
    \begin{enumerate}
        \item Pairs are separated by at least four bases.
        \item Pairs consist of either $\{A, U\}$ or $\{C, G\}$.
        \item $S$ is a matching (no base is paired more than once).
        \item No two pairs cross (the structure is non-crossing).
    \end{enumerate}

\problemQuestionOutput{\sc RNA Secondary Structure (RNA-SS)}%
{A single-stranded RNA molecule $B = b_1b_2\dots b_n$, where each $b_i \in \{A, C, G, U\}$}%
{The maximum number of base pairs that can be obtained by a secondary structure $S$ while satisfying the constraints}  



\medskip\noindent
\textsc{Subproblems}: For all $1 \leq i < j \leq n$, a subproblem is defined as finding the maximum number of base pairs in a secondary structure for the subsequence $b_i\dots b_j$ of $B$.
We have $\bigO(n^2)$ subproblems, as we need to solve for all possible pairs $(b_i, b_j)$ where $1 \leq i < j \leq n$.

\medskip\noindent
\textsc{Optimal substructure}: Let $D$ be a dynamic programming table of size $n\times n$, whose entries $D[i][j]$ store the maximum number of base pairs in a secondary structure for the subsequence $b_i\dots b_j$ of $B$.
The optimal solution for $D[i][j]$ can be determined by considering four cases:
\begin{enumerate}
\item $D[i][j] = D[i+1][j-1] +1$ if $(b_i,b_j)$ is a base pair;
\item $D[i][j] = D[i+1][j]$ if $b_i$ is unpaired;
    \item $D[i][j] = D[i][j-1]$ if $b_j$ is unpaired;
    \item $D[i][j] = 1 + D[i][t-1] + D[t+1][j-1]$ if $b_j$ pairs with some base $b_t$ (where $i \leq t < j-4$).
\end{enumerate}
The optimal solution is the maximum over these four cases.

\medskip\noindent
\textsc{Overlapping substructure}: The value $D[k][l]$ must be accessed to compute all entries $D[i][j]$, where $i\leq l <j-5$ and $i+1<k<j-5$.



\smallskip

\noindent This yields the following dynamic programming algorithm for RNA-SS.

\thm{(RNA-SS)}{

\begin{description}
\item[\sc Base case:] Since pairs must be separated by at least four bases, for all $i$ and $j$ where $j - i \leq 4$
\begin{equation*}D[i][j] = 0\end{equation*}


\item[\sc Recursive case:] For all $i$ and $j$ where $j - i > 4$, compute:
\begin{equation}\label{eq:DP-RNA-SS}
D[i][j] = \max \begin{cases}
     D[i+1][j-1] +1 \\
     D[i+1][j] \\
     D[i][j-1] \\
     \displaystyle\max_{i\leq t\leq j-4} \{1 + D[i][t-1] + D[t+1][j-1]\},\text{ where $(b_j,b_t)$ is a valid pair} \\

\end{cases}
\end{equation}
\end{description}
}

Note that, \cref{eq:DP-RNA-SS} can be rewritten as:
$$
D[i][j] = \displaystyle\max_{i\leq t\leq j-4} (\max(D[i+1][j-1] +1, D[i+1][j],
     D[i][j-1],1 + D[i][t-1] + D[t+1][j-1])),
$$
where $(b_j,b_t)$ is a valid pair. Clearly, this equation matches the pattern of \cref{eq:dynamic-recurrence-generic}. In fact, we have that $S_{i,j}=\{(i,t-1),(t+1,j-1): i\leq t\leq j-4\}$, $C_{i,j} = \{\{(i,t-1),(t+1,j-1)\}: i\leq t\leq j-4\}$, $h=2$, and $f_{\mathcal P}(i,j,\{(i,t-1),(t+1,j-1)\}) = 1 + D[i][t-1] + D[t+1][j-1]$. Note that, RNA-SS is a simple problem, since each entry of $C_{i,j}$ stems from a distinct entry of $S_{i,j}$. The running time for computing $f_{\mathcal P}$, $f_C$, and $_\gamma$ is $\bigO(\log n)$, $\bigO(\log n)$, and $\bigO(\log n)$, respectively. Thus, we have that the time $T'=T_{f_C} +T_{\gamma}$ (see statement of \cref{th:minmax}) is in $\bigO(\log n)$.


Finally, we bound the average degree of $\depgr$. Recall that $I = (B)$. Note that, $|V(\depgr)|$ is the number of subproblems, that is, $\bigO(n^2)$.
Note that, the $\bigO(n)$ nodes of $V(\depgr)$ corresponding to the subproblem $D[i][j]$, where $j-i\leq 4$ have outdegree $0$.
Instead, by the definition of $C_{i,j}$, each node $n_{i,j}$ of $\depgr$ corresponding to a subproblem $D[i][j]$ has outdegree equal to $j-i-4$. Therefore, we have that $\sum_{i=1}^{n}\sum_{j=i}^{n-4} (j-i-4) = \frac{n(n^2 - 24n + 131)}{6}$.
It follows that the average degree $\delta$ of $\depgr$ is equal to $\frac{n(n^2 - 24n + 131)}{3}/{n^2}  < n$.


Finally, we compare the current-best classical time bound~\cite{DBLP:books/daglib/0015106} for the RNA-SS problem with our quantum bound.

\runningtime{(RNA-SS)}{
\textsc{Classical}: $\bigO(n^3)$ time -- $\bigO(n^2)$  space \cite{DBLP:books/daglib/0015106}
\\
\\
\textsc{Quantum}: $\tildeO(n^2\sqrt{n})$ time -- $\bigO(n^2)$ space
}



\subsubsection{Rod Cutting}\label{ssc: RC}
\problemQuestionOutput{\sc Rod Cutting (RC)}%
{A rod $r$ of length $n$ and an array $price[\,]$ where $price[i]$ denotes the value of a piece of length $i$}%
{Maximum value obtainable by cutting the rod and selling the pieces} 


\medskip\noindent
\textsc{Subproblems}: A subproblem is defined as computing the maximum value obtainable for a rod of length $j$. Since the rod has length $n$, we have $O(n)$ subproblems.

\medskip\noindent
\textsc{Optimal substructure}: Let $D$ be a dynamic programming table of size $n$ whose entries $D[j]$ store the maximum value obtained for a rod of length $j$.
This can be determined by considering all possible ways to make the first cut.

\medskip\noindent
\textsc{Overlapping substructure}: The value $D[i]$ must be accessed for computing all entries $D[j]$, where $j<i$.

\smallskip

\noindent This yields the following dynamic programming algorithm for RC.

\thm{(RC)}{

\begin{description}
\item[\sc Base case:] For a rod of length $0$, the maximum value is $0$:
\begin{equation*}
D[0] = 0
\end{equation*}

\item[\sc Recursive case:] For a rod of length $j > 0$, the maximum value $D[j]$ is given by:
\begin{equation}\label{eq:DP-RC}
D[j] = \max_{1 \leq i \leq j} (p(i) + D[j-i] )
\end{equation}
\end{description}
}

Clearly, \cref{eq:DP-RC} matches the pattern of \cref{eq:dynamic-recurrence-generic}. In fact, we have that $S_{j}=\{i: 1\leq j\}$, $C_{j} = \{\{i\}, 1\leq i \leq j\}$, $h=1$, and $f_{\mathcal P}(i,\{j\}) = p(i) + D[j-i]$. Note that, RC is a simple problem, since each entry of $C_{j}$ stems from a distinct entry of $S_{j}$. The running time for computing $f_{\mathcal P}$, $f_C$, and $_\gamma$ is $\bigO(\log n)$, $\bigO(\log n)$, and $\bigO(\log n)$, respectively. Thus, we have that the time $T'=T_{f_C} +T_{\gamma}$ (see statement of \cref{th:minmax}) is in $\bigO(\log n)$. Finally, we bound the average degree of $\depgr$. Recall that $I = (n, price[\ ])$. Note that, $|V(\depgr)|$ is the number of subproblems, that is, $\bigO(n)$.
Note that, the single node of $V(\depgr)$ corresponding to the subproblem $D[0]$ has outdegree $0$.
Instead, by the definition of $C_{i}$, each node $n_{i}$ of $\depgr$ corresponding to a subproblem $D[i]$ has outdegree equal to $i$, where $1\leq i \leq n$. Therefore, we have that $\sum_{i=1}^{n} \deg_{out}(n_{i}) = \frac{n(n+1)}{2}$.
It follows that the average degree $\delta$ of $\depgr$ is equal to $\frac{n(n+1)}{n} \leq n+1$.


Finally, we compare the current-best classical time bound \cite{DBLP:books/daglib/0023376} for the RC problem with our quantum bound.

\runningtime{(RC)}{
\textsc{Classical}: $\bigO(n^2)$ time -- $\bigO(n)$  space \cite{DBLP:books/daglib/0023376}
\\
\\
\textsc{Quantum}: $\tildeO(n\sqrt{n})$ time -- $\bigO(n)$ space
}


\subsubsection{Largest Divisible Subset in Array}\label{ssc: LDS}
Given $n$ integers, a subset $S\subseteq n$ is called {\em divisible} if for every pair $(x,y)\in S$, either $x$ divides $y$ or $y$ divides $x$.

\problemQuestionOutput{\sc Largest Divisible Subset in Array (LDS)}%
{A sorted array $A$ of integers of $n$ elements}%
{Size of the largest divisible subset $S$}  


\medskip\noindent
\textsc{Subproblems}: A subproblem is defined as finding the largest divisible subset $S_i$ ending at $A[i]$. Since there are $n$ integers in $A$, we have $\bigO(n)$ subproblems.

\medskip\noindent
\textsc{Optimal substructure}: Let $D$ be a dynamic programming table of size $n$, whose entries $D[i]$ store the size of the largest divisible subset ending at $A[i]$. Consider the size of the largest divisible set ending at $A[j]$ then $D[j]$ is either itself (if no previous element divides it) or $D[j]+1$.

\medskip\noindent
\textsc{Overlapping substructure}: The value $D[i]$ must be accessed to compute all entries $D[j]$, where $1\leq i \leq j$.

\smallskip

\noindent This yields the following dynamic programming algorithm for RC.

\thm{(LDS)}{

\begin{description}
\item[\sc Base case:] Each element is trivially a divisible subset of size $1$, hence for each element $j \in A$
\begin{equation*}
D[i] = \{A[i]\}
\end{equation*}

\item[\sc Recursive case:] For each $j$, with $1\leq j\leq n-1$:
\begin{equation}\label{eq:DP-LDS}    
D[j] =\max_{i \text{ s.t. } A[i]|A[j]}(1,D[i]+1)
\end{equation}


\end{description}
}

Clearly, \cref{eq:DP-LDS} matches the pattern of \cref{eq:dynamic-recurrence-generic}. In fact, we have that $S_{i}=\{j: A[j] | A[i]\}$, $C_{i} = \{\{j\}: A[j] | A[i]\}$, $h=1$, and $f_{\mathcal P}(i,\{j\}) = (1,D[j]+1)$. Note that, LDS is a simple problem, since each entry of $C_{i}$ stems from a distinct entry of $S_{i}$. The running time for computing $f_{\mathcal P}$, $f_C$, and $_\gamma$ is $\bigO(\log n)$, $\bigO(\log n)$, and $\bigO(\log n)$, respectively. Thus, we have that the time $T'=T_{f_C} +T_{\gamma}$ (see statement of \cref{th:minmax}) is in $\bigO(\log n)$. 

Finally, we bound the average degree of $\depgr$. Recall that $I = (n,A)$. Note that, $|V(\depgr)|$ is the number of subproblems, that is, $n$.
Note that, the $1$ node of $V(\depgr)$ corresponding to the subproblem $D[0]$ have outdegree $0$.
Instead, by the definition of $C_{j}$, each node $n_{j}$ of $\depgr$ corresponding to a subproblem $D[j]$ has outdegree equal to $i$. Therefore, we have that $\sum_{i=1}^{n} \deg_{out}(n_{i}) = \frac{n(n+1)}{2}$.
It follows that the average degree $\delta$ of $\depgr$ is equal to $\frac{n(n+1)}{n} \leq n+1$.


Finally, we compare the current-best classical time bound~\cite{LDS} for the LDS problem with our quantum bound.


\runningtime{(LDS)}{
\textsc{Classical}: $\bigO(n^2)$ time -- $\bigO(n)$ space \cite{LDS}
\\
\\
\textsc{Quantum}: $\tildeO(n\sqrt{n})$ time -- $\bigO(n)$ space
}

\subsubsection{Text Segmentation Problem}\label{ssc: TSP}

Let $\texttt{IsWord()}$ be an algorithm that, given a dictionary $L$ and string $s$ output $\texttt{True}$ if $s\in L$ and $\texttt{False}$ otherwise.

\problemQuestionOutput{\sc Text Segmentation Problem (TextSeg)}%
{A string $A$, a dictionary $L$, and a subroutine $\texttt{IsWord()}$.}%
{A boolean value equals to $\texttt{True}$ if $A$ can be partitioned into a sequence of words $w_1,\dots,w_l\ |\ w_i\in L, \forall i = 1,\dots, l$, $\texttt{False}$ otherwise.}


\medskip\noindent


\medskip\noindent
\textsc{Subproblems}: A subproblem is defined as determined if the suffix $A[i\dots n]$ of $A$ can be partitioned into a sequence of words from $L$. Since $A$ have at most $n$ suffices, we have $n$ subproblems.


\medskip\noindent
\textsc{Optimal substructure}: Let $D$ be a dynamic programming table of size $n$, whose entries $D[i]$ store a boolean value equals to $\texttt{True}$ if $A[i\dots n]$ can be partitioned into a sequence of words contained in the dictionary, $\texttt{False}$ otherwise.
Consider the entry $D[i]$, containing the value relative to the suffix $A[i\dots n]$. It's value is $\texttt{True}$ if there exists an $j>j$ such that $A[i\dots j] \in L$ and $D[j+1] = \texttt{True}$.


\medskip\noindent
\textsc{Overlapping substructure}: The value $D[j]$ must be accessed to compute all entries $D[i]$, where $i<j$.

\smallskip

\noindent This yields the following dynamic programming algorithm for \textsc{TextSeg}.

\thm{(\textsc{TextSeg})}{

\begin{description}

\item[\sc Base case:] If $i > n$, then $D[i] = \texttt{True}$ because an empty string can be trivially partitioned.

\item[\sc Recursive case:] For each position $i$ in $A$, we check all possible ways to split the suffix $A[i\dots n]$ into words:
\begin{equation}\label{eq:DP-TSP}
D[i] = \bigvee_{j=i}^{n} ( \texttt{IsWord}(A[i\dots j]) \wedge D[j+1] )
\end{equation}

\end{description}
}

Clearly, \cref{eq:DP-TSP} matches the pattern of \cref{eq:dynamic-recurrence-generic}. In fact, we have that $S_{i}=\{j: i<j\}$, $C_{i} = \{\{j\}: i<j\}$, $h=1$, and $f_{\mathcal P}(i,\{j\}) = ( \texttt{IsWord}(A[i\dots j]) \wedge D[j+1])$. Note that, TSP is a simple problem, since each entry of $C_{i}$ stems from a distinct entry of $S_{i}$. The running time for computing $f_{\mathcal P}$, $f_C$, and $_\gamma$ is $\bigO(\log n)$, $\bigO(\log n)$, and $\bigO(\log n)$, respectively. Thus, we have that the time $T'=T_{f_C} +T_{\gamma}$ (see statement of \cref{th:minmax}) is in $\bigO(\log n)$. 



Finally, we bound the average degree of $\depgr$. Recall that $I = (A,L,\texttt{IsWord()})$. Note that, $|V(\depgr)|$ is the number of subproblems, that is, $n$.
Note that, the $1$ node of $V(\depgr)$ corresponding to the subproblem $D[n]$ have outdegree $0$.
Instead, by the definition of $C_{i}$, each node $n_{i}$ of $\depgr$ corresponding to a subproblem $D[i]$ has outdegree equal to $n-i$. Therefore, we have that $\sum_{i=1}^{n} \deg_{out}(n_{i}) = \frac{n(n-1)}{2}$.
It follows that the average degree $\delta$ of $\depgr$ is equal to $\frac{n(n-1)}{n} \leq n+1$.


Finally, we compare the current-best classical time bound~\cite{DBLP:books/x/E2019} for the \textsc{TextSeg} problem with our quantum bound.

\runningtime{(\textsc{TextSeg})}{
\textsc{Classical}: $\bigO(n^2)$  time -- $\bigO(n)$ space \cite{DBLP:books/x/E2019}
\\
\\
\textsc{Quantum}:  $\tildeO(n\sqrt{n})$ time -- $\bigO(n)$ space
}


