\subsubsection{Unbounded Knapsack Problem}\label{ssc: UKP}

\problemQuestionOutput{\sc Unbounded Knapsack (UKP)}%
{A set $N$ of $n$ items, each with a weight $w_i, i=1,\dots,n$ and a value $v_i, i=1,\dots,n$ and a knapsack of capacity $W$}%
{The maximum value that can be achieved by choosing a subset $S\subseteq N$ such that $\sum_{j\in S} p_j \leq W$, where the value is equal to $\sum_{j\in S} v_j$.}

\medskip\noindent


\medskip\noindent
\textsc{Subproblems}: A subproblem is defined as finding the maximum value achievable with a knapsack of capacity $i$, with $i\leq W$. It is evident that we have $W$ subproblems.


\medskip\noindent
\textsc{Optimal substructure}: Let $D$ be a dynamic programming table of size $W$, whose entries $D[i]$ store the maximum value achievable with a knapsack of capacity $i$. Consider a subproblem of capacity $i$ whose value is stored in $D[i]$ and consider each item $j$ such that $w_j< i$. Entry $D[i]$ can be computed by computing the best item value $v_j$ to add, with $w_j<i$, to maximize $D[i-p_j]+v_j$.


\medskip\noindent
\textsc{Overlapping substructure}: The value $D[i]$ must be accessed to compute all entries $D[k]$, where $i<k$ and there exist at least an item $j$ such that $k-w_j = i$.

\smallskip

\noindent This yields the following dynamic programming algorithm for UKP.

\thm{(UKP)}{
\begin{description}
\item[\sc Base case:] If $i = 0$: 
\begin{equation*}
    D[i] = 0
\end{equation*}

\item[\sc Recursive case:] For each capacity $i \leq W$:
\begin{equation}\label{eq:DP-UKP}
D[i] = \max_{j: w_j \leq i} \{ D[i - w_j] + v_j \}.
\end{equation}
\end{description}
}

Clearly, \cref{eq:DP-UKP} matches the pattern of \cref{eq:dynamic-recurrence-generic}. In fact, we have that $S_{i}=\{j: w_j\leq i\}$, $C_{i} = \{\{j\}: w_j\leq i\}$, $h=1$, and $f_{\mathcal P}(i,\{j\}) = D[i - w_j] + v_j$. Note that, UKP is a simple problem, since each entry of $C_{i}$ stems from a distinct entry of $S_{i}$. The running time for computing $f_{\mathcal P}$, $f_C$, and $_\gamma$ is $\bigO(\log n)$, $\bigO(\log n)$, and $\bigO(\log n)$, respectively. Thus, we have that the time $T'=T_{f_C} +T_{\gamma}$ (see statement of \cref{th:minmax}) is in $\bigO(\log n)$. 



Finally, we bound the average degree of $\depgr$. Recall that $I = (N,W)$. Note that, $|V(\depgr)|$ is the number of subproblems, that is, $W$.
Note that, the $1$ node of $V(\depgr)$ corresponding to the subproblem $D[0]$ have outdegree $0$.
Instead, by the definition of $C_{i}$, each node $n_{i}$ of $\depgr$ corresponding to a subproblem $D[i]$ has outdegree (at most) equal to $n$. Therefore, we have that $\sum_{i=0}^{W} \deg_{out}(n_{i}) = nW$.
It follows that the average degree $\delta$ of $\depgr$ is equal to $\frac{2nW}{W} \leq 2n$.

Finally, we compare the current-best classical time bound~\cite{DBLP:books/daglib/0017733} for the UKP problem with our quantum bound.

\runningtime{(UKP)}{
\textsc{Classical}: $\bigO(Wn)$ time -- $\bigO(W)$ space \cite{DBLP:books/daglib/0017733}
\\
\\
\textsc{Quantum}: $\tildeO(W\sqrt{n})$ time -- $\bigO(W)$ space
}


\subsection{Optimal Paths}

In the following, we will describe two Optimal-Path problems.

\subsubsection{All-Pairs Shortest Paths via Matrix Multiplication}\label{ssc: APSP_Matrix}


Let $G=(V,E)$ be a weighted $n$-vertex $m$-edge digraph, where each arc $e = uv \in E$, directed from $u$ to $v$, has an associated weight $w(e)$. Let $p = (u_0,u_1,\dots,u_k)$ be a directed path from $u_0$ to $u_k$. 
The \emph{weight} of $p$ is 
$\sum_{(u_iu_{i+1}) \in E(p)} w(u_i u_{i+1})$, and the \emph{length} of $p$ is~$|E(p)| = k$. 
A \emph{shortest path} from $u$ to $v$ is a minimum-weight directed path from $u$ to $v$. 
The \emph{shortest path distance} from $u$ to $v$ is the weight of a shortest path from $u$ to $v$.

\problemQuestionOutput{\sc All-Pairs Shortest Paths (APSP) via Matrix Multiplication}%
{A weighted digraph $G=(V,E)$, a function $w: E \rightarrow \mathbb R$.}%
{The shortest-path distances between every pair of vertices $v_i,v_j\in V\times V$.}


\medskip\noindent


\medskip\noindent
\textsc{Subproblems}: For a fixed $l$, for all $v_i,v_j \in V\times V$, a subproblem is defined as the shortest path distance between vertices $v_i$ and $v_j$ using at most $l$ edges.
We have $\bigO(n^2)$ subproblems.

\medskip\noindent
\textsc{Optimal substructure}: Let $D^l$ be a dynamic programming table of size $n\times n$, whose entries $D^l[i][j]$ store the shortest path distance between vertices $v_i$ and $v_j$ using at most $l$ edges. 
If the shortest path from $v_i$ to $v_j$ use at most $2l$ edges passes through some intermediate vertex $k$, then:
$$
D^{(2l)}[i][j] = \min_{{v_k} \in V} (D^{(l)}[i][k] + D^{(l)}[k][j])
$$
This shows that the shortest path using at most $2l$ edges can be determined from two shorter paths using at most $l$ edges each.

\smallskip\noindent
\textsc{Overlapping substructure}: The value $D^{l}[i][j]$ must be accessed to compute all entries $D^{2l}[g][k]$, where $g\leq i \leq j \leq k$.

\noindent This yields the following dynamic programming algorithm for APSP using matrix multiplication.

\thm{(APSP via Matrix Multiplication)}{

\begin{description}
\item[\sc Base case:] For $l=0$, for each $v_i,v_j \in V\times V$:
\begin{equation*}
D^{l}[i][i] =  \begin{cases}
     0, \text{ if } i=j,\\
     w(i,j) \text{ if } (i,j)\in E,\\
     \infty \text{ otherwise.}
\end{cases}
\end{equation*}

\item[\sc Recursive case:] Compute the shortest paths iteratively using matrix multiplication with a modified operation:

\begin{equation}\label{eq:DP-APSP}
    D^{(2l)}[i][j] = \min_{{v_k} \in V} (D^{(l)}[i][k] + D^{(l)}[k][j])
\end{equation}


\end{description}
}


Clearly, \cref{eq:DP-APSP} matches the pattern of \cref{eq:dynamic-recurrence-generic}. In fact, we have that $S_{i,j}=\{(i,k),(k,j), v_k \in V\}$, $C_{i,j} = \{\{(i,k),(k,j)\},v_k \in V\}$, $h=2$, and $f_{\mathcal P}(i,j,\{(i,k),(k,j)\}) = D^{(l)}[i][k] + D^{(l)}[k][j]$. Note that, APSP is a simple problem, since each entry of $C_{i,j}$ stems from a distinct entry of $S_{i,j}$. 
The time $T_{\mathcal P}$, $T_{f_C}$, and $T_\gamma$ needed for computing quantumly $f_{\mathcal P}$, $f_C$, and 
$\gamma$
is then $O(\log W) = O(\log n)$, 
$O(\log n)$,
and 
$O(\log n)$, respectively. Thus, we have that the time
$T' = T_{f_C} + T_\gamma$ (see the statement of \cref{th:minmax}) is~in~$O(\log n)$.

Finally, we bound the average degree of $\depgr$. Recall that $I = (G,w)$. Note that, $|V(\depgr)|$ is the number of subproblems, that is, $n^2$.
Note that, the $n$ nodes of $V(\depgr)$ corresponding to the subproblems $D[i][j]$, where $i=j$ or $(i,j)\in E$, have outdegree $0$.
Instead, by the definition of $C_{i,j}$, each node $n_{i,j}$ of $\depgr$ corresponding to a subproblem $D[i][j]$ has outdegree equal to $n$. Therefore $\sum_{i=1}^{n}\sum_{j=1}^{n} n = n^3$.
It follows that the average degree $\delta$ of $\depgr$ is equal to $\frac{2n^3}{n^2} \leq  2n$.


Finally, we compare the current-best classical time bound~\cite{DBLP:journals/jda/HanT16} for the APSP problem with our quantum bound.


\runningtime{(APSP)}{
\textsc{Classical}:  $\bigO(n^3 \log \log n / \log ^2 n)$ time -- $\bigO(n^2)$ space \cite{DBLP:journals/jda/HanT16}
\\
\\
\textsc{Quantum}: $\tildeO(n^2\sqrt{n}\log n)$  time -- $\bigO(n^2)$ space
}



\subsubsection{Viterbi Algorithm}\label{ssc: VA}

A \emph{transition probability} $a_{r,s}$ is the probability of transitioning from state $r$ to state $s$. An \emph{emission probability} $b_{s,o}$ is the probability of observing $o$ at state $s$.

\problemQuestionOutput{\sc Viterbi Algorithm (VA)}%
{A hidden Markov model with a set of hidden states $S$, a sequence of $T$ observations $o_0, o_1, \dots, o_{T-1}$, initial state probabilities $\pi_s$, transition probabilities $a$, and emission probabilities $b$}%
{The most likely sequence of states that could have produced the observations}


\medskip\noindent


\medskip\noindent
\textsc{Subproblems}: For each time step $t \in T$ and hidden state $s_j \in S$, a subproblem is defined as probability of the most probable path ending in state $s_j$ at time $t$. Since we need to compute a probability for each state at each time step, the total number of subproblems is $|S|\times |T|$.


\medskip\noindent
\textsc{Optimal substructure}: Let $D$ be a dynamic programming table of size $|S|\times |T|$ whose entries $D[t][j]$ store the probability of the most probable path ending in state $s_j$ at time $t$.
The most probable path to state $s_j$ at time $t$ depends on the most probable paths to all possible previous states at time $t-1$. This means that:
$$
D[t][j]=\max_{i \in S} (D[t-1][i]\cdot a_{s_i,s_j})\cdot b_{s_j,o_t}
$$

where $a_{s_i,s_j}$ is the transition probability from state $s_i$ to state $s_j$ and $b_{s_j,o_t}$ is the emission probability of observing $o_t$ given state $s_j$. The probability of reaching $s_j$ at time $t$ is computed using optimal probabilities from the previous steps.

\medskip\noindent
\textsc{Overlapping substructure}: The value $D[t-1][i]$ must be accessed multiple times across different transitions $a_{i,j}$.

\smallskip

\noindent This yields the following dynamic programming algorithm for VA.

\thm{(VA)}{

\begin{description}
\item[\sc Base case:] Let $\pi_{j}$ be the initial probability of state $s_j$ and let $b_{s_j,o_1}$ be the probability of emitting the first observation from state $s_j$, then for $t = 1$:
$$
D[1][j] =\pi_j\cdot b_{s_j,o_1}
$$

\item[\sc Recursive case:] For $t > 1$:
\begin{equation}\label{eq:DP-Viterbi}
    D[t][j]=\max_{i \in S} (D[t-1][i]\cdot a_{s_i,s_j})\cdot b_{s_j,o_t}
\end{equation}
\end{description}
}

Clearly, \cref{eq:DP-Viterbi} matches the pattern of \cref{eq:dynamic-recurrence-generic}. In fact, we have that $S_{t,j}=\{(t-1,i), s_i \in S\}$, $C_{t,j} = \{\{(t-1,i)\}, s_i \in S\}$, $h=1$, and $f_{\mathcal P}(t,j,\{(t-1,i)\}) = (D[t-1][i]\cdot a_{s_i,s_j})\cdot b_{s_j,o_t}$. Note that, VA is a simple problem, since each entry of $C_{t,j}$ stems from a distinct entry of $S_{t,j}$. 
The time $T_{\mathcal P}$, $T_{f_C}$, and $T_\gamma$ needed for computing quantumly $f_{\mathcal P}$, $f_C$, and 
$\gamma$
is then $O(\log W) = O(\log n)$, 
$O(\log n)$,
and 
$O(\log n)$, respectively. Thus, we have that the time
$T' = T_{f_C} + T_\gamma$ (see the statement of \cref{th:minmax}) is~in~$O(\log n)$.

Finally, we bound the average degree of $\depgr$. Recall that $I = (S,T,\pi_s,a, b)$. Note that, $|V(\depgr)|$ is the number of subproblems, that is, $|S|\times |T|$.
Note that, the $|S|$ nodes of $V(\depgr)$ corresponding to the subproblems $D[1][\cdot]$, have outdegree $0$.
Instead, by the definition of $C_{t,j}$, each node $n_{t,j}$ of $\depgr$ corresponding to a subproblem $D[t][j]$ has outdegree equal to $|S|$. Therefore $\sum_{t=1}^{|T|}\sum_{j=1}^{|S|} |S| = |T||S|^2$.
It follows that the average degree $\delta$ of $\depgr$ is equal to $\frac{2|T||S|^2}{|T||S|} \leq  2|S|$.


Finally, we compare the current-best classical time bound \cite{DBLP:books/daglib/0004298} for the VA problem with our quantum bound.

\runningtime{(VA)}{
\textsc{Classical}: $\bigO(T \times |S|^2)$  time -- $\bigO(T \times |S|)$ space \cite{DBLP:books/daglib/0004298}
\\
\\
\textsc{Quantum}: $\tildeO(T \times |S| \times \sqrt{|S|})$  time -- $\bigO(T \times |S|)$ space
}


\subsection{Quantum Cocke-Younger-Kasami for Membership in Context-Free Language}\label{sc:CYK}

Let $ G $ be a \emph{Context-Free Grammar} (CFG) in \textbf{Chomsky Normal Form (CNF)}. 
%
A CFG is in CNF if all its production rules are of one of the following forms:
\begin{enumerate*}[label=({\bf \arabic*})]
    \item $ A \rightarrow BC $ where $ A, B, C $ are non-terminals symbols (variables), hence a non-terminal $A$ can be replaced by two other non-terminals symbols,
    \item $ A \rightarrow a $ where $ A $ is a non-terminal and $ a $ is a terminal symbol, hence a non-terminal $A$ can be replaced by a single terminal symbol $a$,
%
\end{enumerate*}
\noindent
Let $L(G)$ be the language composed by all the strings that can be generated by the grammar $G$.

 Next, we define the {\sc Membership in Context-Free Language} problem.

\problemQuestionOutput{\sc Membership in Context-Free Language (MCFL)}%
{A constant size context-free grammar $G$ in CNF and a nonempty string $w=w_1w_2\dots w_n$, where each $w_i$ is a terminal symbol.}%
{A boolean value $\texttt{True}$ if the string $w$ can be derived from the start symbol $S$ of the grammar $G$, i.e. $w \in L(G)$, $\texttt{False}$ otherwise.}


\medskip\noindent
\textsc{Subproblems}: A subproblem is defined as determing whether a substring $w_jw_{j+1}\dots w_l$ can be derived from a non-terminal symbol $A$. Since a string of $n$ symbols has $\binom{n}{2}$ consecutive substrings of length at most $n$, we have $\frac{n(n+1)}{2}$ subproblems.


\medskip\noindent
\textsc{Optimal substructure}: Let $D$ be a dynamic programming table of size $\bigO(n^2)$, whose entries $D[i][j]$ store the set of non-terminals that can generate the substring $w_jw_{j+1}\dots w_{j+i-1}$. Consider the subproblem consisting of the substring $w_jw_{j+1}\dots w_{j+i-1}$, then the set of non-terminals for $D[i][j]$ is obtained as follows:
\begin{itemize}
    \item $D[i][j] = ((B \in D[k][j]) \wedge (C \in D[i-k][j+k]))$, where $1\leq k< i$ and $(A\rightarrow BC) \in G$
\end{itemize}



\medskip\noindent
\textsc{Overlapping subproblems}: The value $D[k][j]$ or $D[i-k][j+k]$ must be accessed to compute all the entries of the form $D[u][l]$, where:
\begin{itemize}
    \item $l=j$ and $k<u$;
    \item $l=j+k$ and $i-k<u$.
\end{itemize}



\smallskip
\noindent
The above yields the following dynamic programming algorithm for MCFL, due to Cocke-Younger-Kasami~\cite{DBLP:journals/iandc/Younger67,kasami1966efficient,cocke1969programming}. 
%
%
%
%
%

\thm{(MCFL)}{
The entries of $D$ can be computes as follows:

\begin{description}
\item[\sc Base case:] if $i=1$:
\begin{equation*}
    D[i][j] = 
        \{A\ |\  (A\rightarrow w_j) \in G\}
\end{equation*}

\item[\sc Recursive case:] if $i<j$:
\begin{equation}\label{eq:DP-CYK}
    D[i][j] =\findAll_{1\leq k< i,\  A\rightarrow BC } ( (B \in D[k][j]) \wedge (C \in D[i-k][j+k]) )
\end{equation}
\end{description}
}


Note that this recursive equation matches the pattern of \cref{eq:dynamic-recurrence-generic} of \cref{thm:quantum-dp-lemma}. Observe that, $w$ can be generated from $G$ if and only if $D[n][1]\neq \{\emptyset\}$.
In particular, we 
have that: $S_{i,j}=\{(k,j),(i-k,j+k): 1\leq k< i\}$, $C_{i,j} = \{\{(k,j),(i-k,j+k)\}: 1\leq k< i\}$, $h=2$, and $f_{\mathcal P}(i,j,\{(k,j),(i-k,j+k)\}) = (B \in D[k][j]) \wedge (C \in D[i-k][j+k])$. Note that, MCFL is a simple problem, since each entry of $C_{i,j}$ stems from a distinct entry of $S_{i,j}$. 
The time needed for computing quantumly $f_{\mathcal P}$, $f_C$, and 
$\gamma$
is then $O(1)$, 
$O(\log n)$,
and 
$O(\log n)$, respectively. Therefore, we have that 
$T' \in O(\log n)$. 

Finally, we bound the average degree of $\depgr$. Recall that $I = (G, w)$. Note that, $|V(\depgr)|$ is the number of subproblems, that is, $\frac{n(n+1)}{2}$.
Note that, the $n$ nodes of $V(\depgr)$ corresponding to the subproblems $D[1][j]$ have outdegree $0$.
Instead, by the definition of $C_{i,j}$, each node $n_{i,j}$ of $\depgr$ corresponding to a subproblem $D[i][j]$ has outdegree equal to $2(i-1)$; refer to \cref{fig:cyk-table}. Therefore, for any $i \in \{1,\dots,n\}$,  we have that $\sum_{j \in [n]} \deg_{out}(n_{i,j}) = 2n(i-1)$. The total number of edges of $\depgr$ is equal to $$\sum_{i=1}^{n} 2n(i-1)=n\sum_{i=1}^{n}(i-1) = 2n(\sum_{i=1}^{n}i-\sum_{i=1}^{n}1)) = 2n(\frac{n(n+1)}{2}-n)) = 2n(\frac{n(n-1)}{2}).$$
It follows that the average degree $\delta$ of $\depgr$ is equal to $$\frac{4n(\frac{n(n-1)}{2})}{\frac{n(n+1)}{2}} = \frac{4n(n-1)}{n+1} = \frac{4n^2}{n+1} - \frac{4n}{n+1} < 4n.$$

Finally, we compare the current-best classical time bound for the MCFL problem with our quantum bound. We remark that the running time of the CYK algorithm is $O(n^3)$ time. 

Valiant demonstrated in 1975 that context-free language recognition can be performed at least as efficiently as Boolean matrix multiplication \cite{DBLP:journals/jcss/Valiant75}. Since Boolean matrix multiplication could be achieved in $\bigO(n^{2.81})$ time using Strassen's algorithm \cite{strassen1970gaussian}, this implied an indirect $\bigO(n^{2.81})$ algorithm for context-free recognition. However, such an algorithm does not allow to directly retrieve the sequence of productions used to derive $w$. The current-fastest classical algorithm for matrix multiplication has a time complexity of $\bigO(n^{2.371552})$ \cite{DBLP:conf/soda/WilliamsXXZ24}, building upon the Coppersmith-Winograd algorithm \cite{DBLP:journals/jsc/CoppersmithW90}. However, the constant factors hidden by the Big O notation are so substantial that these fast matrix multiplication algorithms are impractical for matrix sizes manageable by current computers.

Moreover, our approach significantly simplifies the process. We directly accelerate an ``easy'' algorithm for context-free parsing. In contrast, using matrix multiplication for parsing requires a more complex, three-step process:
\begin{enumerate*}[label=({\bf \arabic*})] \item 
    transforming the parsing instance into a format suitable for matrix multiplication, \item applying the sophisticated (and practically cumbersome) matrix multiplication algorithm described in \cite{DBLP:conf/soda/WilliamsXXZ24}, \item 
    converting the recognition solution (provided by the matrix multiplication) into a parsing solution\footnote{Note that Ruzzo showed parsing is slightly harder than recognition by a logarithmic factor \cite{DBLP:conf/icalp/Ruzzo79}}.
    \end{enumerate*}

Therefore, our algorithm offers a much simpler and more direct approach to context-free parsing compared to methods relying on matrix multiplication.
