\noindent\fbox{%
	\parbox{\columnwidth}{%
		\mysubsection{MCR (Minimum Change Required)}:

		\textbf{Input}: Model $f$, input $\x$, and $d\in\mathbb{N}$.

		\textbf{Output}: \yes{}, if there exists some contrastive reason $S$ such that $|S| \leq d$ for $f(\x)$, and \no{} otherwise.
	}%
}

