    \parbox{\columnwidth}{%
\mysubsection{Weighted Circuit Satisfiability (WCS[$C_{t,d}$])}:

\textbf{Input}: A boolean Circuit $C$ with weft at most $t$ and depth at most $d$, and an integer $k$, 

\textbf{Parameter}: $k$

\textbf{Output}: \yes{}, if $C$ has a satisfying assignment of Hamming weight exactly $k$
