\section{Proof of Proposition~\ref{CC_and_SHAP_proposition}}
\label{pseudo_plynomial_theorem_appendix_section}

\begin{proposition}
\label{pseudo_plynomial_theorem_appendix}
    While the CC and SHAP queries can be solved in pseudo-polynomial time for Perceptrons, ensemble-Perceptrons remain $\#P$-Hard even if the weights and biases are given in unary.
\end{proposition}

%\emph{Proof sketch.} The findings for ensembles are derived from those in Proposition~\ref{main_result_non_paramterized_main_text}. We base the pseudo-polynomial algorithm for CC on the work of~\cite{BaMoPeSu20}. Additionally, we achieve similar outcomes for SHAP using a non-trivial dynamic programming algorithm that solves the SHAP query for Perceptrons in pseudo-polynomial time.

\emph{Proof.} For the \emph{CC} query, we refer to the results from \cite{BaMoPeSu20}, which demonstrated that when the weights and biases are provided in unary, the \emph{CC} query can be solved in polynomial time for perceptrons. However, according to the findings in Proposition~\ref{not_paramaterized_results_appendix}, when the weights and biases are not given in unary, the \emph{CC} query is $\#P$-Complete for \emph{ensembles} of perceptrons.


%For the \emph{CC} query, we rely on the results provided by~\cite{BaMoPeSu20} who showed that given that the weights and biases are given in unary, the \emph{CC} query can be solved in polynomial time for perceptrons. However, relying on the results from proposition~\ref{not_paramaterized_results_appendix} it holds that whhen the weights and biases are not given in unary, then the \emph{CC} query is $\#P$-Complete for \emph{ensembles} consisting of perceptrons.

For the \emph{SHAP} query, we use a proof that was proposed by the work of~\cite{arenas2023complexity} which showed a connection between the computation of shapley values for models (under some mild conditions) and the following portion:

\begin{equation}
H_{\mathcal{D}_p}(f,\x,S,k):=\sum_{S\subseteq[n], |S|=k}\mathbb{E}_{\z\sim \mathcal{D}_p}[f(\z)| \z_S=\x_S]
\end{equation}

Specifically, this relationship applies to models that are \emph{closed under conditioning}, defined as follows:

\begin{definition}
\label{closed_under_conditioning}
    A model $f:\mathbb{F}\to\{0,1\}$ is closed under conditioning if given some assignment $\x\in\mathbb{F}$ and some subset $S\in[n]$, we can construct in polynomial time a function $f':\mathbb{F}\to\{0,1\}$ for which it holds that for all $\y\in\mathbb{F}$: $f'(\y)=f(\x_S;\y_{\Bar{S}})$.
\end{definition}

The connection between models that are closed under conditioning and the computation of $H_{\mathcal{D}_p}$ is as follows~\cite{arenas2023complexity}:

\begin{lemma}
    Let there be a model $f$ which is closed under conditioning. Then solving the \emph{SHAP} query for $f$ and any $i\in[n]$ can be reduced, in polynomial time, to the problem of computing $H_{\mathcal{D}_p}$
\end{lemma}

To apply this lemma to our scenario, we begin by proving the following claim:


\begin{claim}
    Any perceptron $f:=\langle \wb,b\rangle$ is closed under conditioning.
\end{claim}

\emph{Proof.} Given a perceptron $f := \langle \wb, b \rangle$, an assignment $\x \in \mathbb{F}$, and a subset $S \in [n]$, we can construct a second perceptron $f' := \langle \wb', b' \rangle$, where $\mathbf{w}' := \mathbf{w} \cdot \mathbf{1}_{\Bar{S}}$. In other words, we ``zero-out'' all the feature values in $\mathbf{w}$ corresponding to the set $S$ and leave the features in $\overline{S}$ unchanged. Additionally, we define $b' := b + \sum_{i \in S, \x_i = 1} \mathbf{w}_i$. It now holds that for any $\y \in \mathbb{F}$:



%Given a perceptron $f:=\langle \wb,b\rangle$, an assignement $\x\in\mathbb{F}$ and a subset $S\in[n]$, we can construct a second perceptron $f':\langle \wb',b'\rangle$ for which: $\mathbf{w}':=\mathbf{w}\cdot \mathbf{1}_{\Bar{S}}$. In other words, we ``zero-out'' all of the values of features in $\mathbf{w}$ of the set $S$, and leave the features in $\Bar{S}$ as is. Moreover, we define: $b':=b+\sum_{i\in S, \x_i=1}\mathbf{w}_i$. It now holds that for any $\y\in \mathbb{F}$:

\begin{equation}
\begin{aligned}
    f'(\y) = \sum_{i\in[n]}\mathbf{w}'_i\cdot \y_i+b'= \sum_{i\in S}\mathbf{w}'\cdot \y_i+\sum_{i\in \Bar{S}}\mathbf{w}'\cdot \y_i+(b+\sum_{i\in S, \x_i=1}\mathbf{w}_i)=\\
    \sum_{i\in \Bar{S}}\mathbf{w}\cdot \y_i+(b+\sum_{i\in S, \x_i=1}\mathbf{w}_i)=\\ \sum_{i\in \Bar{S}}\mathbf{w}\cdot \y_i+(b+\sum_{i\in S, \x_i=1}\mathbf{w}_i\cdot\x_i+\sum_{i\in S, \x_i=0}\mathbf{w}_i\cdot\x_i)=f(\x_S;\y_{\Bar{S}})
    \end{aligned}
\end{equation}

$\qedsymbol{}$

Now, we only need to prove that when the weights and biases of a perceptron $f$ are given in unary, $H_{\mathcal{D}_p}(S,k)$ can be computed in polynomial time. This will complete our proof that the \emph{SHAP} query can be solved in pseudo-polynomial time for perceptrons. We use the notation $sim(\z,\x)$ to denote the set of features $S$ such that for all $i \in S$, it holds that $\z_i = \x_i$. We begin by demonstrating the following relations:

%Now, we are only left to prove that when the weights and biases of a perceptron $f$ are given in unary, $H_{\mathcal{D}_p}(S,k)$ can be computed in polynomial time. This will conclude our proof that the \emph{SHAP} query can be solved in pseudo-polynomial time for perceprons. We use the notation of $sim(\z,\x)$ to denote the set of features $S$ such that for all $i\in S$ it holds that $\z_i=\x_i$. We start by demonstrating the following relations:

\begin{equation}
\begin{aligned}
H_{\mathcal{D}_p}(S,k):=\sum_{S\subseteq[n], |S|=k}\mathbb{E}_{\z\sim \mathcal{D}_p}[f(\z)| \z_S=\x_S]=\\
\sum_{\z\in\mathbb{F}, |sim(\z,\x)|\geq k}\binom{|sim(\z,\x)|}{k}\cdot \big( \prod\limits_{i\in[n],\z_i=1} \big(p(i)\big) \prod\limits_{i\in[n],\z_i=0} \big(1-p(i))\big)\cdot f(\z)=\\
\sum_{\z\in\mathbb{F}, |sim(\z,\x)|\geq k, f(\z)=1}\binom{|sim(\z,\x)|}{k}\cdot \big( \prod\limits_{i\in[n],\z_i=1} \big(p(i)\big) \prod\limits_{i\in[n],\z_i=0} \big(1-p(i))\big)=\\
\sum_{j=k}^{j=n}\big(\sum_{\z\in\mathbb{F}, |sim(\z,\x)|= j, f(\z)=1}\binom{|sim(\z,\x)|}{k}\cdot \big( \prod\limits_{i\in[n],\z_i=1} \big(p(i)\big) \prod\limits_{i\in[n],\z_i=0} \big(1-p(i))\big)\big)=\\
\sum_{j=k}^{j=n}\binom{j}{k}\big(\sum_{\z\in\mathbb{F}, |sim(\z,\x)|= j, f(\z)=1}\cdot \big( \prod\limits_{i\in[n],\z_i=1} \big(p(i)\big) \prod\limits_{i\in[n],\z_i=0} \big(1-p(i))\big)\big)=\\
\sum_{j=k}^{j=n}\binom{j}{k}\big(\sum_{\z\in\mathbb{F}, |sim(\z,\x)|= j}\cdot \big( \prod\limits_{i\in[n],\z_i=1} \big(p(i)\big) \prod\limits_{i\in[n],\z_i=0} \big(1-p(i))\big)\big)\cdot\mathbf{1}_{\{f(\z)=1\}}=\\
\sum_{j=k}^{j=n}\binom{j}{k}\big(\sum_{\z\in\mathbb{F}, |sim(\z,\x)|= j}\cdot \big( \prod\limits_{i\in[n],\z_i=1} \big(p(i)\big) \prod\limits_{i\in[n],\z_i=0} \big(1-p(i))\big)\big)\cdot\mathbf{1}_{\{\sum_{i=1}^n \mathbf{w}_i\cdot \z_i+b\geq 0\}}
\end{aligned}
\end{equation}

We define $M := \max(\mathbf{w}) + 1$. Next, we define the vector $\mathbf{w}'$ as follows:

