\begin{equation}
\begin{aligned}
\sum_{S\subseteq [n], |S|=j}\mathbf{1}_{\{(\sum_{i\in S} \mathbf{w}_i\cdot \x_i)+(\sum_{i\in \Bar{S}} \mathbf{w}_i\cdot (\neg\x_i))+b\geq 0\}}=\\
\sum_{S\subseteq [n], |S|=j}\mathbf{1}_{\{(\sum_{i\in S,\x_i=1} \mathbf{w}_i)+(\sum_{i\in \Bar{S},\x_i=0} \mathbf{w}_i)+b\geq 0\}}
\end{aligned}
\end{equation}

We move to the second term and prove that the following holds:

\begin{equation}
\begin{aligned}
\sum_{S\subseteq [n], |S|= j}\mathbf{1}_{\{\sum_{i\in S} \mathbf{w}'_i\leq T+M\cdot j\}}=\\ 
\sum_{S\subseteq [n], |S|= j}\mathbf{1}_{\{\sum_{i\in S,\x_i=1} (-\mathbf{w}_i+M)+\sum_{i\in S,\x_i=0} (\mathbf{w}_i+M)\leq T+M\cdot j\}}=\\
\sum_{S\subseteq [n], |S|= j}\mathbf{1}_{\{\sum_{i\in S,\x_i=1} (-\mathbf{w}_i)+\sum_{i\in S,\x_i=0} \mathbf{w}_i\leq T\}}=\\
\sum_{S\subseteq [n], |S|= j}\mathbf{1}_{\{\sum_{i\in S,\x_i=1} (-\mathbf{w}_i)+\sum_{i\in S,\x_i=0} \mathbf{w}_i\leq b+(\sum_{i\in[n],\x_i=0} \mathbf{w}_i)\}}=\\
\sum_{S\subseteq [n], |S|= j}\mathbf{1}_{\{\sum_{i\in S,\x_i=1} (-\mathbf{w}_i)+\sum_{i\in S,\x_i=0} \mathbf{w}_i-\sum_{i\in S,\x_i=0} \mathbf{w}_i- \sum_{i\in \Bar{S},\x_i=0} \mathbf{w}_i\leq b\}}=\\
\sum_{S\subseteq [n], |S|= j}\mathbf{1}_{\{\sum_{i\in S,\x_i=1} \mathbf{w}_i+ \sum_{i\in \Bar{S},\x_i=0} \mathbf{w}_i+b\geq 0\}}
\end{aligned}
\end{equation}

Hence proving the equivalence.

$\qedsymbol{}$


We hence can equivalently derive in that $H_{\mathcal{D}_p}(S,k)$ is equivalent to:

