\begin{equation}
    \begin{aligned}
DP[1][C][1-\ell]=DP[1][C][1]= DP[0][C][0]\cdot (p(1)) + DP[0][C-s_1][0]\cdot p(1)=\\DP[0][C-s_1][0]\cdot (1-p(1))
    \end{aligned}
\end{equation}

If it additionally holds that $s_1\leq C$, then we have:

\begin{equation}
    \begin{aligned}
DP[1][C][1-\ell]=DP[0][C-s_1][0]\cdot (1-p(1))=(1-p(1))=R(\x,\{s_1\},1)
    \end{aligned}
\end{equation}

However, if $s_1> C$ we get that:


\begin{equation}
    \begin{aligned}
DP[1][C][1-\ell]=DP[0][C-s_1][0]\cdot (1-p(1))=0
    \end{aligned}
\end{equation}

as required. For the inductive step, we assume correctness holds for some $i \in \mathbb{N}$ and show that:


\begin{equation}
    \begin{aligned}
        DP[i+1][C][i+1-\ell]:=\\ 
        DP[i][C][j]\cdot p(i) + DP[i][C-\mathbf{w}'_{i+1}][j-1]\cdot (1-p(i)) = \\
    \sum\limits_{|S|\leq i-\ell, |\x_S|_1\leq C}R(k,\x,S,i)\cdot p(i+1) + \\
    \sum\limits_{|S| \leq i-\ell, |\x_S|_1\leq C-\mathbf{w}'_{i+1}}R(k,\x,S,i)\cdot (1-p(i+1))=\\
    \sum\limits_{|S| \leq i-\ell+1, |\x_S|_1\leq C, i+1\not\in S}R(k,\x,S,i)\cdot p(i+1) + \\
    \sum\limits_{|S| \leq i-\ell+1, |\x_S|_1\leq C, i+1\in S}R(k,\x,S,i)\cdot (1-p(i+1))=\\
    R(k,\x,S,i+1)
    \end{aligned}
\end{equation}

$\qedsymbol{}$

We conclude by presenting the complete algorithm described for computing $H_{\mathcal{D}_P}(S,k)$ with the following pseudocode:


\begin{algorithm}
	%\algnewcommand\algorithmicforeach{\textbf{for each}}
	%\algdef{S}[FOR]{ForEach}[1]{\algorithmicforeach\ #1\ \algorithmicdo}
    \newcommand{\algorithmicforeach}{\textbf{for each}}
\newcommand{\ForEach}[2]{\STATE \algorithmicforeach\ #1 \textbf{do} #2}
\newcommand{\Return}[1]{\STATE \textbf{return} #1}
\newcommand{\EndForEach}{\STATE \textbf{end for each}}

	\textbf{Input} $f$, $\x$, $S$, $k$
	\caption{Computing $H_{\mathcal{D}_P}(S,k)$}\label{alg:subset-minimal-local}
	\begin{algorithmic}[1]
 		\STATE $T\gets b+\big(\sum_{i\in[n],\x_i=0} \mathbf{w}_i\big)$
    	\STATE $H_{\mathcal{D}_P}\gets 0$
		\ForEach {$k\leq j \leq n$}\label{lst:line:orderingline}
    	\STATE $H_{\mathcal{D}_P}\gets H_{\mathcal{D}_P}+\binom{j}{k}\cdot(DP[n][T+Mj][j]-DP[n][T+M(j-1)][j-1])$
		\EndForEach
		\STATE \Return $H_{\mathcal{D}_P}$ 
	\end{algorithmic}
\end{algorithm}


