%\begin{equation}
%    \forall \z\in\mathbb{F} \quad [f(\x_{\Bar{S}\cup \{i\}};\z_{S\setminus \{i\}})= f(\x)] 
%\end{equation}

%In other words, $\overline{S}\cup\{i\}=\overline{S\setminus \{i\}}$ is a sufficient reason of $\langle f,\x\rangle$.
%it can be deduced that it is possible to iterate over subsets of $\frac{k}{2}$ decision trees of some ensemble $f$ and compute all subset minimal contrastive reasons of $\langle f,\x\rangle$. This process is performed in FPT time with respect to the parameter $k$. Then, given that we now have all subset minimal contrastive reasons (denoted by $\mathbb{S}$), we can non-deterministically guess a subset $S\subseteq [n]$ and check whether $S$ is a MHS of $\mathbb{S}$ and whether $|S|\leq k$. Hence, from definition, it holds that the \emph{MSR} query for ensembles of $k$-FBDDs is contained in para-NP.


\section{Proof of Proposition~\ref{subset_minimal_proof_main}}
\label{xp_subset_minimal_proof_sec}

\begin{proposition}
\label{xp_subset_minimal_proof}
    Obtaining a subset-minimal sufficient reason for a $k$-ensemble of decision trees is in XP.
\end{proposition}

\emph{Proof.} The specific result aligns with a result demonstrated by~\cite{ordyniak2024explaining}. However, we can further establish this result as a direct extension of the complexity result for the CSR query (Lemma~\ref{k-ensemble-fbdds-csr}), which will demonstrate this result not only for majority voting ensembles. To show this, we use a common greedy algorithm that computes a subset-minimal sufficient reason by invoking a linear number of queries, each checking whether a given subset is a sufficient reason~\cite{ignatiev2019abduction}. Intuitively, the algorithm attempts to ``free'' a feature from the subset $S$ at each iteration, until finally converging to a subset-minimal sufficient reason.

\begin{algorithm}
\label{algorithm_for_paper}
	%\algnewcommand\algorithmicforeach{\textbf{for each}}
	%\algdef{S}[FOR]{ForEach}[1]{\algorithmicforeach\ #1\ \algorithmicdo}
    \newcommand{\algorithmicforeach}{\textbf{for each}}
\newcommand{\ForEach}[2]{\STATE \algorithmicforeach\ #1 \textbf{do} #2}
\newcommand{\Return}[1]{\STATE \textbf{return} #1}
\newcommand{\EndForEach}{\STATE \textbf{end for each}}


	\textbf{Input} $f$, $\x$
	\caption{Greedy Subset Minimal Sufficient Reason Search}\label{alg:subset-minimal-local}
	\begin{algorithmic}[1]
		\STATE $S \gets \{1,\ldots,n\}$
		\ForEach {$i \in \{1,...,n\}$ by some arbitrary ordering}\label{lst:line:orderingline}
		\IF{$S\setminus \{i\}$ is a sufficient reason w.r.t $\langle f,\x\rangle$}\label{lst:line:sufficientline}
		\STATE $S \gets S\setminus \{i\}$
		\ENDIF
		\EndForEach\label{lst:line:endregularupper}
		\STATE \Return $S$ \COMMENT{$S$ is a \emph{subset minimal} sufficient reason}
	\end{algorithmic}
\end{algorithm}

Lemma~\ref{k-ensemble-fbdds-csr} proved that the \emph{CSR} query for an ensemble of decision trees is in coW[1] (and hence is also in XP). In essesnse, algorithm~\ref{algorithm_for_paper} implies that a linear number of queries to the \emph{CSR} query produces a subset-minimal sufficient reason. It hence, directly follows that obtaining some subset minimal sufficient reason for some $\langle f,\x\rangle$ is also in XP.

$\qedsymbol{}$



