\title{Generalized Rellich's lemmas, uniqueness theorem and inside-out duality for scattering poles}
\author{Xiaodong Liu\thanks{Academy of Mathematics and Systems Science,
Chinese Academy of Sciences, Beijing 100190, China. Email: xdliu@amt.ac.cn}
,\and
Jiguang Sun\thanks{Department of Mathematical Sciences, Michigan Technological University, Houghton, MI 49931, USA. Email: jiguangs@mtu.edu}
