% We observe from \eqref{aa} that $\|u\|_{H^1(D)}=0$, which implies $u=0$ in $D$.

% (2) If $\Re k\neq 0$, then $\Im k^2 \neq 0$. Taking the imaginary part on both sides of \eqref{aa} we have $\|u\|_{L^2(D)}=0$, which again yields that $u=0$ in $D$.
% \end{proof}

%\textcolor{red}{Since you have the well-posedness for non-real $k$, Theorem 3.1 is not necessary.}

%Since the spectrum of $-\Delta$ in $D$ with Dirichlet/Neuman condition on $\partial D$ is real, 
For $k\in {\mathbb C}_{-}$, the existence of the solution to the interior boundary value problems \eqref{IDbvp}/\eqref{INbvp} can be easily established by the standard variational method or the integral equation method. Denote by $\Om$ a bounded domain with Lipschitz boundary $\pa\Om$ such that $\ov{\Om}\subset D$.
We define an operator $G$ by
\be\label{G-Def}
Gf=u|_{\pa\Om},
\en
where $u$ is the solution of the boundary value problem \eqref{IDbvp}/\eqref{INbvp}. The interior regularity property implies that the operator $G$ is compact.


Considering the scattering problem due to a point source $\Phi_k(\cdot, y)$ located at $y\in\pa \Om$, let $u^s_k(\cdot, y)$ be the unique solution of the interior boundary value problems \eqref{IDbvp} (or \eqref{INbvp}) with the Dirichlet boundary value $-\Phi_k(\cdot, y)$ (or Neumann boundary value $-\pa \Phi_k(\cdot, y)/\pa\nu$) on $\pa D$.
The following reciprocity relation holds 
\be\label{Reciprocity Relation}
u^s_k(x, y)= u^s_k(y,x),\quad x,y\in D.
\en
Define the near field operator $\mathcal{N}_k: L^2(\pa \Om) \to L^2(\pa \Om)$ such that
\begin{equation}\label{NFoperator}
\Big(\mathcal{N}_k g\Big)(x) = \int_{\pa \Om}u^{s}_k(x,y)g(y)ds(y),\quad x\in \pa\Om.
\end{equation}
Introduce the single layer potential operator $\mathcal {S}_k: L^2(\pa \Om) \to H^1_{loc}(\R^2\ba{\ov{D}})$ such that
\ben
\Big(\mathcal {S}_k g\Big)(x):=\int_{\pa\Om} \Phi_k(x,y)g(y)ds(y),\quad x\in \R^2\ba{\ov{D}}.
\enn

\begin{theorem} \label{S-Properties}
If $k\in {\mathbb C}_{-}$, then the operator $\mathcal {S}_k: L^2(\pa \Om) \to H^1_{loc}(\R^2\ba{\ov{D}})$ is injective. If $k\in {\mathbb C}_{-}$ is not a scattering pole, then $\mathcal {S}_k: L^2(\pa \Om) \to H^1_{loc}(\R^2\ba{\ov{D}})$ has a dense range.
\end{theorem}
\begin{proof}
Given $g\in L^2(\pa \Om)$, define
     \ben
     u_g (x) := \int_{\pa\Om} \Phi_k(x,y)g(y)ds(y),\quad x\in \R^2\ba{\pa \Om}.
     \enn
     Then $u_g$ is a solution to the Helmholtz equation in $\Om$ and in $\R^2\ba\ov{\Om}$ and satisfies the outgoing condition \eqref{outgoing}.
     Let $u_g=\mathcal {S}_k g=0$ in $\R^2\ba\ov{D}$, by the unique continuation principle, we have $u_g=0$ in $\R^2\ba\ov{\Om}$. Furthermore, by the continuation of the single layer potential, we have $u_g=0$ on $\pa \Om$. By Lemma \ref{Uni-Interior}, we have $u_g=0$ in $\Om$. Now the jump relation of the single layer potential implies $g=0$. Hence, the operator $\mathcal {S}_k: L^2(\pa \Om) \to H^1_{loc}(\R^2\ba{\ov{D}})$ is injective.


Next we assume that $k\in \C_{-}$ is not a Dirichlet pole. We introduce an auxiliary operator $A_k: L^2(\pa \Om) \to H^{1/2}(\pa D)$ defined by
       \ben
        \Big(A_k g\Big)(x):=\int_{\pa\Om} \Phi_k(x,y)g(y)ds(y),\quad x\in \pa D.
       \enn
     One has the factorization $\mathcal {S}_k = \mathcal {B}(k)A_k$,  where $\mathcal {B}(k)$ is the scattering operator defined in \eqref{SoluitonOperator}. Note that $\mathcal {B}(k)$ is well-defined since $k\in {\mathbb C}_{-}$ is not a scattering pole. The denseness of the range of $\mathcal {S}_k$ then follows from the fact that the auxiliary operator $A_k$ has a dense range in $H^{1/2}(\pa D)$. Interchanging the order of integration we observe that the adjoint operator $A^\ast_k: H^{-1/2}(\pa D) \to L^2(\pa \Om)$ of $A_k$ is
     defined by
     \ben
     \Big(A^\ast_k h\Big)(y):=\int_{\pa D} \ov{\Phi_k(x,y)}h(x)ds(x),\quad y\in \pa\Om.
     \enn
     Define the single layer potential
     \ben
     v_h(y):=\int_{\pa D}\Phi_k(x,y)\ov{h(x)}ds(x), \quad y\in \R^2\ba\pa D.
     \enn
     Thus $v_h$ is a solution to the Helmholtz equation in both $D$ and $\R^2\ba\ov{D}$ and satisfies the outgoing condition \eqref{outgoing}.
     Letting $A^\ast_k h=0$ on $\pa\Om$, we have $v_h=0$ on $\pa\Om$. Note that $v_h$ is a solution to the Helmholtz equation in $D$,  Lemma \ref{Uni-Interior} yields $v_h=0$ in $\Om$. Then $v_h=0$ in $D$ by analytic continuation. In particular, $v_h=0$ on $\pa D$ in the trace sense. Noting that $v_h$ is also an outgoing solution to the Helmholtz equation in $\R^2\ba\ov{D}$, we have, by the assumption $k\in {\mathbb C}_{-}$ is not a Dirichlet pole, that $v_h=0$ in $\R^2\ba\ov{D}$. Thus, $h=0$ by the jump relation of the single layer potential. That is, the adjoint operator $A^\ast_k$ is injective and therefore the auxiliary operator $A_k$ has a dense range in $H^{1/2}(\pa D)$.

     Finally, we consider the case that $k\in \C_{-}$ is not a Neumann pole. To do so, we introduce another auxiliary operator $B_k: L^2(\pa \Om) \to H^{1/2}(\pa D)$ defined by
       \ben
        \Big(B_k g\Big)(x):=\frac{\pa}{\pa\nu(x)}\int_{\pa\Om} \Phi_k(x,y)g(y)ds(y),\quad x\in \pa D.
       \enn
     Then, we have the factorization $\mathcal {S}_k = \mathcal {B}(k)B_k$. Using the fact that the exterior Neumann problem is well posed if $k$ is not a Neumann pole, the denseness of the range of $\mathcal {S}_k$ follows from the fact that the auxiliary operator $B_k$ has a dense range in $H^{-1/2}(\pa D)$. Interchanging the order of integration, the adjoint operator $B^\ast_k: H^{1/2}(\pa D) \to L^2(\pa \Om)$ of $B_k$ is
     defined by
     \ben
     \Big(B^\ast_k h\Big)(y):=\int_{\pa D} \ov{\frac{\pa\Phi_k(x,y)}{\pa\nu(x)}}h(x)ds(x),\quad y\in \pa\Om.
     \enn
     Define the double layer potential
     \ben
     w_h(y):=\int_{\pa D}\frac{\pa\Phi_k(x,y)}{\pa\nu(x)}\ov{h(x)}ds(x), \quad y\in \R^2\ba\pa D.
     \enn
     Then $w_h$ is a solution to the Helmholtz equation in both $D$ and $\R^2\ba\ov{D}$ and satisfies the outgoing condition \eqref{outgoing}.
     Letting $B^\ast_k h=0$ on $\pa\Om$, we have $w_h=0$ on $\pa\Om$. Note that $w_h$ is a solution to the Helmholtz equation in $D$, Lemma \ref{Uni-Interior} yields $w_h=0$ in $\Om$. Thus $w_h=0$ in $D$ by analytic continuation. In particular, $\frac{\pa v_h}{\pa\nu}=0$ on $\pa D$ in the trace sense. Noting that $w_h$ is also an outgoing solution to the Helmholtz equation in $\R^2\ba\ov{D}$ and $k\in {\mathbb C}_{-}$ is not a Neumann pole, we have that $w_h=0$ in $\R^2\ba\ov{D}$. By the jump relation of the double layer potential $h=0$. That is, the adjoint operator $B^\ast_k$ is injective and therefore $B_k$ has dense range in $H^{-1/2}(\pa D)$.
\end{proof}

We first study the inside-out duality for the case of Dirichlet boundary condition in Section \ref{subsec-D}. The case of Neumann boundary condition is considered in Section \ref{subsec-N}, which is analogous to the Dirichlet case.

\subsection{Dirichlet Case}\label{subsec-D}
Letting $w\in H^1_{loc}(\R^2\ba{\ov{D}})$ be an outgoing solution to the Helmholtz equation in $\R^2\ba{\ov{D}}$, we define the operator $\mathcal {G}_k: H^1_{loc}(\R^2\ba{\ov{D}}) \to L^2(\pa \Om)$ by $\mathcal {G}_k w=u_w|_{\pa \Om}$, where $u_w\in H^1(D)$ solves
\ben
\Delta u_w+k^2 u_w= 0 \quad\text{in } D,\qquad u_w = w|_{\pa D} \quad\text{on } \pa D.
\enn
Assume that $k\in {\mathbb C}_{-}$. Then $\mathcal{N}_k: L^2(\pa \Om) \to L^2(\pa \Om)$ has a factorization
     \be\label{Factorization}
     \mathcal{N}_k=\mathcal{G}_k\mathcal{S}_k.
     \en
Assuming further that $k\in {\mathbb C}_{-}$ is not a Dirichlet pole, we have $\Phi_k(\cdot, z)\in \mathscr{R}(\mathcal {G}_k)$ if $z\in \R^2\ba\ov{D}$ (see Lemma 2.10 of \cite{CCH2020}). 

To characterize the Dirichlet poles from the scattered fields for the interior cavity scattering problems, we need the following two theorems.

\begin{theorem}\label{LSM-D}
Assume that $k\in {\mathbb C}_{-}$ is not a Dirichlet pole. Let $z\in \R^2\ba\ov{D}$. Then for every $\eps$, $0<\eps<1$, there exists $g_\eps^z\in L^2(\pa\Om)$ such that
\be\label{Ng=Phi-D}
\lim_{\eps\rightarrow 0}\|\mathcal{N}_k g^{\eps}_z - \Phi_k(\cdot, z)\|_{L^2(\pa\Om)}=0
\en
and
\be\label{Sg<M}
\|\mathcal{S}_k g^{\eps}_z\|_{H^1_{loc}(\R^2\ba{\ov{D}})} < M
\en
for some constant $M>0$. 
%In fact, $\mathcal{S}_k g^{\eps}_z$ converges to $c$ in $H^{1/2}(\pa D)$.
\end{theorem}
\begin{proof}
Since $k\in {\mathbb C}_{-}$ is not a Dirichlet pole, the exterior Dirichlet problem is well posed. Denote by $w_z\in H^1_{loc}(\R^2\ba{\ov{D}})$ the outgoing solution with boundary value $w_z=\Phi_k(\cdot, z)$ on $\pa D$. Consequently, $\mathcal {G}_k w_z = \Phi_k(\cdot, z)$ on $\pa\Om$. Furthermore, using Theorem \ref{S-Properties}, we deduce that, for every $\eps>0$, there exists $g_\eps^z\in L^2(\pa\Om)$ such that
\be\label{Sg-wz}
\|\mathcal{S}_k g^{\eps}_z-w_z\|_{H^1_{loc}(\R^2\ba{\ov{D}})}<\frac{\eps}{\|\mathcal {G}_k\|}.
\en
The limit \eqref{Ng=Phi-D} follows immediately from the inequality \eqref{Sg-wz} and the factorization \eqref{Factorization}.
By the triangular inequality, the inequality \eqref{Sg-wz} implies
\ben
\|\mathcal{S}_k g^{\eps}_z\|_{H^1_{loc}(\R^2\ba{\ov{D}})}\leq \|w_z\|_{H^1_{loc}(\R^2\ba{\ov{D}})}+\frac{\eps}{\|\mathcal {G}_k\|}.
\enn
Then the inequality \eqref{Sg<M} holds by taking $M=\|w_z\|_{H^1_{loc}(\R^2\ba{\ov{D}})}+1/\|\mathcal {G}_k\|$.
\end{proof}

The existence of $g_\eps^z\in L^2(\pa\Om)$ such that the limit holds has been obtained in Theorem 2.11 in \cite{CCH2020}. We want to recall that the uniform boundedness of $\|\mathcal{S}_k g^{\eps}_z\|_{H^{1/2}(\pa D)}$ has also been proved in Theorem 2.11 in \cite{CCH2020}. As pointed out in \cite{CCH2020}, if $k\in {\mathbb C}_{-}$ is not a Dirichlet pole, the two norms $\|\mathcal{S}_k g^{\eps}_z\|_{H^{1/2}(\pa D)}$ and $\|\mathcal{S}_k g^{\eps}_z\|_{H^1_{loc}(\R^2\ba{\ov{D}})}$ are equivalent. However, this is not true if $k\in {\mathbb C}_{-}$ is a Dirichlet pole. The following Theorem \ref{pole-D} shows that, for $z\in\R^2\ba\ov{D}$, the norm $\|\mathcal{S}_k g^{\eps}_z\|_{H^1_{loc}(\R^2\ba{\ov{D}})}$ cannot be bounded if $k\in {\mathbb C}_{-}$ is a Dirichlet pole.

\begin{theorem}\label{pole-D}
Assume that $k\in {\mathbb C}_{-}$ is a Dirichlet pole and 
\be\label{Ng-Phi}
\lim_{\eps\rightarrow 0}\|\mathcal{N}_k g^{\eps}_z - \Phi_k(\cdot, z)\|_{L^2(\pa\Om)}=0
\en
holds for all $z\in \R^2\ba\ov{D}$.
Then, for almost every $z\in \R^2\ba\ov{D}$, $\|\mathcal{S}_k g^{\eps}_z\|_{H^{1}_{loc}(\R^2\ba\ov{D})}$ can not be bounded as $\eps\rightarrow 0$.
\end{theorem}
\begin{proof}
Assume on the contrary that
\ben
\|\mathcal{S}_k g^{\eps_n}_z\|_{H^{1}_{loc}(\R^2\ba\ov{D})}\leq M
\enn
for some constant $M>0$, some sequence $\eps_n\rightarrow 0$ and all
$z\in D_0\subset \R^2\ba\ov{D}$ where $D_0$ has a positive measure. Hence, by selecting subsequences and relabeling, there exists a weakly convergent sequence  $v_n:=\mathcal{S}_k g^{\eps_n}_z \rightharpoonup v$ for some $v\in H^{1}_{loc}(\R^2\ba\ov{D})$. Denote by $T: H^{1}_{loc}(\R^2\ba\ov{D}) \to H^{1/2}(\pa D)$ the trace operator.
Then $T v_n \rightharpoonup Tv$ on $H^{1/2}(\pa D)$.

Let $\wi{v}\in H^{1}_{loc}(\R^2\ba\ov{D})$ be an outgoing solution to the Helmholtz equation in $\R^2\ba\ov{D}$ with boundary value $\wi{v}=v$ on $\pa D$. This implies $T\wi{v}=Tv$ and therefore $T v_n \rightharpoonup T\wi{v}$ on $H^{1/2}(\pa D)$.
By Green's representation theorem, we have that
\be\label{wiv}
\wi{v}(x)=\int_{\pa D}\left\{\frac{\pa \Phi_k(x,y)}{\pa\nu(y)}\wi{v}(y)-\Phi_k(x,y)\frac{\pa \wi{v}}{\pa\nu}(y)\right\}ds(y),\quad x\in \R^2\ba\ov{D}.
\en
Note that $\mathcal{G}_k = GT$ where $G: H^{1/2}(\pa D) \to L^2(\pa \Om)$ is the compact operator defined by \eqref{G-Def}.
Furthermore, with the help of the factorization $\mathcal{N}_k=\mathcal{G}_k\mathcal{S}_k$, we have that
\be\label{Gvn-Gv}
\mathcal{N}_k g^{\eps}_z = \mathcal{G}_k\mathcal{S}_k g^{\eps}_z = \mathcal{G}_k v_n = GT v_n \rightarrow GT \wi{v} = \mathcal{G}_k \wi{v} \quad\mbox{in}\, L^2(\pa\Om).
\en
Denote by $u_z$ the solution of
\ben
\Delta u_z +k^2 u_z = 0 \quad\mbox{in}\, D, \qquad u_z=\wi{v}|_{\pa D}\quad\mbox{on}\, \pa D.
\enn
Then $\mathcal{G}_k \wi{v} = u_z$ on $L^2(\pa\Om)$. Combination of \eqref{Gvn-Gv} and \eqref{Ng-Phi} yields that $u_z=\Phi(\cdot,z)$ on $\pa\Om$. Using Lemma \ref{Uni-Interior} and the analytic continuation, we have $u_z=\Phi(\cdot, z)$ in $D$ and thus
\be\label{wiv=Phi}
\wi{v}=\Phi(\cdot, z)\quad\mbox{on}\, \pa D.
\en

We recall the single and double layer operator $S$ and $K$ given by
\be
S\phi(x)&:=&\int_{\pa D}\Phi_k(x,y)\phi(y)ds(y), \quad x\in\pa D,\cr
\label{K}K\phi(x)&:=&\int_{\pa D}\frac{\pa\Phi_k(x,y)}{\pa\nu(y)}\phi(y)ds(y), \quad x\in\pa D
\en
and the normal derivative operator $K^{'}$ given by
\ben
K^{'}\phi(x):=\int_{\pa D}\frac{\pa\Phi_k(x,y)}{\pa\nu(x)}\phi(y)ds(y), \quad x\in\pa D.
\enn
By the jump relation, the representation \eqref{wiv} implies
\be\label{wiv-b}
\wi{v}|_{\pa D} = \Big(\frac{1}{2}I+K\Big)\wi{v}|_{\pa D} - S \frac{\pa\wi{v}}{\pa\nu}\Big|_{\pa D}.
\en

Since $k\in {\mathbb C}_{-}$ is a Dirichlet pole, we take $w_0$ be a non-trivial outgoing solution in $\R^2\ba\ov{D}$ with homogeneous boundary data $w_0= 0$ on $\pa D$.
By Green's representation theorem again,
\ben
w_0(x)
&=&\int_{\pa D}\left\{\frac{\pa \Phi_k(x,y)}{\pa\nu(y)}w_0(y)-\Phi_k(x,y)\frac{\pa w_0}{\pa\nu}(y)\right\}ds(y)\cr
&=&-\int_{\pa D}\Phi_k(x,y)\frac{\pa w_0}{\pa\nu}(y)ds(y),\quad x\in \R^2\ba\ov{D}.
\enn
Letting $x$ approach the boundary, we have that
\be\label{w0-b}
S\frac{\pa w_0}{\pa\nu} = 0 \quad\mbox{and}\quad \Big(\frac{1}{2}I+K^{'}\Big)\frac{\pa w_0}{\pa\nu} = 0 \qquad \mbox{on}\, \pa D.
\en

Interchanging the order of integration, we observe that $S$ is self-adjoint and
$K$ and $K^{'}$ are adjoint with respect to the bilinear form
\be\label{bilinearform}
\langle\phi,\psi\rangle:=\int_{\pa D} \phi\psi ds.
\en
With the help of \eqref{wiv-b} and \eqref{w0-b}, we have that
\be\label{wiw=0}
\left\langle\wi{v},\frac{\pa w_0}{\pa\nu}\right\rangle
&=&\left\langle\Big(\frac{1}{2}I+K\Big)\wi{v} - S \frac{\pa\wi{v}}{\pa\nu},\frac{\pa w_0}{\pa\nu}\right\rangle\cr
&=&\left\langle\wi{v}, \Big(\frac{1}{2}I+K^{'}\Big)\frac{\pa w_0}{\pa\nu}\right\rangle - \left\langle \frac{\pa\wi{v}}{\pa\nu}, S\frac{\pa w_0}{\pa\nu}\right\rangle\cr
&=& 0.
\en

Define the single layer potential
\ben
\wi{w}(z):=\int_{\pa D}\Phi_k(y, z)\frac{\pa w_0}{\pa\nu}(y)ds(y), \quad z\in \R^2\ba\pa D.
\enn
Then $\wi{w}=0$ in $D_0$ by \eqref{wiw=0} and \eqref{wiv=Phi}. By analytic continuation, $\wi{w}=0$ in $\R^2\ba\ov{D}$. Taking the trace and using Lemma \ref{Uni-Interior},
$\wi{w}=0$ in $D$. Then $\frac{\pa w_0}{\pa\nu}=0$ on $\pa D$ by the jump relation of the single layer potential. Using the homogeneous Dirichlet boundary condition $w_0=0$ on $\pa D$, we have $w_0=0$ in $\R^2\ba\ov{D}$ by the Holmgren's theorem. This is a contradiction to the fact that $w_0$ is a non-trivial outgoing solution in $\R^2\ba\ov{D}$.
\end{proof}


Let $g_z^\eps$ be an approximate solution of
\begin{equation}\label{Near-Field-Equation}
(\mathcal{N}_k g)(x) = \Phi_k(x, z),\quad  x \in \pa \Om, z\in \R^2\ba\ov{D}.
\end{equation}
Due to Theorems \ref{pole-D} and \ref{LSM-D}, one can use $\|\mathcal{S}_k g^{\eps}_z\|_{H^1_{loc}(\R^2\ba{\ov{D}})}$ to characterize the Dirichlet poles. Based on the analysis in the next subsection for the Neumann case, $\|\mathcal{S}_k g^{\eps}_z\|_{H^1_{loc}(\R^2\ba{\ov{D}})}$ can also be used to characterize the Neumann poles.

