\subsection{Neumann Case}\label{subsec-N}
In this subsection we consider Neumann boundary conditions.
For an outgoing solution $w\in H^1_{loc}(\R^2\ba{\ov{D}})$, the operator $\mathcal {G}_k: H^1_{loc}(\R^2\ba{\ov{D}}) \to L^2(\pa \Om)$ is now defined by $\mathcal {G}_k w=u_w|_{\pa \Om}$, where $u_w\in H^1(D)$ solves
\ben
\Delta u_w+k^2 u_w= 0 \quad\text{in } D\quad\mbox{and}\quad \frac{\pa u_w}{\pa\nu} = \frac{\pa w}{\pa\nu}  \quad\text{on } \pa D.
\enn
The near field operator $\mathcal{N}_k: L^2(\pa \Om) \to L^2(\pa \Om)$ has a factorization
     \be\label{Factorization-N}
     \mathcal{N}_k=\mathcal{G}_k\mathcal{S}_k;
     \en
%The analogous results of Theorem \ref{Operator-Properties} and \ref{LSM-D} are formulated in the following theorem.

\begin{theorem} \label{LSM-N}
Assume that $k\in C_{-}$ is not a Neumann pole. 
%Then we have
%    \begin{itemize}
%      \item $\mathcal{N}_k: L^2(\pa \Om) \to L^2(\pa \Om)$ is injective with dense range in $L^2(\pa \Om)$;
%      \item $\mathcal {G}_k: H^1_{loc}(\R^2\ba{\ov{D}}) \to L^2(\pa \Om)$ is injective. For $z\in\R^2\ba\ov{\Om}$,
 %           \be\label{G-range-N}
%            z\in \R^2\ba\ov{D} \Longleftrightarrow \Phi_k(\cdot, z)\in \mathscr{R}(\mathcal {G}_k).
%            \en
%      \item 
Let $z\in \R^2\ba\ov{D}$. Then for every $\eps>0$, there exists $g_\eps^z\in L^2(\pa\Om)$ such that
\ben
\lim_{\eps\rightarrow 0}\|\mathcal{N}_k g^{\eps}_z - \Phi_k(\cdot, z)\|_{L^2(\pa\Om)}=0\quad\mbox{and}\quad \|\mathcal{S}_k g^{\eps}_z\|_{H^1_{loc}(\R^2\ba{\ov{D}})} < M
\enn
for some constant $M>0$. 
%In fact, $\mathcal{S}_k g^{\eps}_z$ converges to $\Phi_k(\cdot, z)$ in $H^{1/2}(\pa D)$.
 %   \end{itemize}
\end{theorem}
\begin{proof}
     For $z\in\R^2\ba\ov{D}$,  $\Phi_k(\cdot, z)$ is a solution to the Helmholtz equation in $D$. Since $k\in {\mathbb C}_{-}$ is not a Neumann pole, the exterior Neumann boundary problem \eqref{Helmholtz}, \eqref{SoundHard}-\eqref{outgoing} is uniquely solvable. Denote by $w\in H^1_{loc}(\R^2\ba\ov{D})$ the outgoing solution with boundary data $\pa w/\pa\nu=\pa\Phi_k(\cdot, z)/\pa\nu$ on $\pa D$. Then $\mathcal {G}_k w=\Phi_k(\cdot, z)$, i.e., $\Phi_k(\cdot, z)\in \mathscr{R}(\mathcal {G}_k)$.
     The results then follows by a similar proof of Theorem \ref{LSM-D}.
\end{proof}

We have the following analogy of Theorem \ref{pole-D}.

\begin{theorem}\label{pole-N}
Assume that $k\in C_{-}$ is a Neumann pole and 
\be\label{Ng-Phi-N}
\lim_{\eps\rightarrow 0}\|\mathcal{N}_k g^{\eps}_z - \Phi_k(\cdot, z)\|_{L^2(\pa\Om)}=0.
\en
holds for all $z\in \R^2\ba\ov{D}$.
Then, for almost every $z\in \R^2\ba\ov{D}$, $\|\mathcal{S}_k g^{\eps}_z\|_{H^{1}_{loc}(\R^2\ba\ov{D})}$ can not be bounded as $\eps\rightarrow 0$.
\end{theorem}
\begin{proof}
Assume on the contrary that
\ben
\|\mathcal{S}_k g^{\eps_n}_z\|_{H^{1}_{loc}(\R^2\ba\ov{D})}\leq M
\enn
for some constant $M>0$, some sequence $\eps_n\rightarrow 0$ and all
$z\in D_0\subset \R^2\ba\ov{D}$, where $D_0$ has a positive measure. By selecting subsequences and relabeling, there exists a  weakly convergent sequence  $v_n:=\mathcal{S}_k g^{\eps_n}_z \rightharpoonup v$ for some $v\in H^{1}_{loc}(\R^2\ba\ov{D})$. Denote by $T: H^{1}_{loc}(\R^2\ba\ov{D}) \to H^{-1/2}(\pa D)$ the Neumann trace operator. Then $T v_n \rightharpoonup Tv$ in $H^{1/2}(\pa D)$.

Let $\wi{v}\in H^{1}_{loc}(\R^2\ba\ov{D})$ be an outgoing solution to the Helmholtz equation in $\R^2\ba\ov{D}$ with Neumann boundary value
$\frac{\pa\wi{v}}{\pa\nu}=Tv$ on $\pa D$.
This implies $T\wi{v}=Tv$ and therefore $T v_n \rightharpoonup T\wi{v}$ in $H^{-1/2}(\pa D)$.
Note that $\mathcal{G}_k = GT$, where $G: H^{-1/2}(\pa D) \to L^2(\pa \Om)$ is the compact operator defined by \eqref{G-Def}.
Furthermore, using the factorization $\mathcal{N}_k=\mathcal{G}_k\mathcal{S}_k$, we have that
\be\label{Gvn-Gv-N}
\mathcal{N}_k g^{\eps}_z = \mathcal{G}_k\mathcal{S}_k g^{\eps}_z = \mathcal{G}_k v_n = GT v_n \rightarrow GT \wi{v} = \mathcal{G}_k \wi{v} \quad\mbox{in}\, L^2(\pa\Om).
\en
Denote by $u_z$ the solution of
\ben
\Delta u_z +k^2 u_z = 0 \quad\mbox{in}\, D, \qquad \frac{\pa u_z}{\pa\nu}=T\wi{v}\quad\mbox{on}\, \pa D.
\enn
Then $\mathcal{G}_k \wi{v} = u_z$ in $L^2(\pa\Om)$. Combination of \eqref{Gvn-Gv} and \eqref{Ng-Phi} yields that $u_z=\Phi(\cdot,z)$ on $\pa\Om$. Using Lemma \ref{Uni-Interior} and analytic continuation, we have that $u_z=\Phi(\cdot, z)$ in $D$ and thus
\be\label{wiv=Phi-N}
T\wi{v}=\frac{\pa\Phi}{\pa\nu}(\cdot, z)\quad\mbox{on}\, \pa D.
\en

Recalling the double-layer operator $K$ defined by \eqref{K}, we introduce the normal derivative operator $\mathbb{T}$ of $K$ by
\ben
\mathbb{T}\phi(x):=\frac{\pa}{\pa\nu(x)}\int_{\pa D}\frac{\pa\Phi_k(x,y)}{\pa\nu(y)}\phi(y)ds(y), \quad x\in\pa D.
\enn
Then $\mathbb{T}$ is self-adjoint with respect to the bilinear form \eqref{bilinearform}.
Since $\wi{v}$ is an outgoing solution, we obtain that
\be\label{wiv-N}
\wi{v}(x)=\int_{\pa D}\left\{\frac{\pa \Phi_k(x,y)}{\pa\nu(y)}\wi{v}(y)-\Phi_k(x,y)\frac{\pa \wi{v}}{\pa\nu}(y)\right\}ds(y),\quad x\in \R^2\ba\ov{D}.
\en
Using the jump relation, \eqref{wiv-N} implies
\be\label{wiv-b-N}
T\wi{v} = \mathbb{T}\wi{v}|_{\pa D}+\Big(\frac{1}{2}I-K^{'}\Big)\frac{\pa\wi{v}}{\pa\nu}\Big|_{\pa D}.
\en

Since $k\in {\mathbb C}_{-}$ is a Neumann pole, we take $w_0$ as a non-trivial outgoing solution in $\R^2\ba\ov{D}$ with homogeneous Neumann boundary data $\frac{\pa w_0}{\pa\nu}= 0$ on $\pa D$.
By the outgoing condition again, 
\ben
w_0(x)
&=&\int_{\pa D}\left\{\frac{\pa \Phi_k(x,y)}{\pa\nu(y)}w_0(y)-\Phi_k(x,y)\frac{\pa w_0}{\pa\nu}(y)\right\}ds(y)\cr
&=&\int_{\pa D}\frac{\pa \Phi_k(x,y)}{\pa\nu(y)}w_0(y)ds(y),\quad x\in \R^2\ba\ov{D}.
\enn
Letting $x$ approach the boundary, we have that
\be\label{w0-b-N}
\mathbb{T}w_0 = 0 \quad\mbox{and}\quad \Big(\frac{1}{2}I-K\Big) w_0 = 0 \qquad \mbox{on}\, \pa D.
\en

With the help of \eqref{wiv-b-N} and \eqref{w0-b-N}, noting that $\mathbb{T}$ is self-adjoint and $K$ and $K^{'}$ are adjoint with respect to the bilinear form \eqref{bilinearform}, it holds that that
\be\label{wiw=0-N}
\left\langle T\wi{v}, w_0\right\rangle
&=&\left\langle\mathbb{T}\wi{v}|_{\pa D}+\Big(\frac{1}{2}I-K^{'}\Big)\frac{\pa\wi{v}}{\pa\nu}\Big|_{\pa D},\, w_0\right\rangle\cr
&=&\left\langle\wi{v}+\frac{\pa\wi{v}}{\pa\nu},\, \mathbb{T}w_0+\Big(\frac{1}{2}I-K\Big)w_0\right\rangle\cr
&=&0.
\en

Define the double-layer potential
\ben
\wi{w}(z):=\int_{\pa D}\frac{\pa\Phi_k(y, z)}{\pa\nu(y)}  w_0(y) ds(y), \quad z\in \R^2\ba\pa D.
\enn
Then $\wi{w}=0$ in $D_0$ by \eqref{wiw=0-N} and \eqref{wiv=Phi-N}. By analytic continuation, $\wi{w}=0$ in $\R^2\ba\ov{D}$. Taking the Neumann trace and using Lemma \ref{Uni-Interior},
$\wi{w}=0$ in $D$. Then $w_0=0$ on $\pa D$ by the jump relation of the double-layer potential. Due to the homogeneous Neumann boundary condition $\frac{\pa w_0}{\pa\nu}=0$ on $\pa D$, $w_0=0$ in $\R^2\ba\ov{D}$ by the Holmgren's theorem. This is a contradiction to the fact that $w_0$ is non-trivial outgoing solution in $\R^2\ba\ov{D}$.
\end{proof}

\section{Numerical Examples}
We now present some examples to validate the inside-out duality developed in the previous section, i.e., characterize the scattering poles using the interior scattering problems. More precisely, we solve the near field equation \eqref{Near-Field-Equation} for some point $z$ outside the obstacle and check the norm of the approximate solutions for various $k$'s. We expect that the norm is large when $k$ is a pole. The "exact" poles are computed by a finite element DtN method proposed in \cite{XiGongSun2024}.

For a sound-soft obstacle and a fixed $k$, we use a linear Lagrange finite element method to compute the scattering data in $D$ with the Dirichlet data $f(x) = -\Phi_k(x, y), y \in \partial \Omega, x \in D$. To discretize \eqref{Near-Field-Equation}, we collect data $u^s_k(x_j, y_i)$, $x_i, y_j \in \partial \Omega,  i,j=1, \ldots, N$, which are computed as follows. For each $y_j$, one computes $u^s_k(x_j, y_i), i=1, \ldots, N$.
In other words, one solves $N$ Helmholtz equations for each $k$. We use the same set of discretization points on $\partial \Omega$ for $g(y)$ and denote the vector by ${\boldsymbol g}^k$ with ${\boldsymbol g}^k_i=g(y_i), i=1, \ldots, N,$ for some $z \in \mathbb R^2 \setminus \overline{D}$. The discrete version of \eqref{Near-Field-Equation}
becomes a system of equations
\begin{equation}\label{DNF}
\sum_{i=1}^N \omega_i u_k^s(x_j, y_i) {\boldsymbol g}^k_i = \Phi_k(x_j, z), \quad j=1, \ldots, N,
\end{equation}
where $\omega_i$'s are the weights of the quadrature rule for the integral over $\partial \Omega$. If $\partial \Omega$ is a circle, then one can simply use the trapezoidal rule such that $\omega_1=\omega_2 = \ldots =\omega_N$.

Let $S \subset \mathbb C_-$ be a region of interest. Let $|{\boldsymbol g}^k|$ be the norm of the solution of \eqref{DNF}. We expect that $|{\boldsymbol g}^k|$ becomes larger as $k$ approaches a scattering pole. We compute $|{\boldsymbol g}^k|$'s for a set $\{k_i\} \subset S$ of sampling points that covers $S$ and look for locations where $|{\boldsymbol g}^k|$'s are large. The case for a sound-hard obstacle is treated similarly.

\begin{remark}
We use $l_2$ norm of ${\boldsymbol g}^k$, not the respective norms in $H^{1/2}(\partial D)$ and $H_{loc}^1(\mathbb R^2 \setminus \overline{D})$. Numerical examples in this paper and results for the linear sampling method in literature suggest that such a simplification works well.
\end{remark}

\begin{remark}
For a fixed $z \in \mathbb R^2 \setminus \overline{D}$, $\Phi(\cdot, z)|_{\partial \Omega}$ is a smooth function of $k$. In stead of solving the integral equation, one can also use the condition number of the matrix $U(k)$ where $U_{i,j}(k) = u^s_k(x_i, y_j)$ to characterize the scattering poles. 
\end{remark}

\begin{remark}
Numerical experiments indicate that the choice $z \in \mathbb R^2 \setminus \overline{D}$ does not affect the result significantly as long as $z$ is not too far away from $\partial D$.
\end{remark}

\subsection{Sound-soft Obstacles}


{\bf Example 1.}
Let $D$ be the unit disk. Using separation of variables, it can be derived that the scattering poles are the zeros of Hankel functions $H_n^{(1)}(k), n \ge 2$ (see Table 1 of \cite{MaSun2023}). In particular, two poles with smallest norms are given by $k_1=0.4295-1.2814i$ and $k_2=1.3080-1.6818i$.

Let $\partial \Omega$ be a circle with radius $0.7$ inside $D$. We choose $40$ points $y_j, j=1, \ldots, 40,$ uniformly on $\partial \Omega$. The same set of points is also used for $x_i$'s. Let $z=(1,1)$, outside $D$. We generate a triangular mesh with mesh size $h\approx 0.025$ for the finite element method to compute $u^s_k(x_i, y_j)$. Then we solve \eqref{DNF} for ${\boldsymbol g}^k$ using the Tikhonov regularization. 

Let $S=[0.42, 0.44]\times[-1.29,-1.27]$ be a small region containing $k_1$. We choose $41 \times 41$ $k$'s uniformly in $S$ and compute $|{\boldsymbol g}^k|$'s. We expect that $|{\boldsymbol g}^k|$'s are large when the sampling points $k$'s are close to $k_1$. In deed, the plot of $|{\boldsymbol g}^k|$'s has a spike at $0.4285-1.2805i$, which is shown in the left picture of Fig.~\ref{SScircle}. 

Similarly, let $S=[1.30, 1.32]\times[-1.29,-1.27]$ be a small region containing $k_2$. Again, we choose $41 \times 41$ $k$'s uniformly in $S$ and compute $|{\boldsymbol g}^k|$'s. We plot $|{\boldsymbol g}^k|$'s (right picture of Fig.~\ref{SScircle}) and a spike is found at $1.3080-1.6820 i$. Both values are good approximations of the exact poles.

