\section{Pattern formation analysis for the structured model~\eqref{eq:modelnspc} with $R \equiv 0$}
\label{appendix:analysisR=0}
We carry out pattern formation analysis for the structured chemotaxis model ~\eqref{eq:modelnspc} with $R \equiv 0$, that is, the system
\beq
\label{eq:modelnspcR=0}
\begin{cases}
\displaystyle{\partial_t n = {\rm div}\left(D_n \, \nabla_x n - n \, \chi(y) \, \nabla_x s \right) + \beta \, \partial^2_{yy} n, \quad y \in \mathcal{Y}},
\\\\
\displaystyle{\partial_t s = D_s \Delta_x s + \int_{\mathcal{Y}} \alpha(y) \, n(t,x,y) \, {\rm d}y - \eta \, s,}
\end{cases}
\quad (t,x) \in (0,\infty) \times \Omega,
\eeq
which we complement with the boundary conditions~\eqref{eq:modelnsBCspc}-\eqref{eq:modelnsBCpheno}, and initial data such that conditions~\eqref{eq:modelnsICspc} hold. 

\paragraph{Positive uniform-in-space steady-state solutions}
Positive uniform-in-space steady-states of the system~\eqref{eq:modelnspcR=0} subject to conditions~\eqref{eq:modelnsBCspc}-\eqref{eq:modelnsBCpheno}, as well as initial data such that conditions~\eqref{eq:modelnsICspc} hold, are pairs $(\overline{n}(x,y), \overline{s}(x)) \equiv (\overline{n}(y), s^{\star})$, with $\overline{n} : \mathcal{Y} \to \mathbb{R}^+_0$ and $s^{\star} \in \mathbb{R}^+$ such that
\beq
\label{eq:modelnsststR0}
\begin{cases}
\displaystyle{\beta \, \partial^2_{yy} \overline{n}(y) = 0, \quad y \in \mathcal{Y}}
\\\\
\partial_y \overline{n}(y) =  0, \quad y \in \partial \mathcal{Y}
\\\\
\displaystyle{\int_{\mathcal{Y}} \overline{n}(y) \, {\rm d}y = \dfrac{N^0}{|\Omega|}}= \rho^0_{\rm m}
\\\\
\displaystyle{s^{\star} = \dfrac{1}{\eta} \, \int_{\mathcal{Y}} \alpha(y) \, \overline{n}(y) \, {\rm d}y}.
\end{cases}
\eeq

Solving the boundary-value problem~\eqref{eq:modelnsststR0}$_{1,2}$ for $\overline{n}(y)$ under the integral constraint~\eqref{eq:modelnsststR0}$_{3}$ and then substituting into~\eqref{eq:modelnsststR0}$_{4}$, recalling the definitions~\eqref{eq:ICs} for $\rho^0_{\rm m}$ and $n^0_{\rm m}$, as well as the definition~\eqref{def:taasr} for $\left<\alpha\right>$, we find
\beq
\label{eq:barnbarsR0}
\overline{n}(y) \equiv n^{\star} = \dfrac{1}{|\mathcal{Y}|} \, \dfrac{N^0}{|\Omega|} = \dfrac{\rho^0_{\rm m}}{|\mathcal{Y}|} =n^0_{\rm m}, \quad s^{\star} = \dfrac{1}{\eta} \dfrac{N^0}{|\Omega|} \dfrac{1}{|\mathcal{Y}|} \, \int_{\mathcal{Y}} \alpha(y) \, {\rm d}y = \frac{ \left<\alpha\right> \rho^0_{\rm m}}{\eta}.
\eeq
Hence, uniform-in-space steady-states are also homogeneous in phenotype.

\paragraph{Linear stability analysis of the positive uniform-in-space steady state}
Focussing on a one-dimensional spatial scenario wherein $\Omega = (0,L)$ with $L \in \mathbb{R}^+$, we consider small perturbations of the uniform steady state~\eqref{eq:barnbarsR0} via the ansatz
\beq
\label{eq:ansatzpertnsR0}
n(t,x,y) = n^{\star} + \tilde{\rho}  \exp\left(\lambda t\right) \, \varphi_k(x) \, \phi(y) , \qquad s(t,x) = s^{\star} + \tilde{s} \, \exp\left(\lambda t\right) \, \varphi_k(x),
\eeq
where $\tilde{\rho}, \tilde{s} \in \mathbb{R}$ with $|\tilde{\rho}| \ll 1$ and $|\tilde{s}| \ll 1$, $\lambda \in \mathbb{C}$, $\{\varphi_k \}_{k \geq 1}$ are the eigenfunctions of the Laplace operator, acting on functions defined on $(0, L)$ and subject to homogeneous Neumann boundary conditions, indexed by the wavenumber $k$, i.e.
\beq
\label{eq:wavenumbers}
k = \dfrac{m \pi}{L}, \quad m \in \mathbb{N},
\eeq
and the function $\phi : \mathcal{Y} \to \mathbb{R}$ satisfies the following normalisation condition
\beq
\label{eq:intphi}
\int_{\mathcal{Y}} \phi(y) \, {\rm d}y = 1.
\eeq
Substituting the ansatz~\eqref{eq:ansatzpertnsR0} into~\eqref{eq:modelnspcR=0} posed on $(0,L) \times \mathcal{Y}$ and subject to the boundary conditions~\eqref{eq:modelnsBCspc}-\eqref{eq:modelnsBCpheno}, retaining only linear terms yields
\beq
\label{newsyspert}
\begin{cases}
\displaystyle{\tilde{\rho} \, \beta \, \partial^2_{yy} \phi(y) - \tilde{\rho} \, \left(\lambda + D_n k^2 \right) \, \phi(y) = - \tilde{s} \, \chi(y) \, n^\star \, k^2, \quad y \in \mathcal{Y}}
\\\\
\partial_y \phi(y) = 0, \quad y \in \partial \mathcal{Y}
\\\\
\displaystyle{-\tilde{\rho} \, \int_{\mathcal{Y}} \alpha(y) \, \phi(y) \,  {\rm d}y + \tilde{s} \, \left(\lambda + \eta + D_s \, k^2 \right) = 0.}
\end{cases}
\eeq 
Note that integrating~\eqref{newsyspert}$_1$ over $\mathcal{Y}$ and imposing the boundary conditions~\eqref{newsyspert}$_2$ along with the normalisation condition~\eqref{eq:intphi} gives 
\beq
\label{newsyspertintcon}
\tilde{\rho} = \tilde{s} \, \dfrac{n^\star k^2}{(\lambda + D_n \, k^2)} \, \int_{\mathcal{Y}} \chi(y) \, {\rm d}y.
\eeq 
As explained in the body of the paper, we first consider the limiting scenarios in which $\beta \to 0$ and $\beta \to \infty$, and then turn to the general case $0<\beta<\infty$, where a similar analysis is possible but only when $\chi(y)$ is defined via~\eqref{eq:constantchi}.   

\subsection{Negligible phenotype switching}
\label{sec:annogrbeta0}
We first let $\beta \to 0$. Here, multiplying both sides of~\eqref{newsyspert}$_1$ by $\alpha(y)$, integrating over $\mathcal{Y}$ the resulting equation and imposing the boundary conditions~\eqref{newsyspert}$_2$, we formally find
$$
\tilde{\rho} \, \int_{\mathcal{Y}} \alpha(y) \, \phi(y) \,  {\rm d}y =  \tilde{s} \, \dfrac{n^\star k^2}{(\lambda + D_n \, k^2)} \int_{\mathcal{Y}} \, \alpha(y) \, \chi(y) \,  {\rm d}y.
$$
Substituting this into~\eqref{newsyspert}$_3$ and rearranging terms yields
$$
- \tilde{s} \, n^\star \, k^2 \, \int_{\mathcal{Y}} \alpha(y) \, \chi(y)  \, {\rm d}y \, + \, \tilde{s} \, \left(\lambda + \eta + D_s \, k^2 \right) (\lambda + D_n \, k^2) = 0
$$
from which we obtain the following quadratic equation for $\lambda \equiv \lambda(k^2)$
\beq
\label{eq:lambda}
\lambda^2 + b \, \lambda + c  = 0,
\eeq
where
$$
b \equiv b(k^2) = \left(D_n \, k^2 + D_s \, k^2 + \eta \right), \quad c \equiv c(k^2) = k^2 \, \left(D_n \, D_s \, k^2 + \eta \, D_n - n^\star \, \int_{\mathcal{Y}} \alpha(y) \, \chi(y)  \, {\rm d}y \right).
$$
For the considered perturbations to grow over time, and thus drive the steady state~\eqref{eq:barnbarsR0} unstable, it suffices that there exist some $k^2 \in \mathbb{R}^+$ such that $c(k^2)<0$. That is, recalling the expression~\eqref{eq:wavenumbers} of $k$, the expression~\eqref{eq:barnbarsR0} of $n^{\star}$, and the definition~\eqref{def:taap} of $\left< \alpha \chi \right>$, we formally find that the formation of spatial patterns occurs when condition~\eqref{eq:condinstR0beta0} is met, i.e. the condition
$$
\left< \alpha \chi \right> \rho^0_{\rm m} >  \eta \, D_n + \dfrac{m^2 \pi^2}{L^2}  \, D_n \, D_s \quad \text{for some } \; m \in \mathbb{N}.
$$

\subsection{Fast phenotype switching}
\label{sec:annogrbetainfty}

We next consider the opposite scenario (i.e. when $\beta \to \infty$). Here, \eqref{newsyspert}$_{1,2}$ along with the normalisation condition~\eqref{eq:intphi} formally give $\displaystyle{\phi(y) \equiv \dfrac{1}{|\mathcal{Y}|}}$. Inserting this along with the expression for $\tilde{\rho}$ given by~\eqref{newsyspertintcon} into~\eqref{newsyspert}$_3$ and rearranging terms yields
$$
- \tilde{s} \, n^\star \, k^2 \, \int_{\mathcal{Y}} \chi(y) \,  {\rm d}y \, \dfrac{1}{|\mathcal{Y}|} \, \int_{\mathcal{Y}} \alpha(y) \,  {\rm d}y \, + \, \tilde{s} \, \left(\lambda + \eta + D_s \, k^2 \right) (\lambda + D_n \, k^2) = 0,
$$
from which we obtain the quadratic equation~\eqref{eq:lambda} for $\lambda \equiv \lambda(k^2)$ with
$$
b \equiv b(k^2) = \left(D_n \, k^2 + D_s \, k^2 + \eta \right), \quad c \equiv c(k^2) = k^2 \, \left[\left(D_n \, D_s \, k^2 + \eta \, D_n\right) - n^\star \, \int_{\mathcal{Y}} \alpha(y) \, {\rm d}y \, \dfrac{1}{|\mathcal{Y}|} \int_{\mathcal{Y}} \chi(y) \, {\rm d}y \right].
$$
As previously, requiring that $c(k^2)<0$ and recalling the expression~\eqref{eq:wavenumbers} of $k$, the expression~\eqref{eq:barnbarsR0} of $n^{\star}$, and the definitions~\eqref{def:taasr} and~\eqref{def:tacs} of $\left< \alpha \right>$ and $\left< \chi \right>$, we formally find condition~\eqref{eq:condinstR0betainfty} for the formation of spatial patterns to occur, i.e. the condition
$$
\left< \alpha \right> \left< \chi \right> \rho^0_{\rm m} > \eta \, D_n + \dfrac{m^2 \pi^2}{L^2}  \, D_n \, D_s  \quad \text{for some } \; m \in \mathbb{N}.
$$

\subsection{Generic phenotype switching}
\label{sec:annogrchiconst}
A complete analysis for generic phenotype switching (i.e. $0 < \beta < \infty$) appears to be challenging, but the case where $\chi(y)$ is defined via~\eqref{eq:constantchi} is possible. Without loss of generality -- and to avoid cumbersome notation -- we set $\mathcal{Y}=(0,1)$, thereby $|\mathcal{Y}|=1$. Condition~\eqref{newsyspertintcon} reduces to
\beq
\label{newsyspertintconchiconst}
\tilde{\rho} = \tilde{s} \, \dfrac{n^\star k^2}{(\lambda + D_n \, k^2)} \, \chi_0.
\eeq
Moreover, solving the differential equation \eqref{newsyspert}$_1$ posed on $(0,1)$ under the condition~\eqref{newsyspertintconchiconst} and imposing the boundary conditions~\eqref{newsyspert}$_2$ at the endpoints $y=0$ and $y=1$, we find
\beq
\label{phichiconst}
\phi(y) \equiv 1.
\eeq
Substituting~\eqref{phichiconst} along with the expression for $\tilde{\rho}$ given by~\eqref{newsyspertintconchiconst} into~\eqref{newsyspert}$_3$ and rearranging terms yields
$$
- \tilde{s} \, n^\star \, k^2 \, \chi_0 \, \int_{0}^1 \alpha(y) \,  {\rm d}y \, + \, \tilde{s} \, \left(\lambda + \eta + D_s \, k^2 \right) (\lambda + D_n \, k^2) = 0,
$$
from which we obtain the quadratic equation~\eqref{eq:lambda} for $\lambda \equiv \lambda(k^2)$ with
$$
b \equiv b(k^2) = \left(D_n \, k^2 + D_s \, k^2 + \eta \right), \quad c \equiv c(k^2) = k^2 \, \left(D_n \, D_s \, k^2 + \eta \, D_n - n^\star \, \chi_0 \, \int_{0}^1 \alpha(y)  \, {\rm d}y \right).
$$
Once again it suffices that there exist some $k^2 \in \mathbb{R}^+$ such that $c(k^2)<0$. Recalling the expression~\eqref{eq:wavenumbers} of $k$, the expression~\eqref{eq:barnbarsR0} of $n^{\star}$, and the definition~\eqref{def:taasr} of $\left< \alpha \right>$, we find that the formation of spatial patterns occurs when condition~\eqref{eq:condinstR0chiconst} holds, i.e. when 
$$
	 \left<\alpha\right>  \chi_0 \, \rho^0_{\rm m} >  \eta \, D_n + \dfrac{m^2 \pi^2}{L^2}  \, D_n \, D_s  \quad \text{for some } \; m \in \mathbb{N}.
$$

\section{Pattern formation analysis for the structured model~\eqref{eq:modelnspc} with $R \not\equiv 0$}
\label{appendix:analysisRneq0}
We carry out pattern formation analysis for the structured chemotaxis model~\eqref{eq:modelnspc} with the function $R \not\equiv 0$ that satisfies assumptions~\eqref{ass:Rnophdep}.

\paragraph{Positive uniform-in-space steady-state solutions}
Positive uniform-in-space steady-states of the system~\eqref{eq:modelnspc} with $R \not\equiv 0$, subject to boundary conditions~\eqref{eq:modelnsBCspc}-\eqref{eq:modelnsBCpheno}, are pairs $(\overline{n}(x,y), \overline{s}(x)) \equiv (\overline{n}(y), s^{\star})$, with $\overline{n} : \mathcal{Y} \to \mathbb{R}^+_0$ and $s^{\star} \in \mathbb{R}^+$, such that
\beq
\label{eq:modelnsststRcst}
\begin{cases}
\displaystyle{\beta \, \partial^2_{yy} \overline{n}(y) + R(\rho^\star) \, \overline{n}(y) = 0, \quad y \in \mathcal{Y}}
\\\\
\partial_y \overline{n}(y) =  0, \quad y \in \partial \mathcal{Y}
\\\\
\displaystyle{\rho^{\star} =  \int_{\mathcal{Y}} \overline{n}(y) \, {\rm d}y}>0
\\\\
\displaystyle{s^{\star} = \dfrac{1}{\eta} \, \int_{\mathcal{Y}} \alpha(y) \, \overline{n}(y) \, {\rm d}y}.
\end{cases}
\eeq
Under assumptions~\eqref{ass:Rnophdep} on the net growth rate $R(\rho)$, solving the problem~\eqref{eq:modelnsststRcst}$_{1,2}$ for $\overline{n}(y)$ under the integral constraint~\eqref{eq:modelnsststRcst}$_{3}$ and then substituting into~\eqref{eq:modelnsststRcst}$_{4}$, recalling the definition~\eqref{def:taasr} for $\left<\alpha\right>$, we find
\beq
\label{eq:barnbarsRcst}
\overline{n}(y) \equiv n^{\star} = \dfrac{1}{|\mathcal{Y}|} \, \kappa, \quad s^{\star} = \dfrac{1}{\eta} \, \kappa\, \dfrac{1}{|\mathcal{Y}|} \, \int_{\mathcal{Y}} \alpha(y) \, {\rm d}y = \dfrac{\left< \alpha \right> \kappa}{\eta}.
\eeq
Hence, similarly to the case where population growth is negligible, the uniform-in-space steady-state is also homogeneous in phenotype. 

\paragraph{Linear stability analysis of the positive uniform-in-space steady state}
As in Appendix~\ref{appendix:analysisR=0}, we restrict to a one-dimensional spatial scenario, i.e. $\Omega = (0,L)$, and consider small perturbations of the steady state~\eqref{eq:barnbarsRcst} via the ansatz~\eqref{eq:ansatzpertnsR0}. Substituting this ansatz into system~\eqref{eq:modelnspc} posed on $(0,L) \times \mathcal{Y}$ and subject to the boundary conditions~\eqref{eq:modelnsBCspc}-\eqref{eq:modelnsBCpheno}, retaining only linear terms, using the normalisation condition~\eqref{eq:intphi} along with the fact that under assumptions~\eqref{ass:Rnophdep} the relation $-R'(\kappa)= \left|R'(\kappa)\right|$ holds, yields
\beq
\label{newsyspertRcst}
\begin{cases}
\displaystyle{\tilde{\rho} \, \beta \, \partial^2_{yy} \phi(y) - \tilde{\rho} \, \left(\lambda + D_n k^2 \right) \, \phi(y) = - \tilde{s} \, \chi(y) \, n^{\star} \, k^2 + \tilde{\rho} \, \left|R'(\kappa)\right| \, n^{\star}, \quad y \in \mathcal{Y}}
\\\\
\partial_y \phi(y) = 0, \quad y \in \partial \mathcal{Y}
\\\\
\displaystyle{-\tilde{\rho} \, \int_{\mathcal{Y}} \alpha(y) \, \phi(y) \,  {\rm d}y + \tilde{s} \, \left(\lambda + \eta + D_s \, k^2 \right) = 0.}
\end{cases}
\eeq 
Note that integrating equation~\eqref{newsyspertRcst}$_1$ over $\mathcal{Y}$ and imposing the boundary conditions~\eqref{newsyspertRcst}$_2$ along with the normalisation condition~\eqref{eq:intphi} gives
\beq
\label{newsyspertintconRcst}
\tilde \rho = \tilde{s} \, \dfrac{n^\star \, k^2}{(\lambda + D_n \, k^2 + \left|R'(\kappa)\right| \, \kappa)} \, \int_{\mathcal{Y}} \chi(y) \, {\rm d}y.
\eeq 
As in Appendix~\ref{appendix:analysisR=0}, we first consider the limiting scenarios in which $\beta \to 0$ and $\beta \to \infty$, and then turn to the general case $0<\beta<\infty$ but for $\chi(y)$ defined via~\eqref{eq:constantchi}. 

\subsection{Negligible phenotype switching}\label{sec:421}
When $\beta \to 0$, multiplying both sides of~\eqref{newsyspertRcst}$_1$ by $\alpha(y)$ and integrating over $\mathcal{Y}$ the resulting equation we formally obtain
$$
\tilde{\rho} \, \int_{\mathcal{Y}} \alpha(y) \, \phi(y) \,  {\rm d}y =  \tilde{s} \, \dfrac{n^\star k^2}{(\lambda + D_n \, k^2)} \int_{\mathcal{Y}} \, \alpha(y) \, \chi(y) \,  {\rm d}y \, - \, \tilde{\rho} \,  \dfrac{\left|R'(\kappa)\right| \, n^\star}{(\lambda + D_n \, k^2)} \int_{\mathcal{Y}} \, \alpha(y) \,  {\rm d}y.
$$
Moreover, inserting the expression for $\tilde \rho$ given by~\eqref{newsyspertintconRcst} into the right-hand side of the above equation yields 
$$
\tilde{\rho} \, \int_{\mathcal{Y}} \alpha(y) \, \phi(y) \,  {\rm d}y = \tilde{s} \, \dfrac{n^\star k^2}{(\lambda + D_n \, k^2)} \, \left(\displaystyle{\int_{\mathcal{Y}} \, \alpha(y) \, \chi(y) \,  {\rm d}y} - \dfrac{\left|R'(\kappa)\right| \, n^\star}{(\lambda + D_n \, k^2 + |\mathcal{Y}| \, \left|R'(\kappa)\right| \, n^\star)} \,  \int_{\mathcal{Y}} \chi(y) \, {\rm d}y \,  \int_{\mathcal{Y}} \, \alpha(y) \,  {\rm d}y\right).
$$
Substituting this into~\eqref{newsyspertRcst}$_3$ and rearranging terms gives
{\small
$$
- \tilde{s} \, n^\star \, k^2 \, \left(\displaystyle{\int_{\mathcal{Y}} \, \alpha(y) \, \chi(y) \,  {\rm d}y} - \dfrac{\left|R'(\kappa)\right| \, n^\star}{(\lambda + D_n \, k^2 + |\mathcal{Y}| \,\left|R'(\kappa)\right| \, n^\star)} \,  \int_{\mathcal{Y}} \chi(y) \, {\rm d}y \,  \int_{\mathcal{Y}} \, \alpha(y) \,  {\rm d}y\right) \, + \, \tilde{s} \, \left(\lambda + \eta + D_s \, k^2 \right) (\lambda + D_n \, k^2) = 0,
$$
}
from which, recalling the expression~\eqref{eq:barnbarsRcst} of $n^\star$ as well as the definitions~\eqref{def:taasr}, \eqref{def:tacs}, and~\eqref{def:taap} of $\left< \alpha \right>$, $\left< \chi \right>$, and $\left< \alpha \chi \right>$, we formally obtain the following cubic equation for $\lambda \equiv \lambda(k^2)$
\beq
\label{eq:cubic}
\lambda^3 + b \, \lambda^2 + c \, \lambda + d  = 0,
\eeq
where
\begin{eqnarray*}
&&b \equiv b(k^2) = 2 \, D_n \, k^2 + \eta + D_s \, k^2 + \left|R'(\kappa)\right| \, \kappa,
\\\\
&&c \equiv c(k^2) = \left(D_n \, k^2 + \eta + D_s \, k^2\right) \,  \left(D_n \, k^2 +  \left|R'(\kappa)\right| \, \kappa\right) +  \left(\eta + D_s \, k^2\right) \, D_n \, k^2 - k^2 \, \kappa \, \left<\alpha \chi \right>,
\\\\
&&d \equiv d(k^2) = D_n \, k^4 \left[ \left(\eta + D_s \, k^2\right) \,  \left(D_n + \dfrac{\left|R'(\kappa)\right| \, \kappa}{k^2}\right) - \,  \kappa \, \left<\alpha \chi \right> \right] \, + 
\\
&& \phantom{d \equiv d(k^2) =} + \left(\kappa\right)^2 \, k^2 \,  \left|R'(\kappa)\right| \left[\left<\alpha \right> \left<\chi \right> - \left<\alpha \chi \right> \right].
\end{eqnarray*}
For perturbations to grow over time, and thus drive the steady state~\eqref{eq:barnbarsRcst} unstable, we require at least one root of the  cubic equation~\eqref{eq:cubic} to have a positive real part. Given that $b(k^2)>0$ for all $k^2 \in \mathbb{R}^+$, from the Routh-Hurwitz conditions this can occur if there exist some $k^2 \in \mathbb{R}^+$ for which at least one of the inequalities $c(k^2)<0$, $d(k^2)<0$, or $b(k^2)c(k^2)-d(k^2) <0$ holds. Feasibly, any one of these three inequalities could arise in a suitable parameter region and the algebraic complexity renders statement of a compact single minimal threshold (e.g. as~\eqref{eq:condinstR0beta0}) intractable. We confine here to some general statements. 

Firstly, we note that instabilities in this case could be of either stationary Turing type (in which the eigenvalue that acquires a positive real part is real) or Turing-wave type (in which a complex conjugate pair of eigenvalues acquires a positive real part). 

Secondly, as previously, we observe dependencies on $\left<\alpha \chi \right>$, along with $\left<\alpha \right>$ and $\left<\chi \right>$. This leads us to again expect potentially distinct behaviours according to whether the rate of attractant secretion and the chemotactic sensitivity are positively or negatively correlated, on which we expand further in Section \ref{sec:csgrowth}. Additional insight can be provided by considering some particulars for rates of attractant secretion and chemotactic sensitivities which are monotonic and either positively or negatively correlated. 

For monotonic and positively correlated traits, the Chebyshev integral inequality~\cite[p.~40]{mitrinovic1970analytic} yields $\left< \alpha \chi \right> > \left< \alpha \right>\left< \chi \right>$ and for $d(k^2) < 0$ (recalling the expression~\eqref{eq:wavenumbers} of $k$) we determine the following sufficient condition
\begin{equation}
\label{eq:condinstRcstbeta0a}
\left< \alpha \chi \right> \kappa  > \eta D_n + \frac{m^2 \pi^2}{L^2} D_n D_s + |R'(\kappa)| \, \left(D_s + \eta \frac{L^2}{m^2 \pi^2} \right) \, \kappa \quad \text{for some } \; m \in \mathbb{N}.
\end{equation}
Under monotonic and negatively correlated traits, the Chebyshev integral inequality gives instead $\left< \alpha \chi \right> < \left< \alpha \right>\left< \chi \right>$ and the sufficient condition for instability arising through $d(k^2) < 0$ is
\begin{eqnarray}
\label{eq:condinstRcstbeta0b}
\left< \alpha \chi \right> \kappa  & > & \eta D_n + \frac{m^2 \pi^2}{L^2} D_n D_s + |R'(\kappa)| \, \left(D_s + \eta \frac{L^2}{m^2 \pi^2} \right) \, \kappa + \dfrac{\left(\kappa\right)^2}{D_n} \, \frac{L^2}{m^2 \pi^2} \,  \left|R'(\kappa)\right| \left| \left< \alpha\right>\left< \chi\right>-\left< \alpha\chi\right> \right|  \nonumber \\
&& \text{for some } \; m \in \mathbb{N}.
\end{eqnarray}
Clearly, the condition~\eqref{eq:condinstRcstbeta0b} is more stringent than the condition~\eqref{eq:condinstRcstbeta0a}, reinforcing the notion that the form of trait correlation strongly impacts on pattern formation conditions when phenotype switching is negligible.

While~\eqref{eq:condinstRcstbeta0a} and~\eqref{eq:condinstRcstbeta0b} are sufficient conditions, they do not necessarily provide the minimal critical value of the trait-averaged autoattractant potential, $\left<\alpha \chi \right>$, for pattern formation. Alternatively, denoting the discriminant of the cubic equation~\eqref{eq:cubic} by $\mathcal{D}(k^2)$, that is,
$$
\mathcal{D}(k^2) = b(k)^2 c(k)^2 + 18 b(k) c(k) d(k) - 4 c(k)^3 - 4 b(k)^3 d(k) - 27 d(k)^2,
$$
pattern formation can also occur if there exist some $k^2 \in \mathbb{R}^+$ such that the conditions $c(k^2)<0$, $d(k^2) > 0$, and $\mathcal{D}(k^2) < 0$ simultaneously hold. In fact, this ensures that there exist two complex conjugate roots with positive real part of the cubic equation~\eqref{eq:cubic}. These conditions are clearly cumbersome to study in general but, in appropriate asymptotic regimes, under suitable assumptions on the model functions, it can be shown that, when the rate of attractant secretion and the chemotactic sensitivity are negatively correlated, such conditions provide the minimal critical value of the trait-averaged autoattractant potential for pattern formation.

For instance, if $R'(\kappa) \sim -C$ with $C \in \mathbb{R}^+$ as $\kappa \to \infty$, e.g. when $R(\rho)$ is defined via~\eqref{def:R} and $\gamma \propto \kappa$, then the coefficients of the cubic equation~\eqref{eq:cubic} are such that
\begin{eqnarray*}
&&b \equiv b(k^2) \sim  \kappa \, C, \quad c \equiv c(k^2) \sim \kappa \, k^2 \, \left[\left(D_n + \dfrac{\eta}{k^2} + D_s \right) \, C - \, \left< \alpha \chi \right>\right],
\\\\
&&\text{and } \;\; d \equiv d(k^2) \sim \left(\kappa\right)^2 \, k^2 \,  C  \left(\left< \alpha \right> \left< \chi \right> - \left< \alpha \chi \right> \right) \quad \text{as } \kappa \to \infty.
\end{eqnarray*}
Moreover, the discriminant of the cubic equation~\eqref{eq:cubic} is such that 
\begin{eqnarray*}
\mathcal{D}(k^2) &=& b(k)^2 c(k)^2 + 18 b(k) c(k) d(k) - 4 c(k)^3 - 4 b(k)^3 d(k) - 27 d(k)^2 
\\
&\sim& - 4 \left(\kappa\right)^5 \, k^2 \,  C^4 \,  \left(\left< \alpha \right> \left< \chi \right> - \left< \alpha \chi \right> \right) \quad  \text{as } \kappa \to \infty.
\end{eqnarray*}
Note that $b(k^2)>0$ for all $k^2 \in \mathbb{R}^+$. Again, when the functions $\chi(y)$ and $\alpha(y)$ are monotone in the opposite sense on $\mathcal{Y}$, the Chebyshev integral inequality gives $\left< \alpha \chi \right> < \left< \alpha \right> \left< \chi \right>$. Hence, in this case, $d(k^2)>0$ and $\mathcal{D}(k^2)<0$ for all $k^2 \in \mathbb{R}^+$. Furthermore, if
$$
 \left< \alpha \chi \right> >  \left(D_n + \dfrac{\eta}{k^2} + D_s \right) \, C
$$
then also the condition $c(k^2)<0$ is met. Thus, under this scenario, recalling the expression~\eqref{eq:wavenumbers} of $k$, we find the following sufficient condition for the formation of spatial patterns to occur
\beq
\label{eq:condinstRcstbeta0brhoMinfty}
\left< \alpha \chi \right> > \left(D_s + \eta \frac{L^2}{m^2 \pi^2} + D_n \right) \,  C \quad \text{for some } \; m \in \mathbb{N}.
\eeq
Note that, under this scenario, since $d(k^2) > 0$ for all $k^2 \in \mathbb{R}^+$, the minimal critical value of the trait-averaged autoattractive potential, $\left< \alpha \chi \right>$, for pattern formation to occur is provided by condition~\eqref{eq:condinstRcstbeta0brhoMinfty}.

\subsection{Fast phenotype switching}\label{sec:422}
In the asymptotic regime $\beta \to \infty$, from~\eqref{newsyspertRcst} and~\eqref{newsyspertintconRcst} and following a similar procedure to that employed in Appendix~\ref{sec:annogrbetainfty}, we formally find condition~\eqref{eq:condinstRcstbetainfty} for the formation of spatial patterns to occur, i.e. the condition 
$$
\left<\alpha\right> \left<\chi\right> \kappa  > \eta D_n + \frac{m^2 \pi^2}{L^2} D_n D_s + |R'(\kappa)| \, \left(D_s + \eta \frac{L^2}{m^2 \pi^2} \right) \, \kappa \quad \text{for some } \; m \in \mathbb{N}.
$$


\subsection{Generic phenotype switching}\label{sec:423}
As before, scenarios where $0 < \beta < \infty$ are challenging. However, as in Appendix~\ref{sec:annogrchiconst}, it is again possible to consider the case where $\chi(y)$ is defined via~\eqref{eq:constantchi} and (without loss of generality) set $\mathcal{Y}=(0,1)$. Here, condition~\eqref{newsyspertintconRcst} reduces to
\beq
\label{newsyspertintconRcstred}
\tilde \rho = \tilde{s} \, \dfrac{n^\star \, k^2}{(\lambda + D_n \, k^2 + \left|R'(\kappa)\right| \, \kappa)} \, \chi_0.
\eeq 
Following a similar procedure to that employed in Appendix~\ref{sec:annogrchiconst}, we find condition~\eqref{eq:condinstRcstchiconst} for the formation of spatial patterns to occur, i.e. the condition 
$$
\left< \alpha \right> \, \chi_0 \, \kappa > \eta D_n + \frac{m^2 \pi^2}{L^2} D_n D_s + |R'(\kappa)| \, \left(D_s + \eta \frac{L^2}{m^2 \pi^2} \right) \, \kappa  \quad \text{for some } \; m \in \mathbb{N}.
$$

