        f_\varDelta(m,n)&\coloneq\frac{\ln \varDelta(m,n)}{\frac{m+n}{mn}};\\
        f_\varDelta &\coloneq \lim_{m,n\rightarrow\infty} f_\varDelta(m,n);\\
        k_\varDelta &\coloneq \lim_{m,n\rightarrow\infty} \frac{f_\varDelta(m,n)-f_\varDelta}{\frac{m+n}{mn}}.
    \end{align*}
