We finish this introduction with some notations and definitions.  
For all Polish spaces $X$, we denote by $\mathfrak{P}(X)$ the set of probability measures defined on the measurable space $(X, \mathcal{B}(X))$, where $\mathcal{B}(X)$ is the Borel sigma-algebra on $X$. We define the universal sigma-algebra on $X$ as
\[
\mathcal{B}_c(X) := \bigcap_{P \in \mathfrak{P}(X)} \mathcal{B}_P(X),
\]
where $\mathcal{B}_P(X)$ denotes the completion of $\mathcal{B}(X)$ with respect to $P \in \mathfrak{P}(X)$. For the rest of this paper, we use the same notation for $P \in \mathfrak{P}(X)$ and its (unique) extension on $\mathcal{B}_c(X)$.

In this context, a set $A$ is called $\mathcal{Q}$-polar for some $\mathcal{Q} \subseteq \mathfrak{P}(X)$ if there exists $N \in \mathcal{B}_c(X)$ such that $A\subseteq N$ and $P[N] = 0$ for all $P \in \mathcal{Q}.$ Moreover, a set $B$ is of $\mathcal{Q}$-full-measure if $X\setminus B$ is $\mathcal{Q}$-polar. Finally, a property holds true $\mathcal{Q}$-quasi-surely (q.s.) if it holds true on a  $\mathcal{Q}$-full-measure set. 

Let $x \in \mathbb{R}^d$ and $\epsilon >0,$ then $|x|$ is the Euclidian norm of  $x$ and  the open ball of center $x$ and radius $\epsilon$ is denoted by $B(x,\epsilon):=\{y\in\mathbb{R}^d:|y-x|<\epsilon\}$. 

\section{Projective setup}
\label{projsetup}
We introduce our projective setup.

\begin{definition}[Projective sets] \label{def_projective_sets}
Let $X$ be a Polish space. 
An analytic set of $X$ is the projection into $X$ of a Borel subset of $X \times \mathbb{N}^\mathbb{N}$. The class of such sets is denoted by $\Sigma^1_1(X)$. The complement of an analytic set is called a co-analytic set, which class is denoted by $\Pi^1_1(X)$. 

For $n \geq 2$, the classes of analytic and co-analytic sets of order $n$ are defined recursively:
\[
\Sigma^1_{n}(X) := \bigl\{ \mathrm{proj}_X(C) : C \in \Pi^1_{n-1}(X \times \mathbb{N}^\mathbb{N})\bigr \}, \quad \Pi^1_{n}(X) :=\bigl \{ X \setminus C : C \in \Sigma^1_{n}(X) \bigr\}.
\]
For all $n\geq 1$, the intersection of these two classes defines $\Delta^1_n(X)$:
   \[
   \Delta^1_n(X) := \Sigma^1_n(X) \cap \Pi^1_n(X).
   \]

Finally, the class of projective sets on $X$ is defined as
\[
\mathbf{P}(X) := \bigcup_{n \geq 1} \Delta^1_n(X).
\]

\end{definition}
Note that the only sets which are analytic and co-analytic are the Borel sets, see \cite[Theorem 14.11, p88]{kechris1995}: 
\begin{equation}\label{equation_borel_set}
    \mathcal{B}(X)=\Sigma^1_{1}(X)\cap\Pi^1_{1}(X)=\Delta^1_1(X). 
\end{equation}

Let $X$ be a Polish space. We now define the notion of measurability used in this paper.
\begin{definition}[Projective functions] \label{def_projective_mes_functions}
A function $f: X \to \mathbb{R}^d $ is $\Delta_n^1(X) $-measurable if $f^{-1}(B) $ belongs to $\Delta_n^1(X) $ for all Borel sets $B \subseteq \mathbb{R}^d $. The function $f $ is projective (or projectively measurable or $\mathbf{P}(X) $-measurable), if there exists $n \in \mathbb{N}^*$ such that $f $ is $\Delta_n^1(X) $-measurable.
\end{definition}
For two  Polish spaces $X$ and $Y$, we will denote set-valued mappings\footnote{A set-valued mapping $F: X \twoheadrightarrow Y$ is a mapping such that for every $x \in X$, $F(x)$ is a subset of $Y$.} as $F:X \twoheadrightarrow Y$. 
\begin{definition}[Projective mappings] \label{def_projective_mes_mapping}
A set-valued mapping $F: X \twoheadrightarrow \mathbb{R}^d $ is $\Delta_n^1(X) $-measurable if $F^{-1}(O) := \{ x \in X : F(x) \cap O \neq \emptyset \} $ belongs to $\Delta_n^1(X) $ for all open sets $O \subseteq \mathbb{R}^d $ (see also \cite[Definition 14.1, p.643]{RockafellarWets1998}).
The mapping $F $ is projective (or projectively measurable or $\mathbf{P}(X) $-measurable), if there exists $n \in \mathbb{N}^* $ such that $F $ is $\Delta_n^1(X) $-measurable.
\end{definition}


\begin{remark}\label{n_for_projection}
     The $n\in \mathbb{N}^*$ defined in these two definitions is independent of the Borel or open sets and only depends on the function or set-valued mapping.
\end{remark}



We need the notion of determined sets to state the (PD) axiom. Fix a set $A \subseteq \mathbb{N}^\mathbb{N}$. Consider a two-player infinite game. Player I plays $a_0 \in \mathbb{N} $, then Player II plays $b_0 \in \mathbb{N} $, then Player I plays $a_1 \in \mathbb{N} $, etc. A play is a sequence $(a_0, b_0, a_1, b_1, \dots) \in \mathbb{N}^{\mathbb{N}} $. Player I wins the game if $(a_0, b_0, a_1, b_1, \dots) \in A $. Otherwise, if $(a_0, b_0, a_1, b_1, \dots) \in \mathbb{N}^{\mathbb{N}} \setminus A $, Player II wins. A winning strategy for a Player is a strategy under which the Player always wins; that is, the result of the game always belongs to the set $A$ for Player I or to $\mathbb{N}^\mathbb{N}\setminus A$ for Player II, regardless of what the other Player plays.
\begin{definition}[Determined sets]
\label{def_determined_sets}
    A set $A \subseteq \mathbb{N}^\mathbb{N}$ is determined if a winning strategy exists for one of the two players.
\end{definition}
 Borel sets (see \cite{refboreldet_pj}) are determined. However, the determinacy of Borel sets is the best possible result provable in ZFC. This is why Martin and Moschovakis independently introduce the axiom of Projective Determinacy (see, for example, \cite[Definition 38.15, p. 325]{kechris1995} in the textbook of Kechris).
\begin{axiom}[Projective Determinacy]\label{axiom_PD}
The Projective Determinacy (PD) axiom states that if $A \subseteq \mathbb{N}^\mathbb{N}$ is a projective set, then $A$ is determined.
\end{axiom}
%The mathematicians, consciously or not, work in ZFC. So, going out of ZFC necessitate 
%Quoting Woodin \lq\lq{}The (PD) axiom is a fruitful axiom, but (a logician?s joke) so is the axiom 0 = 1\rq\rq{}. 
\begin{remark}
The (PD) axiom is a fruitful axiom as it allows to answer old questions on projective sets coming from Lusin. What makes this axiom plausible is that it is implied by other axioms of descriptive set theory that, a priori, have no direct connection with projective sets. In particular, the (PD) axiom is closely connected to the existence of Woodin cardinals. Martin and Steel (see \cite{reflargedet_pj}) showed that if sufficiently many Woodin cardinals exist, then all projective sets are determined. Conversely, assuming the (PD) axiom, one can construct inner models (transitive set-theoretic classes that satisfy the axioms of ZF and contain all the ordinals) which exhibit sequences of Woodin cardinals. 
%Large cardinal axioms like the existence of Woodin cardinals are viewed as natural extensions of set theory because they provide 
%a principled framework for resolving questions about definability and regularity properties that are otherwise independent of ZFC. 
%a framework for understanding the consistency of theories extending ZFC. 
%Large cardinals enrich the cumulative hierarchy without contradicting ZFC\rq{}s basic axioms. These cardinals help organize complex set-theoretic phenomena, especially in descriptive set theory. 
The relative consistency of large cardinals with ZFC has been extensively studied via inner model theory and forcing techniques, and no contradictions are known assuming that ZFC itself is consistent (see \cite{refwood1_pj}). 
Quoting Woodin \lq\lq{}Projective Determinacy is the correct axiom for the projective sets; the ZFC axioms are obviously incomplete and, moreover, incomplete in a fundamental way.\rq\rq{}
\end{remark}
We will not apply the (PD) axiom directly, but rather one of the reasons why it was introduced: it implies that projective sets are universally measurable and that a projectively measurable selection is possible on projective sets. 
\begin{proposition}[Consequences of the (PD) axiom]\label{prop_conseq_PD_axiom}
Assume the (PD) axiom.
    \begin{enumerate}
    \item[(i)] If $X$ is a Polish space, then $\mathbf{P}(X)\subseteq\mathcal{B}_c(X)$. 
    \item[(ii)]  Let $X $ and $Y $ be Polish spaces and $A \in \mathbf{P}(X \times Y) $. Then, there exists a projective function $\phi : \operatorname{proj}_X(A) \to Y $ such that $\operatorname{Graph}(\phi) \subseteq A $.
    \end{enumerate}

\end{proposition}
\begin{proof}
    See \cite[Theorem 38.17, p.~326]{kechris1995} and \cite[Proposition 6]{carassus2024}.
\end{proof}









\section{Financial setting}
\label{finsetup}

We fix a time horizon $T $ and introduce a family of Polish spaces $(\Omega_t)_{t \in \{1, \dots, T\}} $. 
For all $t \in \{0, \dots, T\} $, let $\Omega^t := \Omega_1 \times \dots \times \Omega_t$ with the convention that $\Omega^0=\{\omega_0\}$ is a singleton. For all $t \in \{0, \dots, T\},$  let $S_t: \O^t \to \mathbb{R}^d$. Then, $S := (S_t)_{t \in \{0, \dots, T\}} $ is the $\mathbb{R}^d$-valued process representing the price of the $d $  risky assets over time. A riskless asset whose price equals 1 is also available. We are now in a position to state our first assumption.

\begin{assumption}[Measurability of the prices]\label{assumption_prices}
For all $t \in \{0,\dots,T\} $, $S_t $ is $\mathbf{P}(\Omega^t)$-measurable. In the case $t = 0$, we mean that $S_0$ is a constant.
\end{assumption}
\begin{definition}[Trading strategies]\label{def_strategy} 
Let $\phi_t: \O^{t-1} \to \mathbb{R}^d$ for all $t \in \{1, \dots, T\}.$  
A trading strategy $\phi$ is a $d$-dimensional process $\phi := \{\phi_t : t \in \{1, \dots, T\}\}$ such that $\phi_t$ is $\mathbf{P}(\Omega^{t-1})$-measurable for all $t \in \{1, \dots, T\}$. In the case $t = 1$, we mean that  $\phi_1$ is a constant. We denote by $\Phi$ the set of such strategies, which are also self-financing.
\end{definition}

For $x,y\in \mathbb{R}^d,$ the scalar product of $x$ and $y$ will be concatenated as $xy$. For $\phi \in \Phi$, $V_t^{x, \phi}$ denotes the value of the strategy $\phi$ at time $t \in \{0, \dots , T\}$ with initial endowment  $x \in \mathbb{R}$. We get that
\[
V_t^{x, \phi} = x + \sum_{s=1}^{t} \phi_s \Delta S_s.
\]

We now construct the set $\mathcal{Q}^T$ of all prevailing priors. The set $\mathcal{Q}^T$ captures all the investor’s beliefs about the law of nature. It is construct out of the one-step priors $\mathcal{Q}_{t+1} : \Omega^t \twoheadrightarrow \mathfrak{P}(\Omega_{t+1})$ where $\mathcal{Q}_{t+1}(\omega^t)$ is the set of all possible priors for the $(t+1)$-th period given the state $\omega^t$ at time $t$, for all $t \in \{0, \dots , T-1\}$. The following assumption allows us to perform measurable selection (see Proposition~\ref{prop_conseq_PD_axiom}).
\begin{assumption}[Measurability of the beliefs]
\label{assumption:graph_Q}
For all $t \in \{0,\dots,T-1\} $, $\mathcal{Q}_{t+1} : \Omega^t \twoheadrightarrow \mathfrak{P}(\Omega_{t+1})$ is a nonempty and convex-valued random set such that
\[
\mathrm{Graph}(\mathcal{Q}_{t+1}):= \bigl\{ (\omega^t, P) \in \Omega^t \times \mathfrak{P}(\Omega_{t+1}): P \in \mathcal{Q}_{t+1}(\omega^t) \bigr \}
\in \mathbf{P}\bigl(\Omega^t \times \mathfrak{P}(\Omega_{t+1})\bigr).\] 
In the case $t = 0$, we mean that $\mathcal{Q}_{1} =\mathcal{Q}_{1}(\omega^0) $ is a nonempty and convex (nonrandom) set of $\mathfrak{P}(\Omega_{1})$.
\end{assumption}



We set $SK_1=\mathfrak{P}(\Omega_{1})$. Let $t \in \{1, \ldots, T-1\}$ and $q_{t+1}(\cdot \mid \cdot) : \mathcal{B}(\Omega_{t+1}) \times \Omega^t \to \mathbb{R}$.  We say that $q_{t+1} \in SK_{t+1}$ if for all $\omega^t \in\Omega^t $, $q_{t+1}(\cdot \mid \omega^t) \in \mathfrak{P}(\Omega_{t+1})$ and $\Omega^t \ni \omega^t\mapsto q_{t+1}(\cdot \mid \omega^t)\in \mathfrak{P}(\Omega_{t+1})$ is projectively measurable. So, $SK_{t+1}$ is the set of projectively measurable stochastic kernels on $\Omega_{t+1}$ given $\Omega^t$. 

%Under the (PD) axiom, for all $q_{t+1} \in SK_{t+1}$, we have that $\omega^t \mapsto q_{t+1}[A \mid \omega^t]$ is universally measurable (see \cite[Lemma 5]{carassus2024}) and that $q_{t+1}$ is an universally measurable stochastic kernel. %

\begin{remark}[About Assumptions]
    In the setting of Bouchard and Nutz, $S_t$ is assumed to be Borel measurable and $\mathrm{Graph}(\mathcal{Q}_{t+1})$ to be an analytic set. As without the (PD) axiom, Borel functions are projective (choose $n=1$ in Definition~\ref{def_projective_mes_functions} and recall~(\ref{equation_borel_set})), and as analytic sets are projective sets (see Definition~\ref{def_projective_sets}), our assumptions are thus weaker in ZFC. 
    Under the (PD) axiom, if $\phi \in \Phi$, then $\phi$ is universally measurable (see Proposition~\ref{prop_conseq_PD_axiom}), which is the usual assumption in the quasi-sure literature. The same reasoning holds for stochastic kernels. So, our assumptions are again weaker, but we are assuming the (PD) axiom this time.
\end{remark}

Under the (PD) axiom and Assumption~\ref{assumption:graph_Q}, Proposition~\ref{prop_conseq_PD_axiom} allows us to perform measurable selection on $\mathrm{Graph}(\mathcal{Q}_{t+1}) \in \mathbf{P}(\Omega^t \times \mathfrak{P}(\Omega_{t+1}))$ and we obtain that there exists $q_{t+1} \in SK_{t+1}$ such that for all $\omega^t \in \Omega^t$ (recall that $\mathrm{proj}_{\Omega^t}\, \mathrm{Graph}(\mathcal{Q}_{t+1})=\{\mathcal{Q}_{t+1} \neq \emptyset\}=\Omega^t$ from Assumption~\ref{assumption:graph_Q}), $q_{t+1}(\cdot \mid \omega^t) \in \mathcal{Q}_{t+1}(\omega^t)$.

Now, for all $t \in \{1, \ldots, T\}$, there exists (see Remark~\ref{remark_integrals}) a unique product measure $q_1 \otimes \cdots \otimes q_t$ which belongs to $\mathfrak{P}(\Omega^t)$ and is such that for all $A^t:=A_1\times\dots\times A_t \in\Omega^t$:
\[
q_1 \otimes \cdots \otimes q_t[A^t] := \int_{A_1} \dots \int_{A_t} q_t\bigl(d\omega_t \mid (\omega_1, \dots, \omega_{t-1})\bigr) \dots q_1(d\omega_1).
\]
We are in position to define our intertemporal sets of priors $\mathcal{Q}^t \subseteq \mathfrak{P}(\Omega^t)$ for all $t \in \{1, \ldots, T\}$ by:
%\[
%\mathcal{Q}^t := \bigl\{q_1 \otimes q_2 \otimes \cdots \otimes q_t : q_1 \in Q_1, q_{s+1} \in SK_{s+1}, q_{s+1}(\cdot \mid \omega^s) \in Q_{s+1}(\omega^s), \, \forall \omega^s \in \Omega^s, \, \forall s \in \{1, \ldots, t-1\} \bigr\}.
%\]
\[
\mathcal{Q}^t := \bigl\{q_1 \otimes q_2 \otimes \cdots \otimes q_t : q_{s+1} \in SK_{s+1},\, q_{s+1}(\cdot \mid \omega^s) \in Q_{s+1}(\omega^s), \, \forall \omega^s \in \Omega^s, \, \forall s \in \{0, \ldots, t-1\} \bigr\}.
\]
We also set $\mathcal{Q}^0 := \{\delta_{\omega_0}\}$, where $\delta_{\omega_0}$ is the Dirac measure on the single element $\omega_0$ of $\Omega^0$. If $P := q_1 \otimes q_2 \otimes \cdots \otimes q_T \in Q^T$, we write for any $t \in \{1, \ldots, T\}$, $P^t := q_1 \otimes q_2 \otimes \cdots \otimes q_t$ and $P^t \in \mathcal{Q}^t$. In this paper, we mostly work directly on the disintegration of $P$ rather than $P$.

\begin{remark}[Integrals, product measures]\label{remark_integrals}
   Let $X $ be a Polish space. Let $f : X \to \mathbb{R} \cup \{-\infty, +\infty\} $ be a universally measurable function and let $p \in \mathfrak{P}(X) $. We define the $(- \infty)$ integral denoted by $\int_- f dp$ and the $(+\infty)$ integral denoted by $\int^- f dp$ as follows. When $\int f^+ dp < +\infty$ or $\int f^- dp < +\infty$, both integrals are equal and are defined as the extended integral of $f $:
    \[  
     \int_- f dp = \int^- f dp :=\int f^+ dp - \int f^- dp.
    \]
Otherwise, $\int_- f dp := -\infty$ and $\int^- f dp := +\infty$. The condition of no-arbitrage is mainly applied in the context of maximization problems (portfolio choice, super-replication). That's why we use the $\int _- $ integral and the associated arithmetic rule $\infty-\infty=-\infty+\infty=-\infty.$ In the rest of the paper, we simply denote $\int_- f dp $ by $\int f dp$ if no further precision is necessary.

   We have seen in Proposition~\ref{prop_conseq_PD_axiom} that under the (PD) axiom, any projective set $A$ is universally measurable. This allows us to define $p[A]$ for any probability measure $p$ and, more generally, to use classical measure theory results in the projective context. First, any projective function $f$ is universally measurable (see Proposition~\ref{prop_conseq_PD_axiom}) so that $\int f dp$ (as defined above) is well-defined. Moreover, it is possible to construct a unique probability measure on the product space from projectively measurable stochastic kernels and also to use Fubini\rq{}s theorem when $f$ is projective (see \cite[Proposition~7.45~p.175]{Bertsekas1978}). So, the sets $(Q^t)_{t \in \{0,\dots,T-1\}}$ are indeed well-defined.

\end{remark}


\begin{definition}[Supports]\label{def_conditional_supports}
    Let $t \in \{0,\dots,T-1\} $ and $P \in \mathcal{Q}^T $ with the fixed disintegration 
   $
    P:= q_1 \otimes \dots \otimes q_T.
    $
    The random sets $E^{t+1}: \Omega^t \times \mathfrak{P}(\Omega_{t+1}) \twoheadrightarrow \mathbb{R}^d $, $D^{t+1}: \Omega^t \twoheadrightarrow \mathbb{R}^d $ and $D_P^{t+1}: \Omega^t \twoheadrightarrow \mathbb{R}^d $ are defined by
    \begin{align*}
    E^{t+1}(\omega^t, p) &:= \bigcap \bigl\{ A \subseteq \mathbb{R}^d:\text{closed, } p[ \Delta S_{t+1}(\omega^t, \cdot) \in A ] = 1 \bigr\}, \\
    D^{t+1}(\omega^t) &:= \bigcap \{ A \subseteq \mathbb{R}^d :\text{closed, } p[\Delta S_{t+1}(\omega^t, \cdot) \in A]= 1, \ \forall p \in \mathcal{Q}_{t+1}(\omega^t) \}, \\
    D^{t+1}_P(\omega^t) &:= \bigcap \{ A \subseteq \mathbb{R}^d : \text{closed, } q_{t+1}(\Delta S_{t+1}(\omega^t, \cdot) \in A \mid \omega^t) = 1 \}.
    \end{align*}
    We call $D^{t+1}$ the quasi-sure support of $\Delta S_{t+1}$ and  $D^{t+1}_P$ the support of $\Delta S_{t+1}$ relatively to $P$.
\end{definition}
If $R\subseteq \mathbb{R}^d$, $\mathrm{Aff}(R)$ denotes the smallest affine set containing $R$, $\mathrm{Conv}(R)$ denotes the smallest convex set containing $R$ and if $R$ is convex, $\mathrm{Ri(R)}$ is the interior of $R$ relatively to $\mathrm{Aff}(R)$. 

\begin{remark}\label{EP_included_D}
    For all $\omega^t \in \Omega^t$ and all $p \in \mathcal{Q}_{t+1}(\omega^t)$, $E^{t+1}(\omega^t, p) \subseteq D^{t+1}(\omega^t)$. Indeed, let $p \in \mathcal{Q}_{t+1}(\omega^t)$. 
Using the one-period result  \cite[Lemma 4.2]{bouchard2015} (which just requires that $\mathcal{Q}_{t+1}(\omega^t)$ is a nonempty set of probability measures), we get that $D^{t+1}(\o^{t})$ is a closed set of $\mathbb{R}^d$
%$A\subseteq \mathbb{R}^d$ such that $q(A) = 1$ for all  $q \in \mathcal{Q}$. 
such that   
  %  As  $\mathbb{R}^{d}$ is second countable, $p\bigl(\Delta S_{t+1}(\o^{t},\cdot) \in E^{t+1}(\o^{t},p)\bigr)=1,$ see  \cite[Theorem 12.14]{Hitch} and  \\$
$p[\Delta S_{t+1}(\o^{t},\cdot) \in D^{t+1}(\o^{t})]=1$ (it is even the smallest). By definition of $E^{t+1}(\omega^t, p)$ as an intersection of such  sets, $E^{t+1}(\omega^t, p)\subseteq D^{t+1}(\omega^t)$. 

    If $P:=q_1\otimes\dots\otimes q_T\in \mathcal{Q}^T$, then for all $t\in \{1,\dots,T-1\}$ and $\omega^t\in \Omega^t$, $D^{t+1}_P(\omega^t)=E^{t+1}(\omega^t,q_{t+1}(\cdot\mid \omega^t))$.

\end{remark}


We now introduce the definitions of no-arbitrage.

\begin{definition}[Quasi-sure no-arbitrage condition]
The condition $NA(\mathcal{Q}^T)$ holds true if
$$
\quad V_T^{0, \phi} \geq 0 \; \mathcal{Q}^T\mbox{-q.s.} \text{ for some }  \phi \in \Phi \implies V_T^{0, \phi} = 0 \; \mathcal{Q}^T\mbox{-q.s.}
$$

\end{definition}
\begin{definition}[Single-prior no-arbitrage condition]
Let $P \in \mathfrak{P}(\Omega^T).$ The condition $NA(P)$ holds true if
$$
\quad V_T^{0, \phi} \geq 0 \; P\mbox{-a.s.} \text{ for some }  \phi \in \Phi  \implies V_T^{0, \phi} = 0 \; P\mbox{-a.s.}
$$

\end{definition}
Note that when $\mathcal{Q}^T=\{P\}$ both notions coincide. 
\begin{definition}[Local no-arbitrage condition]
Fix $t\in \{0,\dots,T-1\}$ and $\omega^t\in\Omega^t$. The condition $NA(\mathcal{Q}_{t+1}(\omega^t))$ holds true if
\[
y\Delta S_{t+1}(\omega^t,\cdot) \geq 0 \; \mathcal{Q}_{t+1}(\omega^t)\text{-q.s. for some } y\in \mathbb{R}^d \implies y\Delta S_{t+1}(\omega^t,\cdot) = 0 \; \mathcal{Q}_{t+1}(\omega^t)\text{-q.s.}
\]
\label{NAloc}
\end{definition}


\section{Main results}
\label{mainresult}

We are now able to state the paper\rq{}s main results, which proof\rq{}s are given in Section~\ref{proof_section}.

\begin{theorem}[Characterization of $NA(\mathcal{Q}^T)$]\label{main_result}
    Assume the (PD) axiom. The following conditions are equivalent under Assumptions~\ref{assumption_prices} and~\ref{assumption:graph_Q}.
    \begin{enumerate}
        \item[(i)]  $NA(\mathcal{Q}^T)$ holds true.
        \item[(ii)]  There exists $P^*\in \mathcal{Q}^T$ such that $\mathrm{Aff}(D_{P^*}^{t+1})(\cdot)=\mathrm{Aff}(D^{t+1})(\cdot) \ \mathcal{Q}^t\mbox{-q.s.}$  and $0 \in \mathrm{Ri}(\mathrm{Conv}(D_{P^*}^{t+1}))(\cdot) \ \mathcal{Q}^t\mbox{-q.s.}$ for all $t\in \{0,\dots,T-1\}$.
    \end{enumerate}
\end{theorem}
We denote by $\mathcal{H}_T$ the set containing all the probability measures $P^*$ as in (ii). So, Theorem~\ref{main_result} says that $NA(\mathcal{Q}^T)$ is equivalent to $\mathcal{H}_T \neq \emptyset$. 
Theorem~\ref{main_result} was proved by Blanchard and Carassus in the setup of Bouchard and Nutz (see \cite[Theorem 3.29]{blanchard2020}) and has been conjectured by Carassus and Ferhoune in the projective setup. The direction (ii) implies (i) has been proved there, see \cite[Lemma 1 (iv) and  Remark 3]{carassus2024}. Note that, for all $t\in \{0,\dots,T-1\}$, the $\mathcal{Q}^t$-full-measure set where   (ii) holds true is the set $\Omega_{NA}^t$ introduced in Proposition \ref{equivalence_local_global} below. 
\\

The next proposition gives the characterization of the single-prior no-arbitrage condition $NA(P)$, and so, generalizes \cite[Theorem 3]{JS98} to the projective setup. It is a direct consequence of Theorem \ref{main_result} applied to $\mathcal{Q}^{T}:=\{P\},$  with $P:=p_{1} \otimes p_{2} \otimes \dots \otimes p_{T}.$ 
This is not the case in the Bouchard and Nutz setting since  $\mbox{Graph}(p_{t})$ belongs a priori to $\mathcal{B}_{c}(\O^{t}) \otimes \mathcal{B}(\mathfrak{P}(\O_{t+1}))$ and not to the analytic sets of $\O^{t} \times  \mathfrak{P}(\O_{t+1})$.
\begin{proposition}[Characterization of $NA(P)$]
\label{singleP}
Assume the (PD) axiom.  Assume that  Assumption~\ref{assumption_prices} holds true  and let $P \in   \mathfrak{P}(\O^{T})$ with the fixed disintegration $P:=p_{1} \otimes p_{2} \otimes \dots \otimes p_{T}$ where  $p_{t} \in  SK_{t}$ for all  $t\in \{1,\ldots,T\}$. Then, the $NA(P)$ condition holds if and only if  $0 \in \mbox{Ri}(\mbox{Conv}(D_{P}^{t+1}))(\cdot)$ $P^{t}$-a.s. for all $0 \leq t \leq T-1$.
\end{proposition}

The last theorem generalizes \cite[Theorem 3.6]{blanchard2020} to the projective setup and is an easy consequence of Theorem \ref{main_result} and Proposition \ref{singleP}. It proposes a meaningfull caracterization of $NA(\mathcal{Q}^{T})$ by the existence of a subclass of priors $\mathcal{P}^{T} \subseteq \mathcal{Q}^{T}$ such that $\mathcal{P}^{T}$ and $ \mathcal{Q}^{T}$ have the same polar sets and $NA(P)$ holds for all $P \in \mathcal{P}^{T}$. Note that this is not the case for $\mathcal{Q}^{T}$, where some priors may lead to arbitrage. 
So, instead of $NA(\mathcal{Q}^{T})$, one may assume that every model in $\mathcal{P}^{T}$ is arbitrage-free. Under quasi-sure uncertainty, this characterization allows tractable theorems for the existence of solutions to the problem of robust utility maximisation (see  \cite{blanchard2020},  \cite{BCK19} or \cite{RaMe18}). 

\begin{theorem}[Characterization of $NA(\mathcal{Q}^T)$]
\label{TheoS}
Assume the (PD) axiom. The following conditions are equivalent under Assumptions~\ref{assumption_prices} and~\ref{assumption:graph_Q}. \begin{itemize}
 \item[(i)] $NA(\mathcal{Q}^{T})$ holds true.
 \item[(ii)]  There exists some $\mathcal{P}^{T} \subseteq \mathcal{Q}^{T}$  such that $\mathcal{P}^{T}$ and  $\mathcal{Q}^{T}$ have  the  same polar sets  and such that   $NA(P)$ holds  for all $P \in \mathcal{P}^{T}.$
\end{itemize}
\end{theorem}


To prove Theorem~\ref{main_result}, we start by working in a one-period framework (see Proposition~\ref{prop_construction_P_star} in the Appendix). Then, we generalize the result to the multi-period framework using measurable selection techniques to find stochastic kernels.  
However, it requires first proving that the quasi-sure no-arbitrage is consistent with the local no-arbitrage at each time step. This is Proposition~\ref {equivalence_local_global}, which generalizes \cite[Theorem 4.5]{bouchard2015} in the projective framework under the (PD) axiom.
% and allows us to work in a one-step model. 
%Giving an equivalence between the quasi-sure no-arbitrage and the existence, at each time step, of full-measure sets where the local no-arbitrage holds, the proposition shows that the model supports the idea of time consistency. This means that we can start from the one-period setting and 



\begin{proposition}[Equivalence between global and local no-arbitrage]\label{equivalence_local_global}
Assume the (PD) axiom. The following conditions are equivalent under Assumptions~\ref{assumption_prices} and~\ref{assumption:graph_Q}.
\begin{enumerate}
    \item[(i)] $NA(\mathcal{Q}^T)$ holds true.
    \item[(ii)] For all $t \in \{0, \dots, T-1\}$, there exists a projective set  $\Omega_{NA}^t$ of $\mathcal{Q}^t$-full-measure, such that $NA(\mathcal{Q}_{t+1}(\omega^t))$ holds true for all $\omega^t \in \Omega_{NA}^t$.
\end{enumerate}
\end{proposition}






\section{Proofs of the main results}\label{proof_section}
\label{proofs}
\subsection{Proof of Proposition~\ref{equivalence_local_global}}
We first show Proposition~\ref{equivalence_local_global}, which allows us to prove Theorem~\ref {main_result} from the one-period result given in Proposition~\ref{prop_construction_P_star} in the Appendix. The proof that (ii) implies (i) is based on the same kind of ideas as \cite[Lemma 4.6]{bouchard2015}, using Proposition \ref{prop_conseq_PD_axiom} instead of Jankov-von Neumann\rq{}s measurable selection theorem. But the proof that (i) implies (ii) differs completely from that of \cite[Theorem 4.5]{bouchard2015}. We prove the claim by induction on $T,$ as it can be done in the single-prior case, and this is possible thanks to Corollary~\ref{corollary_section_B_omega} in the appendix, which allows us to transform $\mathcal{Q}^{t+1}\mbox{-q.s.}$ inequality to $\mathcal{Q}_{t+1}(\omega^{t})\mbox{-q.s.}$ one for all $\o^t$ in a projective set of $\mathcal{Q}^t$-full-measure. To prove the same claim, Bouchard and Nutz rely on a third condition: the existence of a certain type of martingale measure. Their proof is therefore based on a measurable selection argument for martingale measures.\\

\noindent \textit{(ii) implies (i).} \\
Assume that (ii) holds. We prove inductively on $T$ that (ii) holds. \\
If $T=1$, $NA(\mathcal{Q}^{1})=NA(\mathcal{Q}_1(\omega^0))$ holds true as $\Omega^0=\{\omega^0\}$ and $\mathcal{Q}^1 = \mathcal{Q}_1(\omega^0)$.\\
We  fix $t\in \{1,\dots,T-1\}$ and assume the claim at time $t$, i.e. that if for all $s \in \{0, \dots, t-1\}$, there exists a projective set $\Omega_{NA}^s$ of $\mathcal{Q}^s$-full-measure, such that for all $\omega^s \in \Omega_{NA}^s, \; NA(\mathcal{Q}_{s+1}(\omega^s))$ holds true, then $NA(\mathcal{Q}^t)$ holds true.\\
Now, suppose that for all $s \in \{0, \dots, t\}$, there exists a projective set $\Omega_{NA}^s$ of $\mathcal{Q}^s$-full-measure, such that for all $\omega^s \in \Omega_{NA}^s, \; NA(\mathcal{Q}_{s+1}(\omega^s))$ holds true. We prove that $NA(\mathcal{Q}^{t+1})$ holds true. Note first that $NA(\mathcal{Q}^{t})$ holds by induction. Let $\phi \in \Phi$ such that $V_{t+1}^{0, \phi} \geq 0 \; \mathcal{Q}^{t+1}\mbox{-q.s}$. Lemma~\ref{lemma_portfolio_measurability} shows that $V_{t+1}^{0, \phi}(\cdot)$ is $\mathbf{P}(\Omega^{t+1})$-measurable under Assumption~\ref{assumption_prices}. Then Corollary~\ref{corollary_section_B_omega}, under the (PD) axiom and Assumption~\ref{assumption:graph_Q}, implies that there exists $\bar{\Omega}^t\subseteq \Omega^{t}$, a projective set of $\mathcal{Q}^{t}$-full-measure, such that for all $\omega^{t} \in \bar{\Omega}^t$ 
 \begin{equation}\label{inequality_V}
    V_{t+1}^{0, \phi}(\omega^{t},\cdot) \geq 0 \;\mathcal{Q}_{t+1}(\omega^{t})\mbox{-q.s}.    
    \end{equation}
Let $\tilde{\Omega}^t := \bar{\Omega}^t\cap\Omega_{NA}^{t}$. Then, as $\tilde{\Omega}^t$ is the intersection of two projective sets, $\tilde{\Omega}^t$ is projective (see Proposition~\ref{prop_properties_projective_functions} (ii)). Moreover, $\tilde{\Omega}^t$ is also of $\mathcal{Q}^{t}$-full-measure as an intersection of full-measure sets.
    Let $\omega^{t}\in \tilde{\Omega}^t$. The previous arguments show that 
    \begin{equation}\label{inequation_proposition_equivalence_global_local}
      \phi_{t+1}(\omega^t)\Delta S_{t+1}(\omega^{t},\cdot) \geq -V_{t}^{0, \phi}(\omega^{t})\; \mathcal{Q}_{t+1}(\omega^{t})\mbox{-q.s.}  
    \end{equation}
 Assume for a moment that $\{V_t^{0,\phi}\geq 0\}$ is of $\mathcal{Q}^t$-full-measure. Then, as  $NA(\mathcal{Q}^t)$ holds, we get that $V_t^{0,\phi}= 0 \; \mathcal{Q}^{t}\mbox{-q.s.}$ Considering~(\ref{inequation_proposition_equivalence_global_local}) for $\omega^t$ in the intersection of $\tilde{\Omega}^t$ and $\{V_t^{0,\phi}= 0\}$, which is a projective set of $\mathcal{Q}^{t}$-full-measure (see Lemma~\ref{lemma_portfolio_measurability} again), we get that $$\phi_{t+1}(\omega^t)\Delta S_{t+1}(\omega^{t},\cdot) \geq 0\; \mathcal{Q}_{t+1}(\omega^{t})\mbox{-q.s.}$$
So, we can apply the local no-arbitrage $NA(\mathcal{Q}_{t+1}(\omega^t))$ to get that $\phi_{t+1}(\omega^t)\Delta S_{t+1}(\omega^{t},\cdot) = 0\; \mathcal{Q}_{t+1}(\omega^{t})\mbox{-q.s.}$ Therefore, using Fubini's theorem (recall that we are on a projective and full-measure set), it follows that $\phi_{t+1}\Delta S_{t+1}=0 \; \mathcal{Q}^{t+1}\mbox{-q.s.}$ and also $V_{t+1}^{0,\phi}=0 \; \mathcal{Q}^{t+1}\mbox{-q.s.}$, meaning that $NA(\mathcal{Q}^{t+1})$ holds as well. \\
It remains to prove that $V_t^{0,\phi}\geq 0 \; \mathcal{Q}^{t}\mbox{-q.s.}$ We consider the function $\phi^*_{t+1}=\phi_{t+1} \mathbf{1}_{\{V_t^{0,\phi}< 0\}}$. We have that $\phi^*$ is $\mathbf{P}(\Omega^{t})$-measurable (see Proposition~\ref{prop_properties_projective_functions}). Let $\omega^t\in \tilde{\Omega}^t\subseteq \bar{\Omega}^t$, we have that $\mathcal{Q}_{t+1}(\omega^{t})\mbox{-q.s.}$ 
    \begin{align*}
    \phi^*_{t+1}\Delta S_{t+1}(\omega^t,\cdot) &\geq V_t^{0,\phi}(\omega^t)1_{\{V_t^{0,\phi}<0\}}(\omega^t)+\phi^*_{t+1}(\omega^t)\Delta S_{t+1}(\omega^t,\cdot) \\
    &=V_{t+1}^{0,\phi}(\omega^t,\cdot)1_{\{V_t^{0,\phi}<0\}}(\omega^t)\geq 0,
    % \; \mathcal{Q}_{t+1}(\omega^{t})\mbox{-q.s,} 
    \end{align*}
    where we have used (\ref{inequality_V}) for the last inequality. As $\omega^t\in \tilde{\Omega}^t\subseteq \Omega_{NA}^t,$ we can apply the local no-arbitrage $NA(\mathcal{Q}_{t+1}(\omega^t))$ and we get that $
    \phi^*_{t+1}\Delta S_{t+1}(\omega^t,\cdot) =0 \;\mathcal{Q}_{t+1}(\omega^{t})\mbox{-q.s.}
    $
So, for all $\omega^t\in \tilde{\Omega}^t$, $\mathcal{Q}_{t+1}(\omega^{t})\mbox{-q.s.}$
    \begin{align*}
        0 \leq V_{t+1}^{0,\phi}(\omega^t,\cdot)1_{\{V_t^{0,\phi}<0\}}(\omega^t) &= V_t^{0,\phi}(\omega^t)1_{\{V_t^{0,\phi}<0\}}(\omega^t)+\phi^*_{t+1}(\omega^t)\Delta S_{t+1}(\omega^t,\cdot)\\
        &= V_t^{0,\phi}(\omega^t)1_{\{V_t^{0,\phi}<0\}}(\omega^t) \leq 0.
        % \; \mathcal{Q}_{t+1}(\omega^{t})\mbox{-q.s.}
    \end{align*}
    Thus, $ V_{t}^{0,\phi}(\omega^t)1_{\{V_t^{0,\phi}<0\}}(\omega^t)=0$ for all $\omega^t\in \tilde{\Omega}^t$ which is of $\mathcal{Q}^t$-full-measure, and $V_{t}^{0,\phi}\geq 0 \; \mathcal{Q}^t\mbox{-q.s.}$ follows.\\

\noindent \textit{(i) implies (ii).} \\
Suppose now that $NA(\mathcal{Q}^{T})$ holds true. Fix $t\in \{0,\dots,T-1\}$.  Let 
$$\Omega_{NA}^t:= \bigl\{\omega^t\in \Omega^t:NA(\mathcal{Q}_{t+1}\bigl(\omega^t)\bigr) \; \mbox{holds}\bigr\}.$$
\noindent \textit{Step1: $\Omega_{NA}^t$ is a projective set.}\\
First, we rewrite the set $N^t$ where the local no-arbitrage fails:
    \vspace{-1em}
