        &=\mathrm{proj}_{\Omega^t}\bigl[\{(\omega^t,q,y)\in \Omega^t \times \mathfrak{P}(\Omega_{t+1}) \times \mathbb{R}^d: q\in\mathcal{Q}_{t+1}(\omega^t),\; \lambda_{\mathrm{inf}}(\omega^t,q,y)=1 \;\mathrm{and}\;\lambda(\omega^t,q,y)\in (0,1] \}\bigr]\\
