\noindent \textit{Step2: $\Omega_{NA}^t$ is a $\mathcal{Q}^t$-full-measure set.}\\    
Suppose by contraposition that $N^t$ is not $\mathcal{Q}^t$-polar. This means that $P^t[N^t]>0$ for some $P\in \mathcal{Q}^T$ having the disintegration $P:=p_1\otimes\dots\otimes p_T$. We apply now measurable selection to find an intertemporal strategy of arbitrage contradicting the quasi-sure no-arbitrage hypothesis.

    As $A\in\mathbf{P}(\Omega^t\times\mathfrak{P}(\Omega_{t+1})\times \mathbb{R}^d)$, Proposition~\ref{prop_conseq_PD_axiom} gives the existence of a function $\Xi=(q^*,\phi^*):\mathrm{proj}_{\Omega^t}(A)=N^t\to \mathfrak{P}(\Omega_{t+1})\times \mathbb{R}^d$, $\mathbf{P}(\Omega^t)$-measurable and such that $\mathrm{Graph}(\Xi)\subseteq A$.  
    %We denote by $q^*:N^t\to\mathfrak{P}(\Omega_{t+1})$ the first coordinate of $\Xi$ and by $\phi^*:N^t\to \mathbb{R}$ its second one. 
So, for all $\omega^t\in N^t,$ $q^*(\o^t)$ is a probability measure on $\Omega_{t+1}$ and we  write $q^*(\omega^t)=q^*(\cdot \mid \omega^t).$ 
Moreover, $ N^t \ni \omega^t  \mapsto  q^*(\cdot \mid \omega^t) \in \mathfrak{P}(\Omega_{t+1})$  is $\mathbf{P}(\Omega^t)$-measurable, 
and the inclusion $\mathrm{Graph}(\Xi)\subseteq A$ implies that for all $\omega^t\in N^t$, $q^*(\cdot \mid \omega^t)\in \mathcal{Q}_{t+1}(\omega^t).$ 
We also have that $\phi^*$ is $\mathbf{P}(\Omega^t)$-measurable and for all $\omega^t\in N^t$
    \begin{equation}\label{eq_inf_proof_Omega_NA}
     \inf_{p\in \mathcal{Q}_{t+1}(\omega^t)}p[\phi^*(\omega^t) \Delta S_{t+1}(\omega^t,\cdot)\geq 0]=1 \; \mathrm{and} \; q^*\bigl(\phi^*(\omega^t)\Delta S_{t+1}(\omega^t,\cdot) >0\mid \omega^t \bigr)>0.
    \end{equation}

    We set $\hat{\phi}_{t+1} := \phi^* $ on $N^t$, $\hat{\phi}_{t+1} := 0 $ on $\Omega^t\setminus N^t$, and $\hat{\phi}_s:=0$ for $s\neq t+1$. We also set $\hat{q}:=q^*$ on $N^t$, $\hat{q}:=\tilde{q}$ on $\Omega^t\setminus N^t$, where $\tilde{q} \in SK_{t+1}$ is such that $\tilde{q}(\cdot\mid\omega^t) \in \mathcal{Q}_{t+1}(\omega^t)$ for all $\omega^t\in \Omega^t$ ($\tilde{q}$ is obtained by performing measurable selection on $\mathrm{Graph}(\mathcal{Q}_{t+1})$ as Assumption~\ref{assumption:graph_Q} holds). This defines a strategy and a stochastic kernel, which are indeed projectively measurable (see Proposition~\ref{prop_properties_projective_functions} and the proof of Lemma~\ref{lemma_section_B_omega} where similar results are proved with more details). We now show that $\hat{\phi}$ is an arbitrage.

    Let $s\in \{1,\dots,T\}$. By construction of $\hat{\phi}\in \Phi$, for all $\omega^{s-1}\in \Omega^{s-1}$, $\hat{\phi}_s(\omega^{s-1}) \Delta S_s(\omega^{s-1},\cdot) \geq 0 \; \mathcal{Q}_s(\omega^{s-1})\mbox{-q.s.}$ (see (\ref{eq_inf_proof_Omega_NA})). Fubini's theorem is then applied to obtain that $\hat{\phi}_s \Delta S_s \geq 0 \; \mathcal{Q}^T\mbox{-q.s}$. We conclude that $$\displaystyle \sum_{s=1}^T\hat{\phi}_s \Delta S_s \geq 0 \; \mathcal{Q}^T\mbox{-q.s}.$$

    Moreover, we define $\hat{P} := P^t \otimes \hat{q} \otimes p_{t+2} \otimes \dots \otimes p_T.$    
    Then $\hat{P} \in \mathcal{Q}^T$ by construction, and using Fubini's theorem:
    \begin{align*}        
        \hat{P} \Bigl[ \sum_{s=1}^T \hat{\phi}_s \Delta S_s > 0 \Bigr] &= 
        \int_{\Omega^T} \mathbf{1}_{\{ \sum_{s=1}^T \hat{\phi}_s \Delta S_s > 0\}}(\omega^{T})
        \, \hat{P}(d\omega^{T}) \notag \\
        &= \int_{\Omega^{t+1}}\mathbf{1}_{\{ \hat{\phi}_{t+1} \Delta S_{t+1} > 0 \}}(\omega^{t+1}) 
        \, P^t\otimes \hat{q}(d\omega^{t+1}) \notag \\
        &= \int_{\Omega^t}   \int_{\Omega_{t+1}} \mathbf{1}_{\{ \hat{\phi}_{t+1} \Delta S_{t+1} > 0 \}}(\omega^t,\omega_{t+1}) 
        \,  \hat{q}(d\omega_{t+1}\mid \omega^{t})P^t(d\omega^{t}) \notag \\
        &=\int_{N^t}  q^*(\phi^*(\omega^t)\Delta S_{t+1}(\omega^t,\cdot) >0\mid \omega^t)P^t(d\omega^{t}) > 0,
    \end{align*}
    as the integral of a strictly positive function (see (\ref{eq_inf_proof_Omega_NA})) on a non-null set (relative to the measure $P^t$). 
    So, $\hat{\phi}$ is an intertemporal arbitrage, which contradicts $NA(\mathcal{Q}^T)$.








\subsection{Proof of Theorem ~\ref{main_result}.}


\textit{Reverse implication.} 

This is proved in \cite[Lemma 1 (iv)]{carassus2024}.\\


\textit{Direct implication.}\\
The proof is an adaptation of \cite[Theorem 3.29]{blanchard2020}'s one to the projective setup. 
Assume that $NA(\mathcal{Q}^T)$ holds true. Proposition~\ref{equivalence_local_global} shows that for all $t \in \{0, \dots, T-1\}$, there exists a projective set $\Omega_{NA}^t$ of $\mathcal{Q}^t$-full-measure, such that $NA(\mathcal{Q}_{t+1}(\omega^t))$ holds true for all $\omega^t \in \Omega_{NA}^t$.

\textit{Construction of $\mathcal{E}_{t+1}$ and measurable selection.}\\
%So, we define $\Omega^t_{NA} := \bigl\{ \omega^t \in \Omega^t \, ,  NA(Q_{t+1}(\omega^t)) \text{ holds true} \bigr\}$
Fix  $t \in \{0, \dots, T-1\}$. Let $\mathcal{E}_{t+1} : \Omega^t \twoheadrightarrow \mathfrak{P}(\Omega_{t+1})$ be defined 
%by  $\mathcal{E}_{t+1}(\omega^t) = \emptyset$  if and if $\omega^t \in \Omega^t_{NA}$,
for all $\omega^t \in \Omega^t$  by 
\[
\mathcal{E}_{t+1}(\omega^t) := \bigl\{ p \in \mathcal{Q}_{t+1}(\omega^t): \, 0 \in \text{Ri} \bigl( \text{Conv}(E^{t+1}) (\omega^t, p) \bigr) \mbox{ and } \text{Aff} ( E^{t+1})(\omega^t, p) = \text{Aff} \bigl( D^{t+1} \bigr)(\omega^t) \bigr\}.
\]
Let $\o^t \in \O^t$. Recalling Definitions \ref{NAloc} and \ref{NAone} and applying Proposition~\ref{prop_construction_P_star} in the Appendix, we get that 
\[
\begin{aligned}
\text{NA}\bigl(\mathcal{Q}_{t+1}(\omega^t)\bigr) \text{ holds true}
&\;\Longrightarrow\;
\exists\,p \in \mathcal{Q}_{t+1}(\omega^t) \;\text{with}\;
0 \in \mathrm{Ri}\Bigl(\mathrm{Conv}\,\bigl(E^{t+1}(\omega^t,p)\bigr)\Bigr) 
\\&\phantom{\;\Longleftrightarrow\;}\;\;
\text{and}\;\;
\mathrm{Aff}\bigl(E^{t+1}(\omega^t,p)\bigr)
=
\mathrm{Aff}\bigl(D^{t+1}(\omega^t)\bigr) \\
&\;\Longleftrightarrow\;
\mathcal{E}_{t+1}(\omega^t) \neq \emptyset.
\end{aligned}
\]
Thus, we deduce that $\Omega^t_{NA} \subseteq \{ \mathcal{E}_{t+1} \neq \emptyset \} $. Suppose for a moment that $\operatorname{Graph} (\mathcal{E}_{t+1} )$ is a projective set. Using Proposition~\ref{prop_conseq_PD_axiom} for $\operatorname{Graph} (\mathcal{E}_{t+1} )$  gives the existence  for all  $\o^t \in  \Omega^t_{NA}$ of 
$\hat p_{t+1}(\cdot|\o^t)  \in  \mathfrak{P}(\Omega_{t+1})$   such that 
$\Omega^t_{NA} \ni \o^t  \mapsto \hat p_{t+1}(\cdot|\o^t)\in  \mathfrak{P}(\Omega_{t+1})$ is projectively measurable  and  $\hat p_{t+1}(\cdot| \omega^t) \in \mathcal{E}_{t+1}(\omega^t) $ for every $\omega^t \in \Omega^t_{NA}$. Indeed, we have that $\text{proj}_{\O^t}\text{Graph}(\mathcal{E}_{t+1})= \{ \mathcal{E}_{t+1} \neq \emptyset \} \supseteq \Omega^t_{NA}. $ Let $\tilde{q}_{t+1}\in SK_{t+1} $ be obtained by performing measurable selection on $\mathrm{Graph}(\mathcal{Q}_{t+1})$ as Assumption~\ref{assumption:graph_Q} holds. We set ${q}^*_{t+1}:=\hat p_{t+1}$ on $\Omega^t_{NA}$ and  ${q}^*_{t+1}:=\tilde{q}_{t+1}$ on $\Omega^t\setminus\Omega^t_{NA}$. 
Define $P^* := p^*_1 \otimes \cdots \otimes p^*_T $. By construction of $P^*,$ as $\Omega^t_{NA}$  and $\Omega^t\setminus\Omega^t_{NA}$ are projective sets, we have that $P^* \in Q^T $. Furthermore, using Remark~\ref{EP_included_D} and  ${q}^*_{t+1}:=\hat p_{t+1}$ on $\Omega^t_{NA}$, we obtain for all $\omega^t \in \Omega^t_{NA}$ that 
\begin{eqnarray*}
\text{Aff} \bigl( D^{t+1}_{P^*} \bigr) (\omega^t) = \text{Aff} \bigl( E^{t+1} \bigr)\bigl(\omega^t, p^*_{t+1}(\cdot| \omega^t)\bigr) = \text{Aff} \bigl( E^{t+1} \bigr)\bigl(\omega^t, \hat{p}_{t+1}(\cdot| \omega^t)\bigr)=\text{Aff} \bigl( D^{t+1} \bigr)(\omega^t)
\\
0 \in \text{Ri} \Bigl( \text{Conv}(E^{t+1}) \bigl(\omega^t, \hat{p}_{t+1}(\cdot| \omega^t)\bigr) \Bigr) =\text{Ri} \Bigl( \text{Conv}(E^{t+1}) \bigl(\omega^t, p^*_{t+1}(\cdot| \omega^t)\bigr) \Bigr) = \text{Ri} \bigl( \text{Conv}(D^{t+1}_{P^*}) \bigr)(\omega^t),
\end{eqnarray*}
and this will conclude the proof as $\Omega_{NA}^t$ is a $\mathcal{Q}^t$-full-measure set.  

\textit{Proof of $\operatorname{Graph} (\mathcal{E}_{t+1} )\in 
\mathbf{P}(\Omega^t \times \mathfrak{P}(\Omega_{t+1})).$}\\
%we have established the existence of $\hat p_{t+1}$ on $ \Omega^t_{NA}$ such that $ \Omega^t_{NA} \ni \o^t  \mapsto \hat p_{t+1}(\cdot|\o^t)\in \mathfrak{P}(\Omega_{t+1})$ is projectively measurable and  $\hat p_{t+1}(\cdot| \omega^t) \in \mathcal{E}_{t+1}(\omega^t) $ for every $\omega^t \in \Omega^t_{NA}$. 
%Thus, it remains to establish the existence of $\hat p_{t+1} $. 
Let
\begin{eqnarray*}
B &  :=  &\bigl\{ (\omega^t, p)\in \Omega^t\times\mathfrak{P}(\Omega_{t+1}): \ \operatorname{Ri} \bigl(\overline{\operatorname{Conv}}(E^{t+1}) \bigr)(\omega^t, p) \cap \{ 0 \} \neq \emptyset \bigr\}\\ 
C & := & \bigl\{ (\omega^t, p)\in \Omega^t\times\mathfrak{P}(\Omega_{t+1}): \ \text{Aff} \bigl( E^{t+1} \bigr) (\omega^t, p) = \text{Aff} \bigl( D^{t+1} \bigr)(\omega^t) \bigr\}.
\end{eqnarray*}
Recall from Proposition~\ref{lemma_measurability_sets} (i) et (iii) that 
$
 \text{Ri} (\overline{\operatorname{Conv}}(E^{t+1}))
$
 is closed-valued and $\Delta^1_n (\Omega^t \times \mathfrak{P}(\Omega_{t+1})) $-measurable for some $n\geq 1$ and  that $\text{Aff} (D^{t+1} )$ 
is $\Delta^1_q(\Omega^t ) $-measurable for some $q\geq 1$. We assume without loss of generality that $q\leq n$, changing $n$ into  $\max(n,q)$ if necessary. So, using 
Proposition~\ref{prop_properties_projective_functions} (i) $\text{Aff} (D^{t+1} )$ 
is also $\Delta^1_n(\Omega^t ) $-measurable. \\
We apply \cite[Theorem 14.3]{RockafellarWets1998} in the measurable space $(\Omega^t \times \mathfrak{P}(\Omega_{t+1}), \Delta^1_n(\Omega^t \times \mathfrak{P}(\Omega_{t+1}))) $ and   we conclude that  $B  \in \Delta^1_n(\Omega^t \times \mathfrak{P}(\Omega_{t+1}))$. 
It also implies that $B \in \mathbf{P}(\Omega^t \times \mathfrak{P}(\Omega_{t+1})) $.\\
Let $h : \Omega^t \times \mathfrak{P}(\Omega_{t+1}) \to \mathbb{R} $ be defined by
\begin{eqnarray}
\label{eq:distance_definition}
h(\omega^t, p) := d \bigl( \operatorname{Aff} \bigl( E^{t+1}(\omega^t, p) \bigr), \operatorname{Aff} \bigl( D^{t+1}(\omega^t) \bigr) \bigr)
= \sup_{x \in \mathbb{R}^d} \Big| d \bigl( x, \operatorname{Aff} \bigl( E^{t+1}(\omega^t, p) \bigr) \bigr) 
- d \bigl( x, \operatorname{Aff} \bigl( D^{t+1}(\omega^t) \bigr) \bigr) \Big|. 
\end{eqnarray}
Here $d(F, G) $ is the Hausdorff distance between two nonempty sets $F, G \subseteq \mathbb{R}^d $, see for instance \cite[Definition 3.70 and Lemma 3.74]{AliprantisBorder2006} and $d(x, F) = \inf \{ |x-y|: \, y \in F \}.$ 
%where the symbol $|\,.\,|$ refers to the Euclidean norm on $\mathbb{R}^d$. 
Proposition~\ref{lemma_measurability_sets} (i) also shows that $\text{Aff} ( E^{t+1})$ 
is $\Delta^1_n(\Omega^t \times \mathfrak{P}(\Omega_{t+1})) $-measurable and 
applying  \cite[Theorem 18.5]{AliprantisBorder2006} with the same measurable space as before, 
%and the separable metric space $(\mathbb{R}^d, d) $, 
we  conclude that 
$$
\Omega^t \times \mathfrak{P}(\Omega_{t+1}) \times \mathbb{R}^d \ni \bigl((\omega^t, p), x\bigr)  \mapsto d\Bigl(x, \operatorname{Aff}\bigl(E^{t+1}(\omega^t, p)\bigr)\Bigr)
$$
is a Caratheodory function. This means that for every $x \in \mathbb{R}^d $, 
$
\Omega^t \times \mathfrak{P}(\Omega_{t+1}) \ni (\omega^t, p)  \mapsto d(x, \operatorname{Aff}(E^{t+1}(\omega^t, p)))
$
is $\Delta^1_n(\Omega^t \times \mathfrak{P}(\Omega_{t+1}))$-measurable and 
%(and also $\mathbf{P}(\Omega^t \times \mathfrak{P}(\Omega_{t+1}))$-measurable) 
for every $(\omega^t, p) \in \Omega^t \times \mathfrak{P}(\Omega_{t+1})$,  
$
\mathbb{R}^d \ni x \ \mapsto d(x, \operatorname{Aff}(E^{t+1}(\omega^t, p)))
$
is continuous. 
Now, we apply again
%Proposition~\ref{lemma_measurability_sets} (iii) shows that $\text{Aff} (D^{t+1} )$ is $\Delta^1_q(\Omega^t ) $-measurable and 
  \cite[Theorem 18.5]{AliprantisBorder2006} to $\text{Aff} (D^{t+1} )$ with the measurable space 
  $(\Omega^t, \Delta^1_n(\Omega^t ))$ and  
we get that 
$$
\Omega^t  \times \mathbb{R}^d  \ni (\omega^t, x) \mapsto d\Bigl(x, \operatorname{Aff}\bigl(D^{t+1}(\omega^t)\Bigl)\Bigl)
$$
is a Caratheodory function, which implies that  for every 
$x \in \mathbb{R}^d $, 
$
\Omega^t  \ni \omega^t  \mapsto d(x, \operatorname{Aff}(D^{t+1}(\omega^t)))
$
is $\Delta^1_n(\Omega^t )$-measurable  and 
for every $\omega^t\in \Omega^t $,  the function 
$
\mathbb{R}^d  \ni x \mapsto d(x, \operatorname{Aff}(D^{t+1}(\omega^t)))
$
is continuous. So, $
\mathbb{R}^d  \ni x  \mapsto | d \bigl( x, \operatorname{Aff} ( E^{t+1}(\omega^t, p) ) ) 
- d ( x, \operatorname{Aff} ( D^{t+1}(\omega^t) ) ) |
$ is continuous and 
we can replace $\mathbb{R}^d $ with $ \mathbb{Q}^d $ in \eqref{eq:distance_definition}. 
Then, Proposition~\ref{prop_properties_projective_functions} (v) and (viii)  shows that 
$(\omega^t, p)
\mapsto | d \bigl( x, \operatorname{Aff} ( E^{t+1}(\omega^t, p) ) ) 
- d ( x, \operatorname{Aff} ( D^{t+1}(\omega^t) ) ) |
$
is $\Delta^1_n(\Omega^t \times \mathfrak{P}(\Omega_{t+1})) $-measurable and that  $h $ is also $\Delta^1_n(\Omega^t \times \mathfrak{P}(\Omega_{t+1})) $-measurable, as a countable supremum. So, we obtain that 
$$C = h^{-1}(\{0\})  \in \Delta^1_n\bigl(\Omega^t \times \mathfrak{P}(\Omega_{t+1})\bigr)  \subseteq \mathbf{P}\bigl(\Omega^t \times \mathfrak{P}(\Omega_{t+1})\bigr).$$ 
As $\operatorname{Ri} (\overline{\operatorname{Conv}}(E^{t+1}) )=\operatorname{Ri} ({\operatorname{Conv}}(E^{t+1}) )$, see \cite[Theorem 6.3]{rockafellar1970convex}, 
Assumption~\ref{assumption:graph_Q} and Proposition~\ref{prop_properties_projective_functions} 
 (ii) show that 
\[
\operatorname{Graph} (\mathcal{E}_{t+1}) = \operatorname{Graph} (\mathcal{Q}_{t+1}) \cap B \cap C \in 
\mathbf{P}(\Omega^t \times \mathfrak{P}\bigl(\Omega_{t+1})\bigr).
\]
%for all such that  $\hat p_{t+1}(\cdot| \omega^t) \in \mathcal{E}_{t+1}(\omega^t) $ for all  $\omega^t \in \Omega^t_{NA} = \{ \mathcal{E}_{t+1} \neq \emptyset \} $.  
Now, the proof is complete.
\begin{remark}
In this proof, it is important at several stages to work with $\Delta^1_n$ and not $\mathbf{P}$. Indeed, we use that $\Delta^1_n$ is a sigma-algebra to apply \cite[Theorem 18.5]{AliprantisBorder2006} and get Caratheodory functions. We also need that the class of $\Delta^1_n$-measurable functions is closed by countable supremum. These two properties are not true for $\mathbf{P}$. 
\end{remark}




