$$\mbox{Aff} \bigl(D^{t+1}\bigr)(\o^{t}) = \mbox{Aff}\bigl(D_{P^*}^{t+1}\bigr)(\o^{t}) \subseteq \mbox{Aff} \bigl(D_P^{t+1}\bigr)(\o^{t}) \subseteq \mbox{Aff} \bigl(D^{t+1}\bigr)(\o^{t}).$$
As  $0 \in \mbox{Ri} ({\mbox{Conv}}(D_{P^*}^{t+1}))(\o^{t})$, there exists some $\varepsilon>0$ such that
$$
 B(0,\varepsilon) \bigcap \mbox{Aff}\bigl(D_{P}^{t+1}\bigr)(\o^{t}) =B(0,\varepsilon) \bigcap \mbox{Aff}\bigl(D_{P^*}^{t+1}\bigr)(\o^{t})
   \subseteq  {\mbox{Conv}}(D_{P^*}^{t+1})(\o^{t}) \subseteq {\mbox{Conv}}(D_{P}^{t+1})(\o^{t}),
$$
which concludes the proof of $0 \in  \mbox{Ri} ({\mbox{Conv}}(D_{P}^{t+1}))(\o^{t})$. 

\section{Appendix}
In this appendix, we first state and prove the results related to one-period models, which were used in the proof of Theorem ~\ref{main_result}. Then, we recall properties from \cite{carassus2024} on projective sets and functions. The next section proves technical results about the measurability of the supports, which were used in the proof of Theorem ~\ref{main_result}. Finally, we prove an extension of some results of  \cite{Carassus25} to the projective setup, which allows us to transform $\mathcal{Q}^{t+1}\mbox{-q.s.}$ inequality to $\mathcal{Q}_{t+1}(\omega^{t})\mbox{-q.s.}$ one for all $\o^t$ in a projective set of $\mathcal{Q}^t$-full-measure. This was crucial in the proof of Proposition~\ref{equivalence_local_global}


\subsection{One-period model}\label{subsection_one_period}

We introduce the one-period model and construct a probability measure for which the single-prior no-arbitrage condition holds in a quasi-sure sense. Let ${\Omega}$ be a Polish space, $\mathfrak{P}(\Omega) $ the set of all probability measures defined on ${\cal B}(\Omega) $, and $\mathcal{Q} $ a nonempty convex subset of $\mathfrak{P}(\Omega) $. 
%For $p \in \mathcal{Q} $ fixed, $E_p $ denotes the expectation under $p $. 
Let $Y $ be a ${\cal B}_c(\Omega)$-measurable $\mathbb{R}^d $-valued random variable. The following sets are the pendants in the one-period case of the ones introduced in Definition~\ref{def_conditional_supports}. 
Let $p \in \mathcal{Q} $,
\begin{align*}
    E(p) &:= \bigcap \{ A \subseteq \mathbb{R}^d: \text{closed}, \, p[Y(\cdot) \in A] = 1 \}, \\
    D &:= \bigcap \{ A \subseteq \mathbb{R}^d: \text{closed}, \, q[Y(\cdot) \in A] = 1, \, \forall q \in \mathcal{Q}\}. 
\end{align*}
We now state the pendant of the no-arbitrage conditions in the one-period framework.
\begin{definition}[Quasi-sure one-period no-arbitrage condition]
The condition $NA(\mathcal{Q})$ holds true if
\[
hY(\cdot) \geq 0 \; \mathcal{Q}\text{-q.s. for some } h\in \mathbb{R}^d \implies hY(\cdot) = 0 \; \mathcal{Q}\text{-q.s.}
\]
\label{NAone}
\end{definition}

\begin{definition}[Single-prior one-period no-arbitrage condition]
Let $p \in \mathcal{Q}$. The condition $NA(p)$ holds true if
\[
hY(\cdot) \geq 0 \; p\text{-a.s. for some } h\in \mathbb{R}^d \implies hY(\cdot) = 0 \; p\text{-a.s.}
\]
\end{definition}
Note that when $\mathcal{Q}=\{p\}$, $NA(\mathcal{Q})$ and $NA(p)$ coincide. 
