The following lemma recalls well-known results about supports and no-arbitrage in a one-period framework, which can, for example, be found in \cite{blanchard2020}. They are recalled for the reader's convenience.
\begin{lemma}\label{lemma_affine_hull_linear}
(i) If $0 \notin  \mathrm{Ri}(\mathrm{Conv}(D)),$ there exists some $h^* \in \mathrm{Aff}(D)$, $h^* \neq 0$ such that $h^* y \geq 0$ for all $y \in D$. \\
(ii) For any $h \in \mathbb{R}^d \setminus \{0\}$,
\begin{align}
\label{pareil1}
hY(\cdot) \geq 0 \; \mbox{$\mathcal{Q}$-q.s.} & \Longleftrightarrow h y \geq 0,\;  \forall y \in D\\
\label{pareil2}
hY(\cdot) = 0 \; \mbox{$\mathcal{Q}$-q.s.} & \Longleftrightarrow h y = 0,\;  \forall y \in D.
\end{align}
(iii) Let $p\in \mathcal{Q}$. For any $h \in \mathbb{R}^d \setminus \{0\}$,
\begin{align}
\label{pareil3}
hY(\cdot) \geq 0 \; \mbox{$p$-a.s.} & \Longleftrightarrow h y \geq 0,\;  \forall y \in E(p)\\
\label{pareil4}
hY(\cdot) =0 \; \mbox{$p$-a.s.} & \Longleftrightarrow h y = 0,\;  \forall y \in E(p).
\end{align}
(iv) Assume that $NA(\mathcal{Q})$ holds. Then, $0 \in \mathrm{Ri}(\mathrm{Conv}(D)).$ \\
(v)  Let $p\in \mathcal{Q}$. Assume that $NA(p)$ holds. Then, $0 \in \mathrm{Ri}(\mathrm{Conv}(E(p))).$
\end{lemma}
\begin{proof}
Assertion (i) is a classical exercise relying on a separation argument in $\mathbb{R}^{d}$, see  \cite[Theorems 11.1, 11.3]{rockafellar1970convex}).  
% or \citep[Proposition A.1]{fs}.
For (ii) and (iii), we only show \eqref{pareil1}. Indeed, \eqref{pareil2} will follow applying  \eqref{pareil1}  to $\pm h$. Then, \eqref{pareil3} and \eqref{pareil4} are obtained choosing $\mathcal{Q}=\{p\}.$ \\
We show the direct implication in \eqref{pareil1}. If there exists $y_0 \in D$ such that $h y_0<0$, then there exists some $\delta>0$ such that $hy<0$ for all $y \in B(y_0,\delta)$, where $B(y_0,\delta)$ is the open ball of radius $y_0$ and center $\delta$.  But by definition of $D$  there exists some $q \in \mathcal{Q}$ such that $q[Y(\cdot) \in B(y_0, \delta)]>0$, a contradiction. For the reverse implication, as in Remark \ref{EP_included_D}, 
%the one-period result  \cite[Lemma 4.2]{bouchard2015} (which just requires that $D$ is a set of probability measures)  to get that 
$D$ is a closed set of $\mathbb{R}^d$
%$A\subseteq \mathbb{R}^d$ such that $q(A) = 1$ for all  $q \in \mathcal{Q}$. 
such that $q[ Y(\cdot) \in {D}] =1$ for all $q \in \mathcal{Q}$. As $Y(\cdot)$ is ${\cal B}_c(\Omega)$-measurable, $\{ Y(\cdot) \in {D}\} \in {\cal B}_c(\Omega)$ and $hY(\cdot) \geq 0$  $\mathcal{Q}$-q.s.

We prove (iv). If $0 \notin \mathrm{Ri}(\mathrm{Conv}(D)),$ (i) implies that there exists some $h^* \in \mbox{Aff}(D)$, $h^* \neq 0$ such that $h^* y \geq 0$ for all $y \in D$ or equivalently $h^* Y(\cdot) \geq 0$ $\mathcal{Q}$-q.s. using \eqref{pareil1}. As $NA(\mathcal{Q})$ holds true, $h^* Y(\cdot) = 0$ $\mathcal{Q}$-q.s. or $h^* y = 0$ for all $y \in D$ using \eqref{pareil2}. Thus, 
$$h^* \in D^\perp:=\bigl\{h\in\mathbb{R}^d: h y=0, \forall y \in D\bigr\}=(\mathrm{Aff}(D))^\perp$$ 
and also $h^* \in (\mathrm{Aff}(D))^\perp \cap \mathrm{Aff}(D)$. So, $h^*=0$ and we get a contradiction. 
Finally, (v) follows from (iv) choosing $\mathcal{Q}=\{p\}.$
%This relies on a simple separation argument. We prove $(i)$. Indeed, if $0\notin \mathrm{Aff}(D)$, there exists a strongly separating hyperplane between the compact convex closed set $\{0\}$ and the convex and closed set $\mathrm{Aff}(D)$ (see \cite[Corollary 11.4.2 p.99]{rockafellar1970convex}), and using \cite[Theorem 11.1 p.95]{rockafellar1970convex}, there exists $h\in \mathbb{R}^d$ such that $\inf_{y\in D}hy\geq \inf_{y\in \mathrm{Aff}(D)}hy>\sup_{y\in \{0\}}hy=0$. Now for all $q\in \mathcal{Q}$, $q(hY(\cdot)>0)\geq q(Y(\cdot)\in D)=1$. This means that $hY(\cdot)> 0 \; \mathcal{Q}\mbox{-q.s.}$ leading to an arbitrage.
%The assertion $(ii)$ is simply $(i)$ when $\mathcal{Q}$ is a singleton. 
\end{proof}


