The following proof is partially inspired from \cite[Lemma 2.2]{bayraktar2017arbitrage} which gives the existence of some $\hat{p}  \in \mathcal{Q}$ such that $NA(\hat{p} )$  holds true and $\mbox{Aff}(E(\hat{p} ))=\mbox{Aff}(D)$. 
\begin{proposition}[Construction of $P^*$ in the one-period case]\label{prop_construction_P_star} Assume that $\mathcal{Q}$ is nonempty and convex and that the one-period $NA(\mathcal{Q})$ condition holds. Then there exists some $\hat{p}  \in Q $ such that $0 \in \mathrm{Ri}(\mathrm{Conv}(E(\hat{p} ))) $ and $\mathrm{Aff}(E(\hat{p} )) = \mathrm{Aff}(D) $.
\end{proposition}
%The proof is given for self-sufficiency. 
\begin{proof}
%[Proof of Proposition~\ref{prop_construction_P_star}.]
 Assume that the quasi-sure one-period no-arbitrage $NA(\mathcal{Q})$ holds true and that $\mathcal{Q}$ is nonempty and convex. As  $0\in \mathrm{Aff}(D)$ (see Lemma~\ref{lemma_affine_hull_linear}), $\mathrm{Aff}(D)$ is a linear subspace of $\mathbb{R}^d$. We denote for all $q\in\mathcal{Q}$, 
 $$N(q):=\{h\in\mathbb{R}^d:hY(\cdot)=0\;q\mbox{-a.s}\} \mbox{ and } N(\mathcal{Q}):=\{h\in\mathbb{R}^d:hY(\cdot)=0\;\mathcal{Q}\mbox{-q.s}\}.$$ Then, using  Lemma~\ref{lemma_affine_hull_linear},
    \begin{eqnarray*} \label{la}
    \mathrm{Aff}(D)^\perp:=\bigl\{h\in\mathbb{R}^d: h y=0, \forall y \in \mathrm{Aff}(D)\bigr\}=D^\perp=N(\mathcal{Q}).
    \end{eqnarray*}
Let \begin{equation}\label{defqbar}
\bar{\mathcal{Q}}=\bigl\{ p\in  \mathcal{Q}:  {p}[hY(\cdot)< 0]>0, \forall h\in \mathrm{Aff}(D)\cap S(0,1)\bigr\},
    \end{equation}
with $S(0,1):=\{x\in\mathbb{R}^d: |x|=1\}$ (recall that $|x|$ is the Euclidian norm of  $x\in \mathbb{R}^d$). \\
 \noindent  {\it Step 1: $\bar{\mathcal{Q}}$ is nonempty.}\\
Let $h\in \mathrm{Aff}(D)\cap S(0,1)$.  There exists $p_h\in \mathcal{Q}$ such that $p_h[hY(\cdot)< 0]>0$. If not, then $hY(\cdot)\geq 0 \; \mathcal{Q}\mbox{-q.s.}$ and $NA(\mathcal{Q})$ implies that $hY(\cdot)= 0 \; \mathcal{Q}\mbox{-q.s.}$, which means that $h\in N(\mathcal{Q})=\mathrm{Aff}(D)^\perp$. Thus, $h\in\mathrm{Aff}(D)\cap \mathrm{Aff}(D)^\perp =\{0\}$. This is impossible because $|h|=1$. 
Furthermore,  
%using separation arguments in $\mathbb{R}^{d}$, see for example \cite[Theorems 11.1, 11.3]{rockafellar1970convex}, 
%the nonempty convex and compact set $\{h\}$ and the nonempty convex and closed set $A:=\{x\in \mathbb{R}^d:xY(\cdot)\geq 0 \; p_h\mbox{-a.s.}\}$ are strongly separable (see \cite[Corollary 11.4.2 p.99]{rockafellar1970convex}), thus there exists an affine hyperplane $H$ strongly separating these two sets. It follows that for some 
there exists $\epsilon_h>0$  such that 
%$B(h,\epsilon_h):=\{h'\in\mathbb{R}^d:|h'-h|<\epsilon_h\}$ such that $B(h,\epsilon_h)\cap A=\emptyset$, which means that
    \begin{equation}\label{equation_proof_construction_P_star}
        p_h[h'Y(\cdot)<0]>0 \; \text{for all} \; h'\in  B(h,\epsilon_h). 
    \end{equation}
Now, using that $\mathrm{Aff}(D)\cap S(0,1)$ is compact in $\mathbb{R}^d$, one can extract a finite subcover of the open cover $\cup_{h\in \mathrm{Aff}(D)\cap S(0,1)}B(h,\epsilon_h).$ So, there exist $k\geq1$ and $h_i\in \mathrm{Aff}(D)\cap S(0,1)$ for all $i\in \{1,\ldots,k\}$ such that 
$\mathrm{Aff}(D)\cap S(0,1)\subseteq\bigcup_{i=1}^k B(h_i,\epsilon_i)$  setting $\epsilon_i=\epsilon_{h_i}.$ We associate to each $h_i$,  the probability $p_{h_i}\in \mathcal{Q}$ constructed above (i.e. satisfying \eqref{equation_proof_construction_P_star}) and we set 
$$\bar{p}:=\frac{1}{k}\sum_{i=1}^k  p_{h_i}.$$ Then, $\bar{p}\in \mathcal{Q}$ by convexity. 
    Furthermore, for all $h\in \mathrm{Aff}(D)\cap S(0,1)$, we have that $h\in B(h_j,\epsilon_j)$ for a certain $j\in \{1,\ldots,k\}$, %(by definition of the finite cover), 
