    \begin{eqnarray*}\label{construction_bar_p}
        \bar{p}[hY(\cdot)<0]=\frac{1}{k}\sum_{i=1}^k  p_{h_i}[hY(\cdot)<0]\geq \frac{1}{k}p_{h_j}[hY(\cdot)<0]>0.
