% We can, therefore, define its dimension and its orthogonal space without reference to a point. 
We also have the inclusion $E(q)\subseteq D$ (see Remark~\ref{EP_included_D}). So, $\mathrm{Aff}(E(q))\subseteq \mathrm{Aff}(D)$.  
Now, we set $\delta:$ $ \bar{\mathcal{Q}} \ni q \mapsto dim(\mathrm{Aff(E(q))})$.  As $\delta(\bar{\mathcal{Q}})$ is a nonempty subset of $\{0,\dots,d\}$, $m:=\max_{\bar{\mathcal{Q}}} \delta$ is attein by  some $\hat p\in\bar{\mathcal{Q}}$ and we have that 
$$\delta(\hat p)=m=\max_{\bar{\mathcal{Q}}}\delta=dim\Bigl(\mathrm{Aff}\bigl(E(\hat p)\bigr)\Bigr) \leq dim \bigl(\mathrm{Aff}(D)\bigr).$$
Using Lemma~\ref{lemma_affine_hull_linear},
    \begin{eqnarray*}\label{lap}
    \mathrm{Aff}\bigl(E(\hat p)\bigr)^\perp:=\bigl\{h\in\mathbb{R}^d: h y=0, \forall y \in \mathrm{Aff}\bigl(E(\hat p)\bigr)\bigr\}=\bigl(E(\hat p)\bigr)^\perp=N(\hat p).
    \end{eqnarray*}
Now, we prove that  $\mathrm{Aff}(E(\hat p))=\mathrm{Aff}(D)$. Else,  suppose that $\mathrm{Aff}(E(\hat p))\subsetneq\mathrm{Aff}(D).$ Let  $d_D:=\dim \mathrm{Aff}(D).$  
%and  $\dim(\mathrm{Aff}(E(\hat{p})))<\dim(\mathrm{Aff}(D))$, i.e. $\dim \, N(\hat{p})> \dim \, N(\mathcal{Q})$. 
  First, we show that 
  $$[\mathrm{Aff}(D)\setminus\mathrm{Aff}(E(\hat{p}))]\bigcap N(\hat{p}) \neq \emptyset.$$ 
  %using the hypothesis of strict inclusion of $\mathrm{Aff}(E(\hat{p}))\subset \mathrm{Aff}(D)$. 
Let $B:=(b_1,\dots,b_{d})$ be an orthonormal basis  of $\mathbb{R}^d$, adapted to the decomposition of $\mathbb{R}^d=\mathrm{Aff}(E(\hat{p}))\oplus N(\hat{p})$, which $m$ first vectors make a basis of $\mathrm{Aff}(E(\hat{p}))$, and which $d_D$ first vectors make a basis of $\mathrm{Aff}(D)$. Then, $m<d_D$. We consider $b_{m+1}$. We have that $b_{m+1}\in[\mathrm{Aff}(D)\setminus\mathrm{Aff}(E(\hat{p}))]\cap N(\hat{p})$. Indeed, remember that $b_{m+1}\in\mathrm{Aff}(D)$. Moreover, let $\ell:=\sum_{i=1}^m \mu_ib_i \in\mathrm{Aff}(E(\hat{p}))$, where $\mu_1,\dots,\mu_m\in\mathbb{R}$, then $b_{m+1}\ell=\sum_{i=1}^m \mu_ib_{m+1}b_i=0.$ Thus,  $b_{m+1}\in\mathrm{Aff}(E(\hat{p}))^\perp = N(\hat{p})$. Finally, $b_{m+1}\notin \mathrm{Aff}(E(\hat{p}))$, else  
  %because $b_{m+1}\in \mathrm{Aff}(E(\hat{p}))$ would mean that 
$b_{m+1}\in \mathrm{Aff}(E(\hat{p}))\cap\mathrm{Aff}(E(\hat{p}))^\perp = \{0\}$, but $b_{m+1}\neq 0$. We set $h^*:=b_{m+1}\in[\mathrm{Aff}(D)\setminus\mathrm{Aff}(E(\hat{p}))]\cap N(\hat{p}).$ Note again that $h^*\neq 0$. 

Now, as $h^*\in \mathrm{Aff}(D)$ and  $\mathrm{Aff}(D)\cap\mathrm{Aff}(D)^\perp=\{0\}$, we have that $h^*\notin \mathrm{Aff}(D)^\perp=N(\mathcal{Q})$, which means that there exists $q^*\in\mathcal{Q}$ such that $q^*[h^*Y(\cdot)\neq 0]>0$.  
We set $p'=\frac{\hat{p}+q^*}{2}$. By convexity $p'\in \mathcal{Q}$. Remark that $N(p')\subseteq N(\hat{p})$. Indeed, let $\ell \in N(p')$, then $\frac{\hat{p}+q^*}{2}[\ell Y(\cdot)=0]=1$, and necessarily $\hat{p}[\ell Y(\cdot)=0]=1$ as well, thus $\ell \in N(\hat{p})$. Moreover, $N(p')\subsetneq N(\hat{p})$. Indeed,  $h^*\in N(\hat{p})$ and as
$$p'[h^*Y(\cdot)\neq0]=\frac{\hat{p}+q^*}{2}[h^*Y(\cdot)\neq0]\geq \frac{q^*}{2}[h^*Y(\cdot)\neq0]>0$$ we have that $h^*\notin N(p').$  
So,  $N(p')\subsetneq N(\hat{p})$ and $\mathrm{Aff}(E(\hat p))\subsetneq \mathrm{Aff}(E(p')).$ Thus, $\delta (\hat p) <\delta(p')$, a contradiction to the maximality of $\hat{p}$ for $\delta$. So, $\mathrm{Aff}(E(\hat p))=\mathrm{Aff}(D)$. \\
 \noindent  {\it Step 4: conclusion.}\\
In Step 3, we have construct $\hat{p} \in \bar{\mathcal{Q}}$, such that $\mathrm{Aff}(E(\hat p))=\mathrm{Aff}(D)$.  
As $\hat{p} \in \bar{\mathcal{Q}},$ by Step 2, $NA(\hat{p})$ holds true and Lemma \ref{lemma_affine_hull_linear} implies that $0\in \mathrm{Ri}(\mathrm{Conv}(E(\hat{p}))$, which concludes the proof. 
