%$h^* \in N(\hat{p})^\perp=(Aff N(\hat{p}))^\perp$ and $h^*=0$, a contradiction. 
\end{proof}




\subsection{Properties of projective sets and functions}
We present key properties of projective sets and functions used in our proofs.
\begin{proposition}[Properties of projective sets and  functions]\label{prop_properties_projective_functions}

Let $X, Y$ and $Z $ be Polish spaces.
\begin{itemize}
        \item[(i)] The sequence $(\Delta_n^1(X))_{n \geq 1}$ is a nondecreasing sequence of sigma-algebras.
    \item[(ii)] The class $\mathbf{P}(X)$ is closed under complements, finite unions and finite intersections. 
    %Moreover, $f : X \to Y$ is $\mathbf{P}(X)$-measurable. Then, for all $n\geq 1$ and for all $B \in \Delta_{n}^1(Y)$, $f^{-1}(B)\in  \Delta_{p+n}^1(X)$.
    If $A\in\mathbf{P}(X\times Y)$, then $\mathrm{proj}_X(A)\in\mathbf{P}(X)$, while  if $A\in\Sigma_n^1 (X\times Y)$ for some $n\geq 1$, then $\mathrm{proj}_X(A)\in\Sigma_n^1 (X).$
    \item[(iii)] Let $n\geq 1$. We have that $\Delta_n^1(X)\times\Delta_n^1(Y)\subseteq\Delta_n^1(X\times Y),$  $\mathbf{P}(X)\times\mathbf{P}(Y)\subseteq\mathbf{P}(X\times Y)$ and 
    \begin{eqnarray}
\Sigma_n^1(X)  \subseteq \Delta_{n+1}^1(X). \label{eq(v)_pj}
\end{eqnarray}
    \item[(iv)] Let $f: X\to \mathbb{R}^p$ and $g : X \to \mathbb{R}^p$  for some $p\geq 1$. 
    If $f$ and $g$ are projective functions, then $-f$, $fg$ and $f+g $ are also projective.
        \item[(v)]  For all $n\geq 0$, let $f, f_n, g : X \to \mathbb{R}\cup \{-\infty,+\infty\}$.
Let $p \geq 1$. Assume that $f$, $f_n$ and $g$ are $\Delta_p^1(X)$-measurable for all $n\geq 0$. Then,  $f+g$, $-f$, $\min(f,g)$, $\max(f,g)$, $\inf_{n\geq 0} f_n$, $\sup_{n\geq 0} f_n$ are $\Delta_p^1(X)$-measurable. Now, if $f$  and $g$ are projective functions, then $f+g$, $-f$, $\min(f,g)$ and $\max(f,g)$ are also projective.
     \item[(vi) ]       Let $g: D \to Y$ and $f : E \to Z$ where $D\subseteq X$ and $g(D)\subseteq E \subseteq Y$.   Assume that $f$ is $\Delta_p^1(Y)$-measurable and that $g$ is $\Delta_q^1(X)$-measurable for some $p, q\geq 1$. Then, $f\circ g$ is $\Delta_{p+q}^1(X)$-measurable. Assume that $f$ and $g$ are projective functions. Then, $f\circ g$ is also projective.
    \item[(vii) ] Let $h : X\times Y \to Z.$ Assume that $h$ is a projective function. Then $h(x,\cdot) : y \mapsto h(x,y)$ is projective for all $x\in X$, while $h(\cdot,y) : x \mapsto h(x,y)$ is projective for all $y\in Y$.
 \item[(viii)] Let $f : X \to Z$ and $h : X  \times Y \to  Z$ be defined by $h(x,y) := f(x)$ for all $(x,y)\in X\times Y$. If $f$ is $\Delta_p^1(X)$-measurable for some $p\geq 1$, then $h$ is $\Delta_p^1(X \times Y)$-measurable.  If $f$ is a projective function, then $h$ is also projective.
 %Let $p\geq 1$ and assume that $f : X \to Y$ is $\Delta_p^1(X)$-measurable. Then, for all $n\geq 1$ and for all $B \in \Delta_{n}^1(Y)$, $f^{-1}(B)\in  \Delta_{p+n}^1(X)$.
\end{itemize}
\end{proposition}
\begin{proof}
    Items (i) to (iii) are proved by applying \cite[Proposition 1]{carassus2024}. Note that for the projection properties in (ii), we choose the direct image with the Borel function $f:=\mathrm{proj}_X$ in \cite[Proposition 1 (i) and (vi)]{carassus2024}. Then, (iv) is proved in \cite[Lemma 4]{carassus2024}, (v)  in \cite[Proposition 4]{carassus2024}, 
  (vi)  in \cite[Proposition 3]{carassus2024}, (vii)  in \cite[Corollary 2]{carassus2024} and, finally, (viii) follows from  \cite[Lemma 2]{carassus2024}. 
\end{proof}
\begin{proposition}[Integral of projective functions] 
Assume the (PD) axiom. Let $X$ and $Y$ be Polish spaces. Let $f : X \times Y \to \mathbb{R}\cup\{-\infty,+\infty\}$ and let $q$ be a stochastic kernel on $Y$ given $X$. Let $\lambda : X  \to \mathbb{R}\cup\{-\infty,+\infty\}$ be defined by $$\lambda(x):=\int_{-} f(x,y)q(dy|x).$$
\noindent (i) Assume that $X \ni x\mapsto q(\cdot|x) \in \frak{P}(Y)$ is $\Delta_r^1(X)$-measurable for some $r\geq 1$ and that $f$ is $\Delta_p(X\times Y)$-measurable for some $p\geq 1$. Then, $\lambda$ is $\Delta_{p+r+2}^1(X)$-measurable.\\
\noindent (ii) Assume that $X \ni x\mapsto q(\cdot|x) \in \frak{P}(Y)$ is projectively measurable and that $f$ is a projective function. Then, $\lambda$ is also a projective function.
\label{prj_cvt_pj}
\end{proposition}
\begin{proof}
    This is exactly  \cite[Proposition 10]{carassus2024}. 
\end{proof}
\subsection{Projective measurability of portfolio values and of the supports.}

We now prove the measurability of the portfolio values and of the supports. 

\begin{lemma}[Projective measurability of portfolio values]\label{lemma_portfolio_measurability}
    Assume Assumption~\ref{assumption_prices}. For all $t\in\{1,\dots,T\}$, $x\in \mathbb{R}$ and $\phi \in  \Phi$,  $ \Omega^{t} \ni \omega^t \mapsto V_t^{x,\phi}(\omega^t)$ is $\mathbf{P}(\Omega^t)$-measurable, and for all $\omega^{t-1}\in \Omega^{t-1}$, $ \Omega_{t} \ni \omega_{t}  \mapsto V_{t}^{x,\phi}(\omega^{t-1},\omega_{t})$ is $\mathbf{P}(\Omega_{t})$-measurable. 
\end{lemma}

\begin{proof}
Let $t \in \{1, \dots, T\} $, $V_t^{x, \phi} = x + \sum_{s=1}^{t} \phi_s\Delta S_s$. Let $ s\in \{1,\ldots,t\}$. We have that $\phi_{s} $ is $\mathbf{P}(\Omega^{s-1}) $-measurable by definition of $\Phi$, and 
also that $ \Omega^t \ni \omega^t \mapsto \phi_{s}(\omega^{s-1})$ is $\mathbf{P} (\Omega^t) $-measurable by Proposition~\ref{prop_properties_projective_functions} (viii). 
By Assumption~\ref{assumption_prices},  $S_s $ is $\mathbf{P} (\Omega^s) $-measurable, Proposition~\ref{prop_properties_projective_functions} (viii) and (iv)  shows that  $\Omega^t \ni \omega^t \mapsto \phi_s(\omega^{s-1}) (S_{s}(\omega^{s}) -S_{s-1}(\omega^{s-1}))$ is $\mathbf{P}(\Omega^t) $-measurable, and then that $ \Omega^t \ni \omega^t \mapsto V_t^{x,\phi}(\omega^t)$ is $\mathbf{P}(\Omega^t)$-measurable.
Now, Proposition~\ref{prop_properties_projective_functions} (vii) shows that $\Omega_{t} \ni \omega_{t}  \mapsto V_{t}^{x,\phi}(\omega^{t-1},\omega_{t})$ is $\mathbf{P}(\Omega_{t})$-measurable for all $\omega^{t-1}\in \Omega^{t-1}$.
\end{proof}

The following proposition generalizes \cite[Lemma 2.6]{blanchard2020}   using similar ideas as in \cite[Proposition 12]{CF24}. 
\begin{proposition}[Projective measurability of the supports] \label{lemma_measurability_sets}
Assume the (PD) axiom and let \textit{Assumptions}~\ref{assumption_prices} \textit{and} \ref{assumption:graph_Q} hold true. Let $0 \leq t \leq T-1 $ be fixed.  
\begin{itemize}
\item[(i)]  The random sets $E^{t+1},  \ \overline{\operatorname{Conv}}(E^{t+1}), \ \operatorname{Aff}(E^{t+1}),  \ \operatorname{Ri} (\overline{\operatorname{Conv}}(E^{t+1}) ) $ are nonempty, closed-valued and $\Delta^1_n (\Omega^t \times \mathfrak{P}(\Omega_{t+1})) $-measurable for some $n \geq 1$, and thus also $ \mathbf{P}(\Omega^t \times \mathfrak{P}(\Omega_{t+1})$-measurable.     
\item[(ii)] Let $P \in \mathcal{Q}^T.$ The random sets $D_P^{t+1},  \ \overline{\operatorname{Conv}}(D^{t+1}_P),  \ \operatorname{Aff}(D^{t+1}_P),  \ \operatorname{Ri} (\overline{\operatorname{Conv}}(D^{t+1}_P) )  $ are nonempty, closed-valued and $\Delta^1_{m} (\Omega^t) $-measurable for some $m \geq n+1$,  and thus   also 
   $\mathbf{P}(\Omega^t) $-measurable. 
\item[(iii)] The random sets $D^{t+1},  \ \overline{\operatorname{Conv}}(D^{t+1}),  \ \operatorname{Aff}(D^{t+1}),  \ \operatorname{Ri} (\overline{\operatorname{Conv}}(D^{t+1}) ) $ are nonempty, closed-valued and $\Delta^1_q (\Omega^t) $-measurable for some $q \geq 1 $, and thus   also
   $\mathbf{P}(\Omega^t) $-measurable.

\end{itemize}
\end{proposition}
\begin{proof}
Recall that $0 \leq t \leq T-1 $ is fixed.  Fix also some open set $O \subseteq \mathbb{R}^d$. \\
{\it Proof of (i).}\\
First, we show that 
$
\Omega^t \times \mathfrak{P}(\Omega_{t+1}) \ni (\omega^t, p)  \mapsto p[ \Delta S_{t+1}(\omega^t, \cdot) \in O ]
$
is $\Delta^1_n (\Omega^t \times \mathfrak{P}(\Omega_{t+1}) )$-measurable for some $n\geq 1$.  
Assumption~\ref{assumption_prices} and Proposition \ref{prop_properties_projective_functions} (iv) and (viii) imply that $\Omega^{t+1} \ni \omega^{t+1}  \mapsto \Delta S_{t+1}(\omega^{t+1})$
is $\mathbf{P}(\Omega^{t+1}) $-measurable and thus   $\Delta^1_r (\Omega^{t+1}) $-measurable, for some $r \geq 1.$  
We apply Proposition \ref{prj_cvt_pj}  to the stochastic kernel $q$ defined by $q(d\omega_{t+1}|(p,\o^t))=p(d\omega_{t+1})$, which is Borel 
%(see \cite[Proposition 7.25]{Bertsekas1978}) 
and thus $\Delta^1_1(\mathfrak{P}(\Omega_{t+1})\times \O^t) $-measurable and the function $f$ defined by $f(p,\o^t,\omega_{t+1})=\mathbf{1}_{\{\Delta S_{t+1}(\omega^t, \omega_{t+1}) \in O\}}$ which is $\Delta^1_r (\mathfrak{P}(\Omega_{t+1})\times \O^{t+1}) $-measurable (see Proposition \ref{prop_properties_projective_functions} (viii) again). Thus, 
$$
 \mathfrak{P}(\Omega_{t+1})  \times \Omega^t \ni (p,\omega^t) \mapsto\int_{\Omega_{t+1}} \mathbf{1}_{\{\Delta S_{t+1}(\omega^t, \omega_{t+1}) \in O\}} \, p(d\omega_{t+1})
$$
is $\Delta^1_{r+3} (\mathfrak{P}(\Omega_{t+1})\times \O^{t}) $-measurable. As $(\omega^t,p) \mapsto (p,\omega^t)$ is $\Delta^1_1( \O^t \times\mathfrak{P}(\Omega_{t+1})) $-measurable, we get that $
 \Omega^t \times \mathfrak{P}(\Omega_{t+1}) \ni (\omega^t, p)  \mapsto p[ \Delta S_{t+1}(\omega^t, \cdot) \in O ] 
$ is $\Delta^1_{r+4} ( \O^t \times\mathfrak{P}(\Omega_{t+1})) $-measurable (see Proposition \ref{prop_properties_projective_functions} (vi)). 
It follows that 
\begin{align*}
    A & :=\Big\{ (\omega^t, p) \in \Omega^t \times \mathfrak{P}(\Omega_{t+1}): \ E^{t+1} (\omega^t, p) \cap O \neq \emptyset \Big\} \\
    &= \Big\{ (\omega^t, p) \in  \Omega^t \times \mathfrak{P}(\Omega_{t+1}): \ p \big[\Delta S_{t+1} (\omega^t, .) \in O \big] > 0 \Big\} \in   \Delta^1_{r+4} (\Omega^t \times \mathfrak{P}(\Omega_{t+1})). 
\end{align*}
So, we have proved the $\Delta^1_{r+4} (\Omega^t \times \mathfrak{P}(\Omega_{t+1})) $-measurability of $E^{t+1} $. Applying \cite[Proposition 14.2, Exercise 14.12]{RockafellarWets1998} and \cite[Lemmata 5.2 and 5.7]{Artstein} 
in the measurable space $(\Omega^t \times \mathfrak{P}(\Omega_{t+1}), \Delta^1_n (\Omega^t \times \mathfrak{P}(\Omega_{t+1}))) $ with $n = r+4 $, proves that $\overline{\text{Conv}}(E^{t+1}),$ $\text{Aff}(E^{t+1}) $ and $\operatorname{Ri} (\overline{\operatorname{Conv}}(E^{t+1}) ) $  are $\Delta^1_n (\Omega^t \times \mathfrak{P}(\Omega_{t+1})) $-measurable. So, we also obtain that $E^{t+1}, \, \overline{\operatorname{Conv}}(E^{t+1}), \operatorname{Aff}(E^{t+1})$ and $\operatorname{Ri} (\overline{\operatorname{Conv}}(E^{t+1}) ) $  are $ \mathbf{P}(\Omega^t \times \mathfrak{P}(\Omega_{t+1}))$-measurable. \\
{\it Proof of (ii).}\\
Let     $P:= q_1 \otimes \dots \otimes q_T \in \mathcal{Q}^T.$ Recalling Remark~\ref{EP_included_D}, then for all $t\in \{1,\dots,T-1\}$ and $\omega^t\in \Omega^t$, $D^{t+1}_P(\omega^t)=E^{t+1}(\omega^t,q_{t+1}(\cdot\mid \omega^t))$.
We have that
\begin{align*}
    \big\{ \omega^t\in  \Omega^t: \ D^{t+1}_P (\omega^t) \cap O \neq \emptyset \big\} 
    &= \big\{ \omega^t \in  \Omega^t: \ \exists p \in \mathfrak{P}(\Omega_{t+1}), \ q_{t+1}(\cdot| \omega^t) = p, \ E^{t+1} (\omega^t, p) \cap O \neq \emptyset \big\} \\
    %&= \text{proj}_{\Omega^t} \Big\{ (\omega^t, p): \ q_{t+1}(\cdot| \omega^t) = p, \ E^{t+1} (\omega^t, q) \cap O \neq \emptyset\Big\} \\
    &= \text{proj}_{\Omega^t} \Bigl[A \cap \big\{ (\omega^t, p) \in \Omega^t \times \mathfrak{P}(\Omega_{t+1}): \ q_{t+1}(\cdot| \omega^t) = p\big\}\bigr].
\end{align*}
As $q_{t+1} \in SK_{t+1}$ and $p \in \mathfrak{P}(\Omega_{t+1}),$ we have that $\Omega^t \times \mathfrak{P}(\Omega_{t+1})  \ni (\omega^t, p) \mapsto q_{t+1}(\cdot| \omega^t) - p \in \mathfrak{P}(\Omega_{t+1})$ is 
$\mathbf{P}(\Omega^t \times \mathfrak{P}(\Omega_{t+1})) $-measurable, see Proposition \ref{prop_properties_projective_functions} (iv) and (viii), and thus 
$\Delta^1_{n\rq{}} (\Omega^t \times \mathfrak{P}(\Omega_{t+1})) $-measurable for some $n\rq{}\geq 1$. Thus, 
$$A \cap \{ (\omega^t, p) \in \Omega^t \times \mathfrak{P}(\Omega_{t+1}): \ q_{t+1}(\cdot| \omega^t) = p \} \in \Delta^1_{m-1} (\Omega^t \times \mathfrak{P}(\Omega_{t+1})) \subseteq \Sigma^1_{m-1} \bigl(\Omega^t \times \mathfrak{P}(\Omega_{t+1})\bigr), $$ 
where $m=\max(n,n\rq{})+1,$ see Proposition \ref{prop_properties_projective_functions} (i). It follows that 
$$
\big\{ \omega^t\in \Omega^t: \ D^{t+1}_P (\omega^t) \cap O \neq \emptyset \big\} =\text{proj}_{\Omega^t} \Bigl[A \cap \big\{ (\omega^t, p) \in \Omega^t \times \mathfrak{P}(\Omega_{t+1}): \ q_{t+1}(\cdot| \omega^t) = p\big\} \Bigr]\in \Sigma^1_{m-1} (\Omega^t ) \subseteq \Delta^1_{m} (\Omega^t ), 
$$
see Proposition \ref{prop_properties_projective_functions} (ii) and \eqref{eq(v)_pj}. 
So, we have proved the $\Delta^1_{m} (\Omega^t) $-measurability of $D^{t+1}_P $. Similarly, by \cite[Proposition 14.2, Exercise 14.12]{RockafellarWets1998} and \cite[Lemmata 5.2 and 5.7]{Artstein}, but this time in the measurable space $(\Omega^t , \Delta^1_{m} (\Omega^t)) $, we obtain that $\overline{\operatorname{Conv}}(D^{t+1}_P), \operatorname{Aff}(D^{t+1}_P)$ and $\operatorname{Ri} (\overline{\operatorname{Conv}}(D^{t+1}_P) )$ 
are $\Delta^1_{m} (\Omega^t) $-measurable, and thus $\mathbf{P}(\Omega^t) $-measurable.\\
{\it Proof of (iii).}\\
Proposition 12 in \cite{CF24} proves that there exists $q \geq 1 $ such that $D^{t+1} $ is $\Delta^1_{q} (\Omega^t) $-measurable. So again, applying \cite[Proposition 14.2, Exercise 14.12]{RockafellarWets1998} and \cite[Lemmata 5.2 and 5.7]{Artstein} in the measurable space $(\Omega^t , \Delta^1_{q} (\Omega^t)) $, we get that  
$\overline{\operatorname{Conv}}(D^{t+1}), $  $\operatorname{Aff}(D^{t+1}) $ and $\operatorname{Ri} (\overline{\operatorname{Conv}}(D^{t+1}) )$ are $\Delta^1_{q} (\Omega^t) $-measurable, and thus $\mathbf{P}(\Omega^t) $-measurable.

