\subsection{Section of jointly measurable sets}

Let $\Omega$ and $\tilde{\Omega}$ be two Polish spaces and suppose that the set-valued mapping $\mathcal{P} : \Omega \twoheadrightarrow \mathfrak{P}(\tilde{\Omega})$ is nonempty-valued. Recall that $SK$ is the set of stochastic kernels such that $q(\cdot \mid \omega)$ is a probability measure in $\mathfrak{P}(\tilde{\Omega})$ for all $\omega \in \Omega$ and $\Omega \ni \omega \mapsto q(\cdot \mid \omega) \in \mathfrak{P}(\tilde{\Omega})$ is projectively measurable.  Let  $\mathcal{R} \subseteq \mathfrak{P}(\Omega)$, we set

\[
\mathcal{Q} := \bigl\{ R \otimes q  : \, R \in \mathcal{R}, \, q \in SK,  \, q(\cdot \mid \omega) \in \mathcal{P}(\omega) \; \forall \omega \in \Omega \bigr\}.
\]

In the quasi-sure literature, it is necessary to prove that if  $\Xi:\Omega \times \tilde{\Omega}\to \mathbb{R}$ satisfies $\Xi \geq 0$ $ \mathcal{Q}$-q.s., then there exists some $\mathcal{R}$-full measure set, with the right measurability, such that for all $\o$ in this set, $\Xi(\o,\cdot) \geq 0$ $ \mathcal{P}(\o)$-q.s. This is Corollary \ref{corollary_section_B_omega}. It is based on Lemma \ref{lemma_section_B_omega}, which generalizes Lemma A.1 of \cite{Carassus25} to the projective setup. The proofs are very similar. The main difference is in the proof of the measurability of $\lambda$, which is simpler in the projective setup. 

\begin{lemma}[Section of jointly measurable sets] \label{lemma_section_B_omega}
    Assume the (PD) axiom. Assume that $Graph(\mathcal{P})\in \mathbf{P}(\Omega \times \tilde{\Omega})$.
    Fix $\bar{B} \in \mathbf{P}(\Omega \times \tilde{\Omega})$. For $\omega \in \Omega$, we denote by $\bar{B}_{\omega}$ the section of $\bar{B}$ along $\omega$, that is

    \[\bar{B}_{\omega} := \{\tilde{\omega} \in \tilde{\Omega} : (\omega, \tilde{\omega}) \in \bar{B}\}.\] 

    Then, we have \[B := \bigl\{ \omega \in \Omega : q[\bar{B}_{\omega}] = 1, \, \forall q \in \mathcal{P}(\omega) \bigr\} \in \mathbf{P}(\Omega).\]  
If furthermore $\bar{B}$ is a $\mathcal{Q}$-full measure set, then $B$ is a $\mathcal{R}$-full measure set.
\end{lemma}































\begin{proof}
Remark that $B = \{ \Lambda \geq 1 \}$, where

\[
    \Lambda(\omega) := \inf_{q \in \mathcal{P}(\omega)} q[\bar{B}_\omega].
\]

First, we prove that $\Lambda$ is $\mathbf{P}(\Omega)$-measurable. 
For that, we define,
\[
 %\Omega \times \mathcal{P}(\tilde{\Omega}) \ni
\Omega \times \mathcal{P}(\tilde{\Omega}) \ni      (\omega, q) \mapsto \lambda(\omega, q) := q[\bar{B}_\omega]=\int_{\tilde{\Omega}} \mathbf{1}_{\bar{B}_\omega}(\tilde{\omega}) q(d\tilde{\omega}).
\]
We have that the function $(\omega, q, \tilde{\omega}) \mapsto \mathbf{1}_{\bar{B}_\omega}(\tilde{\omega}) = \mathbf{1}_{\bar{B}}(\omega, \tilde{\omega}) $ is 
$\mathbf{P}(\Omega \times \mathfrak{P}(\tilde{\Omega}) \times \tilde{\Omega}) $-measurable using that $\bar{B} \in \mathbf{P}(\Omega \times \tilde{\Omega}) $ and 
Proposition \ref{prop_properties_projective_functions} (viii).
Let $p(\cdot|\cdot) : \mathcal{B}(\tilde{\Omega}) \times (\Omega \times \mathcal{P}(\tilde{\Omega})) $ be defined by  
$p(A | (\omega, q)) = q[A] $ for all $A \in \mathcal{B}(\tilde{\Omega}) $ and $(\omega, q) \in \Omega \times \mathcal{P}(\tilde{\Omega}) $.  
As $p(\cdot | (\omega, q)) = q[\cdot]$ is a probability measure on $\tilde{\Omega} $ and $(\omega, q) \mapsto p(\cdot | (\omega, q)) = q[\cdot] $ is Borel measurable 
%(see \cite[Proposition 7.25]{Bertsekas1978}), 
and thus projectively measurable,  we obtain that $q \in SK $.
Recalling that $((\omega, q), \tilde{\omega}) \mapsto \mathbf{1}_{\bar{B}_\omega}(\tilde{\omega})$ is projectively measurable,  we conclude by Proposition \ref{prj_cvt_pj} that the function $(\omega, q) \mapsto \lambda(\omega, q)$ is $\mathbf{P}(\Omega \times \mathcal{P}(\tilde{\Omega}))$-measurable. For any $c \in \mathbb{R}$, we define:


\[E_c := \{ (\omega, q) \in \Omega \times \mathfrak{P}(\tilde{\Omega}) : \lambda(\omega, q) < c \} \cap \operatorname{Graph} \mathcal{P}.\]
Then, $E_c \in \mathbf{P}(\Omega \times \mathcal{P}(\tilde{\Omega}))$, see Proposition~\ref{prop_properties_projective_functions} (ii). 
Moreover, by definition of $\Lambda$ and $E_c$, we obtain that  $\{\Lambda< c \} = \operatorname{proj}_{\Omega} E_c $. Now, Proposition~\ref{prop_properties_projective_functions} (ii) again shows that $\operatorname{proj}_{\Omega} E_c \in \mathbf{P}(\Omega)$, and we conclude that $\Lambda$ is $\mathbf{P}(\Omega)$-measurable. So, $B = \{ \Lambda \geq 1 \} \in \mathbf{P}(\Omega)$.

Assume now that $\bar{B}$ is a $\mathcal{Q}$-full measure set. We prove that $B$ is a $\mathcal{R}$-full measure set.
Assume by contradiction that there exists $\tilde{R} \in \mathcal{R}$ such that $\tilde{R}[\Omega \setminus B] > 0$. 

Since $E_1 \in \mathbf{P}(\Omega \times \mathcal{P}(\tilde{\Omega})) $, we can perform measurable selection on $E_1 $ using Proposition~\ref{prop_conseq_PD_axiom}.  
So, there exists a projectively measurable stochastic kernel $\hat{q} : \operatorname{proj}_\Omega E_1 \to \mathcal{P}(\tilde{\Omega}) $, such that  
$(\omega, \hat{q}(\cdot| \omega)) \in E_1 $ for all $\omega \in \operatorname{proj}_\Omega E_1 =\{ \Lambda <1 \} =\Omega \setminus B $. 
Since $\operatorname{proj}_\Omega \operatorname{Graph}(\mathcal{P}) = \Omega $ and $\operatorname{Graph}(\mathcal{P}) \in \mathbf{P}(\Omega \times \tilde{\Omega}) $, we can also perform measurable selection on $\operatorname{Graph}(\mathcal{P}) $ using again Proposition~\ref{prop_conseq_PD_axiom},  
proving the existence of a projectively measurable stochastic kernel $\bar{q} $ such that for all $\omega \in \Omega $, $\bar{q}(\cdot \mid \omega) \in \mathcal{P}(\omega) $. We set:



\[
    \tilde{q}(\cdot| \omega) := \hat{q}(\cdot| \omega) \mathbf{1}_{\Omega \setminus B} + \bar{q}(\cdot| \omega) \mathbf{1}_B.
\]


We have that $\tilde{q} \in \mathcal{SK}$. Indeed, since $\bar{q}(\cdot|\omega )$ and $\hat{q}(\cdot|\omega ) $ are both probability measures on $\tilde{\Omega}$, $\tilde{q}(\cdot|\omega) $ is also a probability measure. Moreover,  as  $\omega \mapsto \hat{q}(\cdot|\omega) $ and $\omega \mapsto \bar{q}(\cdot| \omega) $ are projectively measurable, and $B, \Omega \setminus B \in \mathbf{P}(\Omega) $, we have that $\omega \mapsto \tilde{q}(\cdot| \omega) $ is projectively measurable, see Proposition~\ref{prop_properties_projective_functions} (ii) and (v). Moreover, as for $\omega \in \Omega \setminus B$, $(\omega, \hat{q}(\cdot| \omega)) \in E_1 \subseteq \operatorname{Graph}(\mathcal{P})$, we conclude that $\tilde{q}(\cdot| \omega) \in \mathcal{P}(\omega)$ for all $\omega \in \Omega$ and that $\tilde{R} \otimes \tilde{q} \in \mathcal{Q}$. Now, we have

\begin{align*}
    \tilde{R} \otimes \tilde{q}[\bar{B}] 
    &= \int_B \int_{\tilde{\Omega}} \mathbf{1}_{\bar{B}}(\omega, \tilde{\omega}) \bar{q}(d\tilde{\omega}|\omega) \tilde{R}(d\omega) 
    + \int_{\Omega \setminus B} \hat{q}(\bar{B}_\omega| \omega) \tilde{R}(d\omega) \\
    &\leq \tilde{R}[B] + \int_{\Omega \setminus B} \lambda(\omega, \hat{q}(\cdot| \omega)) \tilde{R}(d\omega) \\
    &< \tilde{R}[B] + \tilde{R}[\Omega \setminus B] = 1.
\end{align*}


as for all $\omega \in \Omega \setminus B$, $(\omega, \hat{q}(\cdot| \omega)) \in E_1 \subseteq \{ \lambda < 1 \}$ and $\tilde{R}[\Omega \setminus B] > 0$. This contradicts the fact that $\bar{B}$ is of $\mathcal{Q}$-full measure, and we conclude that $B$ is a $\mathcal{R}$-full measure set. 

\end{proof}


\begin{corollary}[From global to local positivity]\label{corollary_section_B_omega}
    Assume the (PD) axiom. Assume that $Graph(\mathcal{P})\in \mathbf{P}(\Omega \times \tilde{\Omega})$. Let $\Xi:\Omega \times \tilde{\Omega}\to \mathbb{R}$ be a projective function. Then, there is an equivalence between:
    \begin{enumerate}
        \item[(i)]  $\Xi\geq0 \; \mathcal{Q}\mbox{-q.s.}$ 
        \item[(ii)]  There exists a projective set of $\mathcal{R}$-full-measure  $\bar{\Omega}\subseteq{\Omega}$, such that for all $\omega\in\bar{\Omega}$, $\Xi(\omega,\cdot) \geq 0 \; \mathcal{P}(\omega)\mbox{-q.s.}$
    \end{enumerate}
\end{corollary}

\begin{proof}
    To show that (i) implies (ii), we apply  Lemma~\ref{lemma_section_B_omega} to $\bar{B} = \{\Xi \geq 0\}$ and choose $\bar{\Omega}=B$. The reverse implication is obtained by Fubini\rq{}s theorem.
\end{proof}

