\section{Weak-coupling derivation of interaction-picture map}\label{app:expansion}

In this appendix, we provide a step-by-step derivation of the Lindblad form of the interaction-picture map, by keeping leading order terms in the weak-coupling expansion. While the derivation mirrors standard ones in the open systems literature \cite{lidar2019lecture}, the derivation for discrete-time processes is uncommon and we reproduce it here for completeness. 

The interaction-picture map was defined in Eq.~(\ref{eq:interactionmapdef}) in the main text. We expand the unitary $\tilde{\mathcal{Q}}$ entering the interaction-picture map to second order: 
\begin{gather}
\tilde{\mathcal{Q}} = \tilde{U}_{\theta,M_T}\ldots\tilde{U}_{\theta,0}\ldots \tilde{U}_{\theta,-M_T} \nonumber \\
= 1-i\theta\delta \sum_{\tau=-M_T}^{M_T} \tilde{V}_{\tau} -\frac{\theta^2\delta^2}{2}\sum_{\tau=-M_T}^{M_T}\tilde{V}_{\tau}^2 - \theta^2\delta^2\sum_{\tau={-M_T}}^{M_T} \sum_{\tau'=-M_T}^{\tau-1} \tilde{V}_{\tau}\tilde{V}_{\tau'} \nonumber \\
= 1-i\theta\delta\sum_{\tau=-M_T}^{M_T} \tilde{V}_{\tau} - \frac{\theta^2\delta^2}{2} \sum_{\tau,\tau'=-M_T}^{M_T} \mathcal{T}(\tilde{V}_{\tau}\tilde{V}_{\tau'}).
\end{gather}
In the last line we introduced the discrete-time time-ordering operator $\mathcal{T}$ which is defined (along with the anti time-ordering operator $\mathcal{T}^*$) by:
\begin{equation}
    \mathcal{T}(O_\tau O_{\tau'}) = \begin{cases}
        O_\tau O_{\tau'} & \tau > \tau' \\
        O_{\tau'} O_{\tau} & \tau \leq \tau'. 
\end{cases}
\hspace{1cm}
    \mathcal{T}^*(O_\tau O_{\tau'}) = \begin{cases}
        O_\tau O_{\tau'} & \tau \leq \tau' \\
        O_{\tau'} O_{\tau} & \tau > \tau'.
\end{cases}
\end{equation}
Substituting into the definition of the interaction-picture map, and observing that the linear term in $\theta$ vanishes due to $\text{tr}\big(\tilde V_\tau \hat \Phi\big) = 0$, we arrive at the second-order map
\begin{equation}\label{eq:interaction_expansion}
    \tilde{\mathcal{E}}(\hat\rho) \approx \hat\rho +\theta^2 \delta^2\sum_{\tau,\tau'=-M_T}^{M_T}\bigg[\text{tr}_B\Big(\tilde{V}_{\tau'}[\hat\rho\otimes\hat\Phi]\tilde{V}_{\tau}\Big) - \text{tr}_B\Big(\mathcal{T}(\tilde{V}_{\tau}\tilde{V}_{\tau'})[\hat\rho\otimes\hat\Phi]\Big) - \text{tr}_B\Big([\hat\rho\otimes\hat\Phi]\mathcal{T}^*(\tilde{V}_{\tau'}\tilde{V}_{\tau})\Big) \bigg].
\end{equation}
We now use the bath correlation function 
\begin{equation}
    \text{tr}_B( \tilde Y_{\mu,\tau}\tilde Y_{\mu',\tau'} \hat\Phi) = \delta_{\mu,\mu'}e^{ih\delta(\tau'-\tau)}
\end{equation}
and the definition of $V_\tau$ (Eq.~\ref{eq:Vdef}) to write 
\begin{gather}
    \text{tr}_B(\tilde V_{\tau}\tilde V_{\tau'} \hat\Phi) = f_\tau f_{\tau'}e^{ih\delta(\tau'-\tau)} \sum_{\mu=1}^{N_B}\tilde A_{\mu,\tau}\tilde A_{\mu,\tau'}.
\end{gather}
This equation takes a more familiar form after introducing the jump operators
\begin{equation}\label{eq:Lderivation}
    \hat L_\mu = \delta\sum_{\tau = -M_T}^{M_T} f_\tau e^{ih\delta\tau} \tilde A_{\mu,\tau}.
\end{equation}
The first term entering the square brackets in Eq.~(\ref{eq:interaction_expansion}) then becomes $\sum_\mu \hat L_\mu \hat\rho L_\mu$. The time-ordered term can be decomposed into Hermitian and anti-Hermitian parts with the Hermitian matrices $\hat K$ and $\hat G^{\text{LS}}$:
\begin{equation}
    \hat J = \delta^2\sum_{\tau,\tau'=-M_T}^{M_T}\text{tr}_B\Big(\mathcal{T}(\tilde{V}_{\tau}\tilde{V}_{\tau'})\hat\Phi\Big) \equiv \hat K + i\hat G^{\text{LS}}.
\end{equation}
The new matrix $\hat K$ is given by 
\begin{gather}
    \hat K = \frac{\delta^2}{2}\sum_\mu\bigg( \sum_{\tau=-M_T}^{M_T} f_\tau^2(\tilde{A}_{\tau,\mu})^2 + \sum_{\tau = -M_T}^{M_T} \sum_{\tau'={-M_T}}^{\tau-1}\Big( e^{ih\delta(\tau'-\tau)}f_\tau f_{\tau'} \tilde{A}_{\tau,\mu}\tilde{A}_{\tau',\mu}+e^{ih\delta(\tau-\tau')}f_\tau f_{\tau'} \tilde{A}_{\tau',\mu}\tilde{A}_{\tau,\mu}\Big) \bigg) \nonumber \\
    % = \frac{1}{2}\sum_\mu\bigg( \sum_{\tau=-M_T}^{M_T} f_\tau^2(\tilde{A}_{\tau,\mu})^2 + \bigg(\sum_{\tau = -M_T}^{M_T} \sum_{\tau'={-M_T}}^{\tau-1}+\sum_{\tau' = -M_T}^{M_T} \sum_{\tau={-M_T}}^{\tau-1}\bigg) e^{ih(\tau'-\tau)}f_\tau f_{\tau'} \tilde{A}_{\tau,\mu}\tilde{A}_{\tau',\mu}\bigg) \nonumber \\
    = \frac{\delta^2}{2}\sum_\mu\bigg( \sum_{\tau=-M_T}^{M_T} f_\tau^2(\tilde{A}_{\tau,\mu})^2 + \bigg(\sum_{\tau = -M_T}^{M_T} \sum_{\tau'={-M_T}}^{\tau-1}+\sum_{\tau = -M_T}^{M_T} \sum_{\tau'={\tau}+1}^{M_T}\bigg) e^{ih\delta(\tau'-\tau)}f_\tau f_{\tau'} \tilde{A}_{\tau,\mu}\tilde{A}_{\tau',\mu}\bigg) \nonumber \\
    = \frac{\delta^2}{2}\sum_\mu\sum_{\tau',\tau=-M_T}^{M_T}e^{ih\delta(\tau'-\tau)}f_\tau f_{\tau'} \tilde{A}_{\tau,\mu}\tilde{A}_{\tau',\mu} \nonumber \\
    = \frac{1}{2}\sum_\mu \hat L^\dagger_\mu \hat L_\mu.
    \label{eq:Kderivation}
\end{gather}
In going from the first to the second line, we performed a change of variable $\tau \leftrightarrow \tau'$, and used $\sum_{\tau} \sum_{\tau' < \tau} = \sum_{\tau'}\sum_{\tau>\tau'}$. 

The matrix $\hat G^{\text{LS}}$ is given by 
\begin{gather}
    \hat G^{\text{LS}} = \frac{\delta^2}{2i}\sum_\mu \sum_{\tau = -M_T}^{M_T} \sum_{\tau'={-M_T}}^{\tau-1}\Big( e^{ih\delta(\tau'-\tau)}f_\tau f_{\tau'} \tilde{A}_{\tau,\mu}\tilde{A}_{\tau',\mu}-e^{ih\delta(\tau-\tau')}f_\tau f_{\tau'} \tilde{A}_{\tau',\mu}\tilde{A}_{\tau,\mu}\Big)  \nonumber \\ 
    = \frac{\delta^2}{2i}\bigg(\sum_{\tau = -M_T}^{M_T} \sum_{\tau'={-M_T}}^{\tau-1}-\sum_{\tau = -M_T}^{M_T} \sum_{\tau'={\tau}+1}^{M_T}\bigg) e^{ih\delta(\tau'-\tau)}f_\tau f_{\tau'} \tilde{A}_{\tau,\mu}\tilde{A}_{\tau',\mu} \nonumber \\ 
    = \frac{\delta^2}{2i}\sum_{\tau,\tau' = -M_T}^{M_T} \text{sgn}(\tau-\tau')e^{ih\delta(\tau'-\tau)}f_\tau f_{\tau'} \tilde{A}_{\tau,\mu}\tilde{A}_{\tau',\mu},
    \label{eq:GLSderivation}
\end{gather}
where the sign function is defined with $\text{sgn}(0)=0$. The anti-time-ordered term is given by 
\begin{equation}
    \hat J^\dagger = \delta^2\sum_{\tau,\tau'=-M_T}^{M_T}\text{tr}_B\Big(\mathcal{T}^*(\tilde{V}_{\tau}\tilde{V}_{\tau'})\hat\Phi\Big) \equiv \hat K - i\hat G^{\text{LS}}.
\end{equation}

Combining Eqs.~(\ref{eq:Lderivation}, \ref{eq:Kderivation}, \ref{eq:GLSderivation}) we arrive at the Lindblad form given in the main text, Eq.~(\ref{eq:lindblad}):
\begin{equation}
        \frac{\tilde{\mathcal{E}}(\hat\rho)-\hat{\rho}}{\theta^2} = -i[\hat G^{\text{LS}}, \hat\rho]+ \{\hat K,\hat\rho\}+\sum_\mu \hat L_\mu \hat\rho\hat L_\mu^\dagger.
\end{equation}
It is interesting to note that our Lindblad equation has the same form as the so-called `Universal Lindblad Equation', derived in an attempt to restore complete positivity to the Redfield equation \cite{nathan2020universal}. In that case, the `filter function' in the frequency domain enters as the square root of the bath spectral function, $\bar f(\omega) = \sqrt{J(\omega)}$. We leave a detailed investigation of the equivalence between the two to future work. 

\section{Approximations in replacing jump operators with operator Fourier transforms}\label{app:fourier}

The jump operators in Eq.~(\ref{eq:Lderivation}) were derived for the digital channel with a finite reset time $M_T$. For analytical purposes it is convenient to replace this expression with the continuous-time operator Fourier transform, 
\begin{equation}\label{eq:jump_continuous2}
    \hat L_\mu = \int_{-\infty}^\infty dt\ f(t) e^{iht} \tilde A_\mu(t),
\end{equation}
and similarly for the Lamb-shift 
\begin{equation}\label{eq:Lambshift_continuous2}
    \hat G^{\text{LS}} = \frac{1}{2i}\sum_\mu \iint_{-\infty}^\infty dtdt'\ \text{sgn}(t-t')f(t)f(t') e^{ih(t'-t)} \hat A^\dagger_{\mu}(t)\hat A_{\mu}(t').
\end{equation}
The error in this substitution is controlled by the smallness of the two parameters, $\xi_T = 1/aT$, $\xi_\delta = a\delta$, as we show here. Let 
\begin{equation}
    \hat L(M_T, \delta) = \delta\sum_{\tau = -M_T}^{M_T} f_\tau e^{ih\delta\tau} \tilde A_{\tau}.
\end{equation}
First we show the bound 
\begin{equation}
    \| \hat L(M_T,\delta) - \hat L(\infty,\delta)\| \leq 2(aN)^{-1}\|\hat A\| \frac{e^{-T^2a^2/2}}{aT},
\end{equation}
with $N$ the filter function normalisation ($N\sim a^{-1}$):
\begin{gather}
\| \hat L(M_T,\delta) - \hat L(\infty,\delta)\| = 
    \Big\| \delta \sum_{\tau={M_T+1}}^\infty (f_\tau e^{ih\delta\tau}\tilde A_{\tau} +f_{-\tau} e^{-ih\delta\tau}\tilde A_{-\tau})\Big\| \nonumber \\
    \leq 2N^{-1}\|\hat A\| \Big\|\delta \sum_{\tau=M_T+1}^\infty e^{-\delta^2a^2\tau^2/2}\Big \| \nonumber \\
    \leq 2N^{-1}\|\hat A\|\int_T^\infty dt \ e^{-a^2 t^2/2} = \sqrt{2\pi} (aN)^{-1} \|\hat A\| \text{erfc}\bigg(\frac{aT}{\sqrt{2}}\bigg),
\end{gather}
where $T=\delta M_T$, $\text{erfc(x)}$ is the complementary error function, and we used the fact that the Gaussian is monotonically decreasing for $\tau>0$, hence the sum can be bounded by the integral. The error function satisfies the known bound 
\begin{equation}
    \text{erfc}(x) \leq \frac{e^{-x^2}}{x\sqrt{\pi}},
\end{equation}
leading to 
\begin{equation}
    \| \hat L(M_T,\delta) - \hat L(\infty,\delta)\| \leq 2(aN)^{-1}\|\hat A\| \frac{e^{-T^2a^2/2}}{aT}.
\end{equation}

Next, we consider the frequency domain decomposition of $\hat L$,
\begin{equation}
    \hat L(\infty,\delta) = \delta\sum_{\tau = -\infty}^{\infty} f_\tau e^{ih\delta\tau} \tilde A_{\tau} = \sum_\omega \hat A_\omega \bigg(\delta \sum_{\tau=\infty}^\infty f_\tau e^{i(h-\omega)\delta\tau}\bigg). 
\end{equation}
Using the Poisson summation formula \cite{ding2024single} we can replace the infinite time sum with a sum over shifted copies of the continuous-time Fourier transform of the filter function:
\begin{equation}
    \delta \sum_{\tau=\infty}^\infty f_\tau e^{-i\omega\delta\tau} = \sum_{k=-\infty}^\infty \bar{f}(\omega - 2\pi k/\delta),
\end{equation}
where $\bar f(\omega) = e^{-\omega^2/2a^2}$. Restricting to the range $\omega \delta \ll \pi$, which defines the prethermal regime we work in, the error from keeping only the $k=0$ term in the above sum is of the order $\mathcal{O}(e^{-\pi^2/2\xi_\delta^2})$. Combining the two approximations above, we can replace $\hat L(M_T,\delta)$ with $\hat L(\infty,0)$ (Eq.~(\ref{eq:jump_continuous2})). 
A similar analysis may be performed for the Lamb-shift term. This gives the final integral-form operators appearing in Eqs.~(\ref{eq:jump_continuous}, \ref{eq:Lambshift_continuous}), and the error involved in these replacements in exponentially small in the parameters $\xi_T$ and $\xi_\delta$.


\section{Explicit form for the Lamb-shifts}\label{app:Lamb}

Here we derive an explicit formula for the Lamb-shift Hamiltonian, $\hat G^{\text{LS}}$, which can be expressed in terms of the error-function, and compare to the detailed balance function $\hat G^{\text{DB}}$.

To simplify notation we consider a single auxiliary spin, $\hat A_\mu \equiv \hat A$, and work with the continuous time formula given in Eq.~(\ref{eq:Lambshift_continuous2}). We first decompose $\hat A = \sum_\omega \hat A_{\omega}$ in terms of cooling transitions of frequency $\omega$, such that $\hat A(t) = \sum_\omega \hat A_{\omega}e^{-i\omega t}$. The Lamb-shift is 
\begin{equation}
    \hat G^{\text{LS}} = \sum_{\omega,\omega'} \hat A^\dagger_\omega \hat A_{\omega'} K^{\text{LS}}(\omega,\omega'),
\end{equation}
with the kernel
\begin{gather}
    K^{\text{LS}}(\omega,\omega') = \frac{1}{2i}\iint _{-\infty}^\infty dt dt'\ \text{sgn}(t-t') e^{i[(\omega-h)t-(\omega'-h)t']}f(t)f(t'). 
\end{gather}
Using the Fourier transform of $\text{sgn}(t-t')$, we can write this as a standard principal value integral 

\begin{gather}
    K^{\text{LS}}(\omega,\omega') = \mathcal{P}\int \frac{d\nu}{2\pi \nu} \bar f_h(\omega-\nu) \bar f_h(\omega'-\nu).
\end{gather}
For our choice of Gaussian filter function, $\bar f$ restricts $\omega $ to the range $\omega \approx h+\nu \pm \mathcal{O}(a)$ within the integral; in turn, this restricts the kernel to be finite only when $|\omega-\omega'| \lesssim \mathcal{O}(a)$. To see this explicitly, we may factor
\begin{gather}
    K^{\text{LS}}(\omega,\omega') = \frac{1}{2\pi}\int \frac{d\nu}{\nu-h} e^{-(\omega - \nu)^2/2a^2}e^{-(\omega' - \nu)^2/2a^2} \nonumber \\ 
    = \frac{e^{-(\omega-\omega')^2/4a^2}}{2\pi} \int \frac{d\nu}{\nu+\bar{\omega}-h}e^{-\nu^2/a^2},
\end{gather}
where we defined $\bar{\omega} = \frac{\omega+\omega'}{2}$. The latter integral is the Hilbert transform of a Gaussian, which has a known solution:
\begin{equation}\label{eq:LSkernel}
    K^{\text{LS}}(\omega,\omega') = \frac{1}{\sqrt{\pi}} e^{-(\omega-\omega')^2/4a^2} F\bigg(\frac{\bar{\omega}-h}{a}\bigg).
\end{equation}
The function
\begin{equation}
    F(x) = \frac{\sqrt{\pi}}{2i} e^{-x^2} \text{erf}(ix),
\end{equation}
is a real-valued antisymmetric function known as Dawson's function, and erf is the error function. The main points to note are that $F(x) \approx \frac{1}{2x}$ for large $x$, and $F(x) \approx x$ for small $x$. In total, Eq.~(\ref{eq:LSkernel}) shows that the Lamb-shift kernel is a real-valued function which is symmetric in the argument $\omega-\omega'$, and suppressed as a Gaussian of width $2a$ for large $|\omega-\omega'|$.   

This can be compared to the kernel of the Hamiltonian required for exact detailed balance, derived in Eq.~(\ref{eq:trueLamb}), 
\begin{gather}
    K^{\text{DB}}(\omega,\omega') 
    = i \tanh\bigg(\frac{\beta(\omega-\omega')}{4}\bigg) e^{-(\omega-\omega')^2/4a^2} e^{-(\bar{\omega}-h)^2/a^2}.
\end{gather} 
In contrast to (\ref{eq:LSkernel}), $K^{\text{LS}}$ is an imaginary function, antisymmetric in $\omega - \omega'$, but with the same Gaussian decay for large values of the argument $\omega-\omega'$. The difference between the Lamb-shifts, $\Delta\hat G$, can be written as 
\begin{equation}
    \Delta\hat G = \sum_{\omega,\omega'}\hat A^\dagger_\omega\hat A_{\omega'} \Delta K(\omega,\omega'),
\end{equation}
where
\begin{equation}\label{eq:DeltaKdef}
    \Delta K(\omega,\omega') = 2e^{-(\omega-\omega')^2/4a^2}y(\omega,\omega'),
\end{equation}
and
\begin{equation}
    y(\omega,\omega') =\frac{1}{2\sqrt{\pi}}F\bigg(\frac{\bar{\omega}-h}{a}\bigg)-\frac{i}{2}\tanh\bigg(\frac{\beta(\omega-\omega')}{4}\bigg)e^{-(\bar{\omega}-h)^2/a^2}
\end{equation}
is a function satisfying $|y(\omega,\omega')|\leq 1$. Although the matrix element $\Delta\hat G_{ab}$ involves an internal summation over intermediate states which is difficult to bound, we expect the behaviour at large $\omega_{ab}$ is dominated by the Gaussian suppression in Eq.~(\ref{eq:DeltaKdef}).

\section{Hamiltonian renormalisation}\label{app:renormalisation}

The corrections to the Gibbs state derived in Section \ref{sec:thermal} were derived using standard perturbation theory around the Gibbs state in the Schrödinger picture. In this appendix, we show how the same formulas can be obtained through an alternative method, guided by the following intuition: on physical grounds, we expect that the presence of the bath modifies (`renormalises') the bare system Hamiltonian (leading to e.g.~level shift phenomena known from atomic theory \cite{cohen2024photons}), hence there is no reason to expect exact thermalization into the Gibbs state set by $\hat H_S$ \cite{trushechkin2022open}. While detailed balance is therefore broken in the interaction picture with respect to the \emph{bare} Hamiltonian, it may be that it is restored in the interaction frame with respect to a \emph{renormalised} Hamiltonian, $\hat H'_S$.  We show below that this intuition is correct, and that the renormalised system Hamiltonian can be solved for self-consistently at second order in the coupling $\theta$.

We define the renormalised Hamiltonian with the correction expanded in powers of the system-bath coupling
\begin{equation}\label{eq:renormalisedH}
    \hat H'_S = \hat H_S + \theta^2 \hat C, \hspace{1cm} \hat C = \sum_{k=0}^\infty \theta^{2k} \hat C_k,
 \end{equation}
 where $\hat C$ is an operator acting only on the system Hilbert space. We assume throughout that the Trotter angle is small such that 
 \begin{equation}
     e^{-i\delta\theta^2\hat C} e^{-i\delta \hat H_S} \approx e^{-i\delta\hat H'_S} \equiv U_S'.
 \end{equation}
Then, by making use of the identities 
\begin{equation}
\mathcal{U_\tau} = e^{-i\delta\theta\hat V_{\tau}} e^{i\delta\theta^2\hat C}e^{-i\delta \hat H_B} e^{-i\delta\theta^2\hat C}e^{-i\delta\hat H_S} = e^{-i\delta\theta \hat V_{\tau}}e^{i\delta\theta^2\hat C}U_B U'_S,
\end{equation}
\begin{equation}
    \mathcal{R} = \prod_{\tau = 1}^{M_R} e^{-i\delta\tau \hat H_S} = \prod_{\tau = 1}^{M_R} e^{i\delta \theta^2\hat C}U'_S
\end{equation}
we define the interaction picture with respect to the renormalised Hamiltonian as 
\begin{equation}
    \breve{O}_\tau = Y_0^{-\tau} (O_\tau)Y_0^\tau,, \hspace{.5cm} Y_0 = U_B U'_S,
\end{equation}
and $\breve{\mathcal{Q}} = U^{\prime - M_R}_SY_0^{-M_T} \mathcal{Q}Y_0^{-(M_T+1)}$. The Schrödinger map is then written in the form 
\begin{gather}
    \mathcal{E}(\hat \rho) = 
    \mathcal{S'}^{M_T+M_R} \circ\breve{\mathcal{E}}\circ\mathcal{S'}^{M_T+1}(\hat\rho),
\end{gather}
\begin{equation}
    \mathcal{S'}(\hat\rho) = U'_S(\hat\rho)U^{\prime-1}_S, \hspace{1cm}
    \breve{\mathcal{E}}(\rho) = \text{tr}_B\big[ {\breve{Q}}(\hat \rho\otimes \hat \Phi)\breve{Q}^{\dagger}\big].
\end{equation}


The weak-coupling derivation follows the same steps as laid out in Appendix \ref{app:expansion}. The only difference at leading order in $\theta$ is the appearance of an additional coherent term:
\begin{equation}\label{eq:lindblad_rn}
    \frac{\breve{\mathcal{E}}(\hat\rho)-\hat{\rho}}{\theta^2} = -i[\hat G^{\text{LS}}-\hat G^C, \hat\rho]+ \{\hat K,\hat\rho\}+\sum_\mu \hat L_\mu \hat\rho\hat L_\mu^\dagger,
\end{equation}
where 
\begin{equation}
    \hat G^C = \delta \sum_{\tau=-M_T}^{M_T+M_R}\breve{C}_{0,\tau} \approx \int_{-T}^{T+T_R} dt\  \breve{C}_0(t).
\end{equation}

We next seek the frame in which the quantum detailed balance equations are satisfied. Denote by $\phi_a'$ the basis of eigenstates of $H'_S$. The filter function guarantees that Eq.~(\ref{eq:jump_transition1}) holds with the replacement $\phi_a \to \phi'_a$, and hence the dissipative part of Eq.~(\ref{eq:lindblad_rn}) still satisfies QDB. To satisfy QDB for the coherent terms, we require that 
\begin{equation}
    \hat G^{\text{LS}}-\hat G^{\text{DB}}-\hat G^C + \hat \Lambda = 0,
\end{equation}
where $\hat \Lambda$ is a term diagonal in the eigenbasis of $\hat H_S'$. If we can find $\hat C$ such that the above condition is satisfied, then the steady state of the channel $\breve{\mathcal{E}}$ is given by the QDB solution 
\begin{equation}\hat \sigma'_\beta \propto e^{-\beta \hat H'_S}.
\end{equation}
Returning to the Schrödinger picture, $Y_0$ commutes with $\hat \sigma'_\beta$, and therefore $\hat \sigma'_\beta$ is also the \emph{exact} steady state for the cooling channel, $\mathcal{E}(\hat\sigma'_\beta) = \hat\sigma'_\beta$. 

The solution which satisifes QDB is simply found in the basis of eigenstates of $\hat H'_S$. Ignoring for a moment the randomization step and setting $T_R=0$, we have 
\begin{equation}
    (\hat C_0)_{a'b'} = \frac{(\Delta \hat G)_{a'b'}}{\int_{-T}^T dt \ e^{-i\omega'_{ab}t}}+\delta_{ab}\frac{\Lambda_{a}}{2T} = \frac{(\Delta \hat G)_{a'b'}}{2T\text{sinc}(\omega'_{ab}T)} +\delta_{ab}\frac{\Lambda_{a}}{2T},
\end{equation}
where the primes remind us that we are working in the eigenbasis of $\hat H'_S$. Returning to the eigenbasis of $\hat H_S$ requires a non-trivial perturbation expansion. However, since we only require $\hat C_0$ to leading order, we can substitute the original eigenbasis in place above $\phi'_a \to\phi_a$ i.e.~dropping the primes (assuming that the perturbation $\hat C$ did not lead to degeneracy splitting). 

The above expression is problematic due to the resonances at $\omega_{ab}T = k\pi$, as we observed in Section \ref{sec:thermal}. To include the randomization step, we should consider the channel averaged over the random time $T_R$. Note that now both the interaction-picture map and the Schrödinger-picture map depend on $T_R$. The correct average is performed by fixing
\begin{equation}
    \mathbb{E}\ \int_{-T}^{T+T_R} dt\ (U'_S)^{T_R}\breve{C}_0(t)(U_S^{\prime -1})^{T_R} = \mathbb{E}\ (U'_S)^{T_R}
    \Delta\hat G(U_S^{\prime -1})^{T_R},
\end{equation}
which after a little algebra gives
\begin{equation}
    (\hat C_0)_{ab} = \frac{i\omega_{ab}e^{i\omega_{ab}T}}{1-i\omega_{ab}T_0-e^{2i\omega_{ab}T}}(\Delta \hat G)_{ab}+\delta_{ab}\frac{\Lambda_a}{2T+T_0}.
\end{equation}
Redefining $\frac{\hat \Lambda}{2T+T_0} \to \hat\Lambda$, we find the same correction as we derived in Eq.~(\ref{eq:Cdef}) from the Kubo formula. It is unfortunate that the diagonal correction $\hat \Lambda$ remains undefined in this scheme. However, we expect that our approach of solving for the renormalised Hamiltonian by moving to the self-consistent frame satisfying detailed balance could be of use more generally, for example in determining the Hamiltonian of `mean force' which arises from a finite coupling to a macroscopic bath \cite{trushechkin2022open, lee2022perturbative, correa2023potential, timofeev2022hamiltonian}.


